/* DAWAH X — ahmad, অধ্যায় 15 · খণ্ড 15 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][15]=[[2801,2801,"","সেই ছেলে যে তার কাছে প্রার্থনা করেছিল এবং তাকে ক্ষমা করা হয়েছিল, সেই সময় তিনি আমাকে করুণা করে একটা জীবন দিয়েছিলেন । ওকে কেটে দাও।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏زِيَادٌ ‏ ‏أَنَّ ‏ ‏صَالِحًا ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الرَّحِمَ ‏ ‏شُجْنَةٌ ‏ ‏آخِذَةٌ بِحُجْزَةِ الرَّحْمَنِ يَصِلُ مَنْ وَصَلَهَا وَيَقْطَعُ مَنْ قَطَعَهَا ‏","","",""],[2802,2802,"","আমরা একটা ছেলের কথা বলেছিলাম যে আবার ঘুমাতে গিয়েছিল, ঈশ্বর কঠিন-ওন বিশ্বকে উদ্ধার করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ يَعْنِي الْعَطَّارَ ‏ ‏عَنْ ‏ ‏عَمْروٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏اعْتَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعَ عُمَرٍ عُمْرَةَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏وَعُمْرَةَ الْقَضَاءِ وَالثَّالِثَةَ مِنْ ‏ ‏الْجِعِرَّانَةِ ‏ ‏وَالرَّابِعَةَ الَّتِي مَعَ حَجَّتِهِ ‏","","",""],[2803,2803,"","তিনি বলেছিলেন যে, ঈশ্বর তাঁর কাছে প্রার্থনা করেন এবং তিনি আমাকে যে - সাহায্য করবেন, তা তিনি কখনো আমার দিকে তাকাননি ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏وَحُسَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ لَا يَنْظُرُ إِلَى ‏ ‏مُسْبِلٍ ‏","","",""],[2804,2804,"","আমরা আমার বাবাকে ভালো ছেলেকে দিতে বলেছিলাম, দুইজনকে এটা থেকে ঠিক করতে হবে। অন্ধ হয়ে গেলাম, না, না।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏اخْتَصَمَ رَجُلَانِ فَدَارَتْ الْيَمِينُ عَلَى أَحَدِهِمَا فَحَلَفَ بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ مَا لَهُ عَلَيْهِ حَقٌّ ‏ ‏فَنَزَلَ ‏ ‏جِبْرِيلُ ‏ ‏فَقَالَ مُرْهُ فَلْيُعْطِهِ حَقَّهُ فَإِنَّ الْحَقَّ قِبَلَهُ وَهُوَ كَاذِبٌ وَكَفَّارَةُ يَمِينِهِ مَعْرِفَتُهُ بِاللَّهِ أَنَّهُ لَا إِلَهَ إِلَّا هُوَ أَوْ شَهَادَتُهُ أَنَّهُ لَا إِلَهَ إِلَّا هُوَ ‏","","",""],[2805,2805,"","আমরা সেই বধিরদের কথা বলেছিলাম, যে কিনা এটা বিক্রি করার চেষ্টা করেছিল। ঈশ্বরের এমন পরিকল্পনা আছে যা আমি বস্ত করছি আর তারপর ভাবলাম যে আমি কেন পরিকল্পনা করেছি, আমি কোন রকম পরিকল্পনা করিনি। খালি মনের গাল, আমি একটা গাল-ও-ডু-ডু-ডু-ডুও-ডু-ডু-ডু-ডু-ডু-ডু-ডু-ডু-ডু-ডু-ডু-ডু-ডু-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-ড-)","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏حَدَّثَنَا ‏ ‏عِلْبَاءُ بْنُ أَحْمَرَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَّ أَرْبَعَةَ خُطُوطٍ ثُمَّ قَالَ أَتَدْرُونَ لِمَ خَطَطْتُ هَذِهِ الْخُطُوطَ قَالُوا لَا قَالَ ‏ ‏أَفْضَلُ نِسَاءِ الْجَنَّةِ أَرْبَعٌ ‏ ‏مَرْيَمُ بِنْتُ عِمْرَانَ ‏ ‏وَخَدِيجَةُ بِنْتُ خُوَيْلِدٍ ‏ ‏وَفَاطِمَةُ ابْنَةُ مُحَمَّدٍ ‏ ‏وَآسِيَةُ ابْنَةُ مُزَاحِمٍ ‏","","",""],[2806,2806,"","আমি আমার বাবা ঈশ্বরের পুত্রকে সাহায্য করতে যাচ্ছি, আমি এক ছেলে যে কিনা ঈশ্বরের কাছে প্রার্থনা করেছে এবং তাকে দেওয়া হয়েছে. প্রভু, তার আত্মা হতে হলে, সে বলে আমরা প্রার্থনা আর বিশ্বের স্থাপত্যের ষড়যন্ত্রের মধ্যে একজন মানুষকে খুঁজে বের করি। তারা বলেছিল, কে এটা এবং এটা জন্য জিজ্ঞাসা করা হয়েছে। তাকে এটা দিও না।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ عَلَيْهِمْ وَهُمْ جُلُوسٌ فِي مَجْلِسٍ لَهُمْ فَقَالَ ‏ ‏أَلَا أُخْبِرُكُمْ بِخَيْرِ النَّاسِ قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ رَجُلٌ آخِذٌ بِرَأْسِ فَرَسِهِ فِي سَبِيلِ اللَّهِ حَتَّى يَمُوتَ أَوْ يُقْتَلَ أَفَأُخْبِرُكُمْ بِالَّذِي يَلِيهِ قَالَ قُلْنَا نَعَمْ قَالَ رَجُلٌ مُعْتَزِلٌ فِي شِعْبٍ يُقِيمُ الصَّلَاةَ ‏ ‏وَيُؤْتِي الزَّكَاةَ وَيَعْتَزِلُ شُرُورَ النَّاسِ أَفَأُخْبِرُكُمْ بِشَرِّ النَّاسِ مَنْزِلًا قَالُوا نَعَمْ قَالَ الَّذِي يُسْأَلُ بِاللَّهِ وَلَا يُعْطِي بِهِ ‏","","",""],[2807,2807,"","আমরা একটা কথা বলছিলাম, একটা ছেলে কীভাবে তাকে ভালবাসতে হয় সেটা বলার চেষ্টার ব্যাপারে। সে তার মাকে একটা বদখত হাত দিয়েছিল, ঈশ্বরের কাছে প্রার্থনা করেছিল আর আমি হলাম সে-ই-ই-ই-ই-ই-ই-ই- ভুল, এবং ঈশ্বরের দয়ায়, ঈশ্বরের দয়ায়, ঈশ্বরের দয়ায়, আল্লাহ আমাকে উদ্ধার করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جَعْفَرُ بْنُ إِيَاسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَهْدَتْ ‏ ‏أُمُّ حُفَيْدٍ ‏ ‏خَالَةُ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمْنًا ‏ ‏وَأَقِطًا ‏ ‏وَأَضُبًّا ‏ ‏فَأَكَلَ مِنْ السَّمْنِ وَمِنْ ‏ ‏الْأَقِطِ ‏ ‏وَتَرَكَ الْأَضُبَّ تَقَذُّرًا قَالَ وَأُكِلَ عَلَى مَائِدَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَوْ كَانَ حَرَامًا لَمْ يُؤْكَلْ عَلَى مَائِدَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2808,2808,"","আমরা তোমাকে কতবার বলেছিলাম তোমার টাকা ছিল সেই ছেলে যে শয়তানীকে হিংসা করেছিল। আমি সেই সেই ছেলে যে তার জন্য প্রার্থনা করেছিল আর সে তার দিকে তাকিয়ে আছে সে বলেছে সে তোমার সাথে এমন করেছে, তারপর ওটা ছুঁড়ে ফেলে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكُ بْنُ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّخَذَ خَاتَمًا فَلَبِسَهُ ثُمَّ قَالَ شَغَلَنِي هَذَا عَنْكُمْ مُنْذُ الْيَوْمِ إِلَيْهِ نَظْرَةٌ وَإِلَيْكُمْ نَظْرَةٌ ثُمَّ رَمَى بِهِ ‏","","",""],[2809,2809,"","আমরা ভাল মানুষদের প্রতি প্রেম বলেছি যারা আমার বাবার আশীর্বাদের কথা বলেছে, যে আমাকে ভালোবাসে, তার কারণ আছে ঈশ্বরের কাছে নিজেকে আত্মসমর্পণ করা, সৃষ্টিকর্তাকে বলাই যুদ্ধ। বিক্রি করে, তারা এটা বিনামূল্যে খায়, তারপর করে।","‏ ‏حَدَّثَنَا ‏ ‏مَحْبُوبُ بْنُ الْحَسَنِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏بَرَكَةَ أَبِي الْوَلِيدِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏حُرِّمَ عَلَيْهِمْ الشُّحُومُ فَبَاعُوهَا فَأَكَلُوا أَثْمَانَهَا وَإِنَّ اللَّهَ إِذَا حَرَّمَ عَلَى قَوْمٍ شَيْئًا حَرَّمَ عَلَيْهِمْ ثَمَنَهُ ‏","","",""],[2810,2810,"","ঈশ্বর তাকে কবরে মেরে ফেলা হয়নি কিন্তু মৃত্যু পর্যন্ত মারা যায়নি যে, একজন ব্যক্তির ছেলে মারা গিয়েছে । এবং সে আত্মসমর্পণ করবে যে সে তার আত্মার বিষের মাধ্যমে চলে গেছে, এটা আমার ছেলের জন্য, ঈশ্বরের কাছে প্রার্থনা করে সে তোমার স্বচ্ছতার কথা স্বীকার করবে এবং বলবে সে হয়ত সে এটা করেছে। ওদেরকে মরতে মানা করা হয়নি।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَقِتْ فِي الْخَمْرِ حَدًّا قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏شَرِبَ رَجُلٌ فَسَكِرَ فَلُقِيَ يَمِيلُ فِي فَجٍّ فَانْطُلِقَ بِهِ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَلَمَّا حَاذَى بِدَارِ ‏ ‏عَبَّاسٍ ‏ ‏انْفَلَتَ فَدَخَلَ عَلَى ‏ ‏عَبَّاسٍ ‏ ‏فَالْتَزَمَهُ مِنْ وَرَائِهِ فَذَكَرُوا ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَضَحِكَ وَقَالَ قَدْ فَعَلَهَا ثُمَّ لَمْ يَأْمُرْهُمْ فِيهِ بِشَيْءٍ ‏","","",""],[2811,2811,"","আমরা কয়েক বছর আগে কথা বলেছি, যখন চুমুটা পরিবর্তন হয়ে গেলো... ...আর ওরা একসাথে গান গাইতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قِيلَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ حُوِّلَتْ الْقِبْلَةُ فَمَا لِلَّذِينَ مَاتُوا وَهُمْ يُصَلُّونَ إِلَى ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏فَأَنْزَلَ اللَّهُ تَبَارَكَ وَتَعَالَى ‏ { ‏وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ ‏}","","",""],[2812,2812,"","আমরা দুই বছর আগে আমাদের বাবা নিজের ছেলের সাথে বড় হয়েছি। একজন যাজকের ছেলে বলেছিলেন, আমি ভাববাদীকে প্রার্থনা করতে বলবো আর তার জন্য প্রার্থনা করতে বলেছি। তার ছবিতে তাকে দেখার জন্য অসম্ভব, সে তাকে যে খারাপটা দিয়ে দিয়েছে, সে বলে যে টাকা দিয়েছে, আর সে তা করেনি, আমরা বেঁচে আছি এবং আমরা এটাকে বাঁচাতে পারি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏إِدْرِيسَ بْنِ سِنَانَ الْيَمَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَهْبِ بْنِ مُنَبِّهٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏سَأَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جِبْرِيلَ ‏ ‏أَنْ يَرَاهُ فِي صُورَتِهِ فَقَالَ ادْعُ رَبَّكَ قَالَ فَدَعَا رَبَّهُ قَالَ فَطَلَعَ عَلَيْهِ سَوَادٌ مِنْ قِبَلِ الْمَشْرِقِ قَالَ فَجَعَلَ يَرْتَفِعُ وَيَنْتَشِرُ قَالَ فَلَمَّا رَآهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَعِقَ فَأَتَاهُ فَنَعَشَهُ وَمَسَحَ الْبُزَاقَ عَنْ ‏ ‏شِدْقَيْهِ ‏","","",""],[2813,2813,"","আমরা যে বধিরদের কথা বলেছিলাম তারা ঈশ্বরের পরে আমার বাবার সঙ্গে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أُتِيَ بِأُنَاسٍ مِنْ ‏ ‏الزُّطِّ ‏ ‏يَعْبُدُونَ وَثَنًا فَأَحْرَقَهُمْ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ بَدَّلَ دِينَهُ فَاقْتُلُوهُ ‏","","",""],[2814,2814,"","আমরা ভালোবাসা নিয়ে বলছি যে আমার রক্ত থেকে মুক্তি পাওয়া যাবে, একজন ভাববাদীর প্রার্থনা করা ছেলে... ...সে এক চোখে আত্মসমর্পণ করবে... ক্রুশে দেখা যাবে... ...আর কখনো ক্রেতাদের হাতে খুন করা হবেনা... ...আর লর্ডকে পাওয়া যাবে.","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏أَخْبَرَنِي ‏ ‏سَيْفُ بْنُ سُلَيْمَانَ الْمَكِّيُّ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ سَعْدٍ الْمَكِّيِّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى بِيَمِينٍ وَشَاهِدٍ ‏ ‏قَالَ ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏سَأَلْتُ ‏ ‏مَالِكَ بْنَ أَنَسٍ ‏ ‏عَنْ الْيَمِينِ وَالشَّاهِدِ هَلْ يَجُوزُ فِي الطَّلَاقِ وَالْعَتَاقِ فَقَالَ لَا إِنَّمَا هَذَا فِي الشِّرَاءِ وَالْبَيْعِ وَأَشْبَاهِهِ ‏","","",""],[2815,2815,"","ঈশ্বরের সঙ্গে কথা বলার সময় আমরা একটা কুত্তার পুত্র হওয়ার বিষয়ে কথা বলেছিলাম । সেখানে,","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏سَيْفِ بْنِ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى بِالْيَمِينِ مَعَ الشَّاهِدِ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏إِنَّمَا ذَاكَ فِي الْأَمْوَالِ ‏","","",""],[2816,2816,"","আমরা আমাদের জীবনের সর্বোত্তমতম মানের সাথে কথা বলেছি। সৃষ্টিকর্তা তাকে জানতেন এবং তিনি বলেছিলেন যে প্রত্যেক জ্ঞানী শিক্ষকই বলতেন। বছর।","‏ ‏حَدَّثَنَا ‏ ‏الزُّبَيْرِيُّ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَلَى كُلِّ مُسْلِمٍ حَجَّةٌ وَلَوْ قُلْتُ كُلَّ عَامٍ لَكَانَ ‏","","",""],[2817,2817,"","আমরা কথা বলেছিলাম একটি ভাল ছেলে খুঁজে পেতে। ঈশ্বর তাঁর জন্য প্রার্থনা করেন এবং একটি ক্রস ক্রস থেকে আত্মসমর্পণের জন্য আমি শপথ করে আমার ধনুক গ্রহণ করলাম। শপথটা আমার আর এর মধ্যে আর কোন মিল নেই। আমরা এটা নিয়ে বারবার কথা বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏الزُّبَيْرِيُّ ‏ ‏وَأَسْوَدُ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏ابْتَاعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ عِيرٍ أَقْبَلَتْ فَرَبِحَ أَوَاقِيَّ فَقَسَمَهَا بَيْنَ أَرَامِلِ ‏ ‏عَبْدِ الْمُطَّلِبِ ‏ ‏ثُمَّ قَالَ ‏ ‏لَا أَبْتَاعُ بَيْعًا لَيْسَ عِنْدِي ثَمَنُهُ ‏ ‏و حَدَّثَنَاه ‏ ‏وَكِيعٌ ‏ ‏أَيْضًا فَأَسْنَدَهُ ‏","","",""],[2818,2818,"","আমরা কাস্টমারদের কথা বলেছি আর আমি একটা মেয়েকে খুঁজে বের করতে পারব। আমি এমন একজন মহিলার কাছে এসেছি যার কাছে ঈশ্বর প্রতিজ্ঞা করেছেন যে এটা উদ্ধার করতে পারবে। সে বলবে, \"ঈশ্বর, আমি হয়ত তোমাকে দিতে পারবো।\" প্রভুর কাছে আমার শিক্ষককে সমর্পণ কর, আর সে আমাকে শিখিয়েছে কিভাবে তাকে ইমার্জেন্সি করতে হয়।\" সে বলেছিল, এটা তার প্রথম বিয়ে।","‏ ‏حَدَّثَنَا ‏ ‏الزُّبَيْرِيُّ ‏ ‏وَأَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَسْلَمَتْ امْرَأَةٌ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَزَوَّجَتْ فَجَاءَ زَوْجُهَا الْأَوَّلُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي قَدْ أَسْلَمْتُ وَعَلِمَتْ إِسْلَامِي فَنَزَعَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ زَوْجِهَا الْآخِرِ وَرَدَّهَا عَلَى زَوْجِهَا الْأَوَّلِ ‏","","",""],[2819,2819,"","আমরা আমার বাবার কথা বলেছিলাম যখন আমরা আমার মন ভেঙ্গেছিলাম, কি ইট বা এমন কারো কাছে না যাই যে এই ভবিষ্যদ্বাণীটি জিতেছে। আমি আমার বাবার সাথে কথা বলেছি, আমি আমার বাবার বাপ্তিস্মের সময় থেকে বাপ্তিস্ম নিয়েছি। সে ভুল করে ভুল করে ভুল করে নিজেকে দোষী সাব্যস্ত করে এবং লজ্জিত হতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏فُضَيْلِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَوْ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏أَحَدِهِمَا ‏ ‏عَنْ ‏ ‏صَاحِبِهِ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَرَادَ الْحَجَّ فَلْيَتَعَجَّلْ فَإِنَّهُ قَدْ تَضِلُّ الضَّالَّةُ وَيَمْرَضُ الْمَرِيضُ وَتَكُونُ الْحَاجَةُ ‏","","",""],[2820,2820,"","আমি তাদের বলেছিলাম: “আমি তাদের সঙ্গে কথা বলতে চাই । বিজ্ঞানের পক্ষ থেকে এমন কোনো বিজ্ঞানের কাছ থেকে কোন হিসাব নেওয়া হবে না","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّقُوا الْحَدِيثَ عَنِّي إِلَّا مَا عَلِمْتُمْ فَإِنَّهُ مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ وَمَنْ كَذَبَ فِي الْقُرْآنِ بِغَيْرِ عِلْمٍ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارَ ‏","","",""],[2821,2821,"","আমি আমার পরিবারের সঙ্গে বাইবেল অধ্যয়ন করতে শুরু করেছিলাম । প্রতিশ্রুতির পরে আমি তাদের যেতে দেয়াটা দেখতে পাবো না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَدْ ‏ ‏مَسَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْخُفَّيْنِ فَاسْأَلُوا هَؤُلَاءِ الَّذِينَ يَزْعُمُونَ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ قَبْلَ نُزُولِ ‏ ‏الْمَائِدَةِ ‏ ‏أَوْ بَعْدَ ‏ ‏الْمَائِدَةِ ‏ ‏وَاللَّهِ مَا مَسَحَ بَعْدَ ‏ ‏الْمَائِدَةِ ‏ ‏وَلَأَنْ أَمْسَحَ عَلَى ظَهْرِ عَابِرٍ بِالْفَلَاةِ أَحَبُّ إِلَيَّ مِنْ أَنْ أَمْسَحَ عَلَيْهِمَا ‏","","",""],[2822,2822,"","বাবার ছেলে ঘোড়াগুলো নিয়ে আমরা কথা বলেছি, একটা দেবীর পুত্রকে বলেছিলাম যাতে লড়াই করতে পারে। তোমার মা তার প্রভুর সাথে নেই। লর্ডশিপ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْجَبَّارِ بْنِ وَرْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏لِعُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏يَا ‏ ‏عُرَيَّةُ ‏ ‏سَلْ أُمَّكَ أَلَيْسَ قَدْ جَاءَ أَبُوكَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَحَلَّ ‏","","",""],[2823,2823,"","কয়েক বছর ধরে আমরা এক যাজককে নির্মাণের সাথে আনন্দের সাথে কথা বলেছি, যে কিনা একজন জেদী প্রেমিক ছিল। আকাশ তার এলাকা এবং তারা ছিল এমন কোন সাহস নয় যে তারা হয়ত এই রকম এক ধর্ম পালন করবে। সে তার কল্পনার জন্য এটা করেছে, সে এটা পুড়িয়ে দিয়েছে, সে বলেছিল সে এটা করেছে তার মৃত্যুর জন্য । তার কাছে একটা নাম্বার আছে যেটা আমাকে কাপুরুষ বলে ছেড়ে দেবে","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَتْ لِلشَّيَاطِينِ مَقَاعِدُ فِي السَّمَاءِ فَكَانُوا يَسْتَمِعُونَ الْوَحْيَ وَكَانَتْ النُّجُومُ لَا ‏ ‏تَجْرِي وَكَانَتْ الشَّيَاطِينُ لَا ‏ ‏تُرْمَى قَالَ فَإِذَا سَمِعُوا الْوَحْيَ نَزَلُوا إِلَى الْأَرْضِ فَزَادُوا فِي الْكَلِمَةِ تِسْعًا فَلَمَّا بُعِثَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَعَلَ الشَّيْطَانُ إِذَا قَعَدَ مَقْعَدَهُ جَاءَهُ شِهَابٌ فَلَمْ يُخْطِهِ حَتَّى يُحْرِقَهُ قَالَ فَشَكَوْا ذَلِكَ إِلَى إِبْلِيسَ فَقَالَ مَا هَذَا إِلَّا مِنْ حَدَثٍ حَدَثَ قَالَ فَبَثَّ جُنُودَهُ قَالَ فَإِذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَائِمٌ ‏ ‏يُصَلِّي بَيْنَ جَبَلَيْ ‏ ‏نَخْلَةَ ‏ ‏قَالَ فَرَجَعُوا إِلَى إِبْلِيسَ فَأَخْبَرُوهُ قَالَ فَقَالَ هُوَ الَّذِي حَدَثَ ‏","","",""],[2824,2824,"","এমনকি ঈশ্বর যদি তাঁর জন্য প্রার্থনাও করেন, তবুও তিনি তা করবেন । আমি তার উপর নিষেধাজ্ঞা জারি করেছি। কিন্তু সে বলেছে, সে নাকি খুন হয়েছে। কিন্তু তুমি যা বলেছ, সে তাই বলেছে। আমি তাকে সাহস দিয়ে দেখি ।","‏ ‏حَدَّثَنَا ‏ ‏رِبْعِيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنِ ‏ ‏ابْنِ وَعْلَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏خَرَجَ وَالْخَمْرُ حَلَالٌ فَأَهْدَى لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَاوِيَةَ خَمْرٍ فَأَقْبَلَ بِهَا يَقْتَادُهَا عَلَى بَعِيرٍ حَتَّى وَجَدَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسًا فَقَالَ مَا هَذَا مَعَكَ قَالَ رَاوِيَةُ خَمْرٍ أَهْدَيْتُهَا ‏ ‏لَكَ قَالَ هَلْ عَلِمْتَ أَنَّ اللَّهَ تَبَارَكَ وَتَعَالَى حَرَّمَهَا قَالَ لَا قَالَ فَإِنَّ اللَّهَ حَرَّمَهَا فَالْتَفَتَ الرَّجُلُ إِلَى قَائِدِ الْبَعِيرِ وَكَلَّمَهُ بِشَيْءٍ فِيمَا بَيْنَهُ وَبَيْنَهُ فَقَالَ مَاذَا قُلْتَ لَهُ قَالَ أَمَرْتُهُ بِبَيْعِهَا قَالَ ‏ ‏إِنَّ الَّذِي حَرَّمَ شُرْبَهَا حَرَّمَ بَيْعَهَا قَالَ فَأَمَرَ بِعَزَالِي ‏ ‏الْمَزَادَةِ فَفُتِحَتْ فَخَرَجَتْ فِي التُّرَابِ فَنَظَرْتُ إِلَيْهَا فِي ‏ ‏الْبَطْحَاءِ ‏ ‏مَا فِيهَا شَيْءٌ ‏","","",""],[2825,2825,"","আমরা এক বছর আগে কথা বলেছিলাম, আমরা ঈশ্বর সম্পর্কে কথা বলেছি। তিনি আত্মসমর্পণ করতেন এবং আমাকে যে কাগজগুলো দিতে হত, তা দিয়ে আমি তাকে টেনে তুলে নিতাম এবং তাকে শাস্তি দেয়া হত না। আমার ছেলের জন্য লড়াই করার চেষ্টা করছি, আর সে তার আবিষ্কারের অর্ধেক স্বপ্ন নিয়ে যাচ্ছে, আমি আবার চেষ্টা করছি।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏احْتَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَعْطَى ‏ ‏الْحَجَّامَ ‏ ‏أَجْرَهُ وَلَوْ كَانَ حَرَامًا لَمْ يُعْطِهِ وَكَانَ ‏ ‏يَحْتَجِمُ ‏ ‏فِي ‏ ‏الْأَخْدَعَيْنِ ‏ ‏وَبَيْنَ الْكَتِفَيْنِ وَكَانَ ‏ ‏يَحْجُمُهُ ‏ ‏عَبْدٌ ‏ ‏لِبَنِي بَيَاضَةَ ‏ ‏وَكَانَ يُؤْخَذُ مِنْهُ كُلَّ يَوْمٍ ‏ ‏مُدٌّ ‏ ‏وَنِصْفٌ فَشَفَعَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى أَهْلِهِ فَجُعِلَ ‏ ‏مُدًّا ‏","","",""],[2826,2826,"","আমরা কাঠবিড়ালীর এক ভালো ছেলের জন্য ঋণের কথা বলেছি, ঈশ্বর আমাদের কাছে একটি যুদ্ধলক হিসেবে কাজ করেছেন এবং একটি ছেলে জন্য আমাদের জন্য দু'বার ঘটেছে।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تَزَوَّجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏ابْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏مِثْلَهُ ‏","","",""],[2827,2827,"","আমরা জানতে পারলাম কে এমন ছেলে হতে পারে যে বলল ঈশ্বর তার জন্য প্রার্থনা করছেন এবং আমি বাচ্চাটাকে ছেড়ে দিচ্ছি আর আমি ভালুকের কাছে ফিরে যাব।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُصِرْتُ بِالصَّبَا وَأُهْلِكَتْ ‏ ‏عَادٌ ‏ ‏بِالدَّبُورِ ‏","","",""],[2828,2828,"","ঈশ্বর তাকে আরেকটা সময় খুঁজে বের করার এবং আমাকে হত্যা করার চেষ্টা করতে দেন ।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏طَاوُسًا ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أُمِرَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَسْجُدَ عَلَى سَبْعَةٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَحَدَّثَنِيهِ مَرَّةً أُخْرَى قَالَ أُمِرْتُ بِالسُّجُودِ وَأَنْ لَا أَكُفَّ شَعَرًا وَلَا ثَوْبًا ‏","","",""],[2829,2829,"","ঈশ্বর তাঁর আদেশ দিয়েছেন এবং প্রভু তাকে তার উত্তম ও দুঃখের হাত থেকে তুলে নিয়েছেন ।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُحَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَائِرَاتِ الْقُبُورِ وَالْمُتَّخِذِينَ عَلَيْهَا الْمَسَاجِدَ ‏ ‏وَالسُّرُجَ ‏","","",""],[2830,2830,"","আমরা বাবার কথা বলেছিলাম একবার তিনি একটা ছেলেকে বলেছিলেন যে সে সেই ছেলে ।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي جَمْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي ثَلَاثَ عَشْرَةَ رَكْعَةً مِنْ اللَّيْلِ ‏","","",""],[2831,2831,"","আমরা কথা বলেছিলাম যখন সে তার জ্ঞানকে আদেশ দিয়েছে আর নিজের ইচ্ছার সঙ্গে আমার মনের শান্তির জন্য আত্মসমর্পণ করবে. এটা মেরে ফেলে, আর বলো না আমি আর কেন ধর্ম দিতে পারি না","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ نَفَرٌ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏مَعَهُ غَنَمٌ لَهُ فَسَلَّمَ عَلَيْهِمْ فَقَالُوا مَا سَلَّمَ عَلَيْكُمْ إِلَّا تَعَوُّذًا مِنْكُمْ فَعَمَدُوا إِلَيْهِ فَقَتَلُوهُ وَأَخَذُوا غَنَمَهُ فَأَتَوْا بِهَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنْزَلَ اللَّهُ تَبَارَكَ وَتَعَالَى ‏ { ‏وَلَا تَقُولُوا لِمَنْ أَلْقَى إِلَيْكُمْ السَّلَامَ لَسْتَ مُؤْمِنًا تَبْتَغُونَ عَرَضَ الْحَيَاةِ الدُّنْيَا ‏} ‏إِلَى آخِرِ الْآيَةِ ‏","","",""],[2832,2832,"","আমরা আমাদের পরিবারের সঙ্গে বাইবেল অধ্যয়ন শুরু করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي قَوْلِهِ ‏ { ‏كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ ‏} ‏قَالَ ‏ ‏أَصْحَابُ مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِينَ هَاجَرُوا مَعَهُ إِلَى ‏ ‏الْمَدِينَةِ ‏","","",""],[2833,2833,"","আমরা সবাই ভাল থেকে ভাল, আমাদের কথোপকথনের ভাল ... ...আমার বাবার জন্য অনেক ভালবাসা ছিল. পানিকে যুক্তি দিয়ে বোঝা যায় আর ভুল হয়েছে, তার আঙ্গুলে, সে তোমাকে ঈশ্বরের উপর ছেড়ে দিতে বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ حَسَنٍ الْأَشْقَرُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُدَيْنَةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ يَهُودِيٌّ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ جَالِسٌ فَقَالَ كَيْفَ تَقُولُ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏يَوْمَ يَجْعَلُ اللَّهُ تَبَارَكَ وَتَعَالَى السَّمَاءَ عَلَى ذِهْ وَأَشَارَ بِالسَّبَّابَةِ وَالْأَرْضَ عَلَى ذِهْ وَالْمَاءَ عَلَى ذِهْ وَالْجِبَالَ عَلَى ذِهْ وَسَائِرَ الْخَلَائِقِ عَلَى ذِهْ كُلُّ ذَلِكَ يُشِيرُ بِإِصْبَعِهِ قَالَ فَأَنْزَلَ اللَّهُ تَبَارَكَ وَتَعَالَى ‏ { ‏وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ ‏} ‏الْآيَةَ ‏","","",""],[2834,2834,"","আমরা আমাদের বাবা বা বাবা থেকে ভাল ছিলাম... ...তার কাছে আমার একজন যাজকের ছেলে হওয়ার জন্য, ঈশ্বরের কাছে প্রার্থনা করে, আর সে তার কথা মন থেকে বাদ দিয়ে বলে পানি, সে তাকে মেরে ফেলবে, তোমার কিছু বলার আছে আমাদের কিছু পানি নিয়ে যেতে হবে, সে বলেছে সে হয়ত পরে যাবে। আমি আমার কাজ করবো এবং আমি বলবো এটা ছিল। জীবন কাহিনী থেকে মুছে দাও, নৌকা।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ الْحَسَنِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُدَيْنَةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَصْبَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ وَلَيْسَ فِي الْعَسْكَرِ مَاءٌ فَأَتَاهُ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ لَيْسَ فِي الْعَسْكَرِ مَاءٌ قَالَ هَلْ عِنْدَكَ شَيْءٌ قَالَ نَعَمْ قَالَ فَأْتِنِي بِهِ فَأَتَاهُ بِإِنَاءٍ فِيهِ شَيْءٌ مِنْ مَاءٍ قَلِيلٍ قَالَ ‏ ‏فَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصَابِعَهُ عَلَى فَمِ الْإِنَاءِ وَفَتَحَ أَصَابِعَهُ قَالَ فَانْفَجَرَتْ مِنْ بَيْنِ أَصَابِعِهِ عُيُونٌ وَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَقَالَ نَادِ فِي النَّاسِ الْوَضُوءَ الْمُبَارَكَ ‏","","",""],[2835,2835,"","আমি আমার বাবার ঈশ্বরের প্রতি ভালবাসা থেকে পালিয়ে যাওয়ার কথা বলেছিলাম। পাঠক - পাঠিকাদের থেকে প্রশ্নসকল সে যার আদেশ করবে, সে কি করবে, আমি তার চেয়ে ঝামেলার শিকার আর ঈশ্বরের সন্তানের জন্য তার অনুগ্রহ প্রভু ও আমার প্রভুকে দিতে আদেশ দিয়েছেন ছেলে উদ্ধার করা হয়েছে, আর তাদের ভুলও।","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏يُونُسَ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا حَضَرَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَفَاةُ قَالَ ‏ ‏هَلُمَّ أَكْتُبْ لَكُمْ كِتَابًا لَنْ تَضِلُّوا بَعْدَهُ وَفِي الْبَيْتِ رِجَالٌ فِيهِمْ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ غَلَبَهُ الْوَجَعُ وَعِنْدَكُمْ الْقُرْآنُ حَسْبُنَا كِتَابُ اللَّهِ قَالَ فَاخْتَلَفَ أَهْلُ الْبَيْتِ فَاخْتَصَمُوا فَمِنْهُمْ مَنْ يَقُولُ يَكْتُبُ لَكُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ قَرِّبُوا يَكْتُبْ لَكُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمِنْهُمْ مَنْ يَقُولُ مَا قَالَ ‏ ‏عُمَرُ ‏ ‏فَلَمَّا أَكْثَرُوا اللَّغَطَ ‏ ‏وَالِاخْتِلَافَ وَغُمَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قُومُوا عَنِّي ‏ ‏فَكَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ الرَّزِيَّةَ كُلَّ الرَّزِيَّةِ مَا حَالَ بَيْنَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ أَنْ يَكْتُبَ لَهُمْ ذَلِكَ الْكِتَابَ مِنْ اخْتِلَافِهِمْ وَلَغَطِهِمْ ‏","","",""],[2836,2836,"","আমরা একজন যাজকের সাক্ষি হওয়ার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَهُوَ ‏ ‏بِمَكَّةَ ‏ ‏نَحْوَ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏وَالْكَعْبَةُ ‏ ‏بَيْنَ يَدَيْهِ وَبَعْدَ مَا هَاجَرَ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏سِتَّةَ عَشَرَ شَهْرًا ثُمَّ صُرِفَ إِلَى ‏ ‏الْكَعْبَةِ ‏","","",""],[2837,2837,"","আমরা তার বাবার সঙ্গে এক ছেলের জন্ম দেওয়ার বিষয়ে কথা বলেছিলাম, যিনি আমার প্রেমের সঙ্গে সুখী ছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏عُمَرُ ‏ ‏فَقَالَ ‏ ‏السَّلَامُ عَلَى رَسُولِ اللَّهِ السَّلَامُ عَلَيْكُمْ أَيَدْخُلُ ‏ ‏عُمَرُ ‏","","",""],[2838,2838,"","আমরা দুই দিন আগে কথা বলেছি এবং তিনি একজন পিতার অমর সন্তান হবেন, যে হয়ত বলেছিল, ঈশ্বর তার জন্য প্রার্থনা করবেন এবং আমি তার বাবা-মার আত্মাকে অভিবাদন করব, এবং তারপর তারপর ঈশ্বরের লোকেরা অনেক ভাল হবে.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلْحِقُوا الْفَرَائِضَ بِأَهْلِهَا فَمَا بَقِيَ فَلِأَوْلَى رَجُلٍ ذَكَرٍ ‏","","",""],[2839,2839,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তলোয়ার ও এর রিপোর্ট করার আগে পর্যন্ত অন্ধকারে আনন্দ করার বছরটাকে সমর্পণ করেছেন । আমি ভেবেছিলাম যে তিনি এমন একটা রাজ্যে প্রবেশ করেছেন যেটা ভবিষ্যতে একটা ভুল ধারণা দিয়ে ঈশ্বরের কাছে প্রার্থনা করেছিল । আমি যা ভেবেছিলাম সেটা ছিল বধির এবং কিছু জিনিস থেকে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏مُفَضَّلٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏سَافَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ الْفَتْحِ فِي رَمَضَانَ فَصَامَ حَتَّى بَلَغَ ‏ ‏عُسْفَانَ ‏ ‏ثُمَّ دَعَا بِإِنَاءٍ فَشَرِبَ نَهَارًا لِيَرَاهُ النَّاسُ ثُمَّ أَفْطَرَ حَتَّى دَخَلَ ‏ ‏مَكَّةَ ‏ ‏وَافْتَتَحَ ‏ ‏مَكَّةَ ‏ ‏فِي رَمَضَانَ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَصَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي السَّفَرِ وَأَفْطَرَ فَمَنْ شَاءَ صَامَ وَمَنْ شَاءَ أَفْطَرَ ‏","","",""],[2840,2840,"","আমরা কয়েক বছর ভবিষ্যদ্বাণীর কথা বলেছি, আমরা এটা আর ঈশ্বরকে ভালোবাসি। সে তার মেয়ে আর সে একজন বন্দী যে বলেছে আধা ডজন বার সে তোমার ক্রেতাকে বলেছে একজন যাজকের ছেলে.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الرَّجُلِ يُجَامِعُ امْرَأَتَهُ وَهِيَ حَائِضٌ قَالَ عَلَيْهِ نِصْفُ دِينَارٍ ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏","","",""],[2841,2841,"","আমরা একজন যাজকের ছেলের কথা বলেছিলাম যে আমি আমার ছেলেকে বিয়ে করতে চাই। ঈশ্বর প্রতি বছর প্রতিটি শিশু শিশু কথা বলে, আর যদি আমি বলি, তাহলে সে হবে হয়তো তার সন্তান। বলেছে সব পেপ কথা।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْحَجِّ كُلَّ عَامٍ فَقَالَ ‏ ‏عَلَى كُلِّ مُسْلِمٍ حَجَّةٌ وَلَوْ قُلْتُ كُلَّ عَامٍ لَكَانَ ‏","","",""],[2842,2842,"","আমরা ঈশ্বরের পুত্র হিসেবে জন্মগ্রহণের কথা বলেছিলাম. সে আমার মাথা থেকে আল-মারীর দিকে বের হয়ে তার নার্সদের হাতে তুলে দিল, সে বলেছিল, তার কাজ করার জন্য এটাই ছিল তার সবকিছু. বাবা, সে আমাকে মেরে ফেলবে, তার উপস্থিতি থেকে তাকে উদ্ধার করবে আর আমি জানি সে কখনো তার মুখের কথা জানে না, সে আমাদের এই আদেশটি দিয়েছে। সে যদি আমাদের এলাকায় থাকত, তাহলে আমরা কখনো তার কাছে যেতাম না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏خَرَجَ ‏ ‏عَلِيٌّ ‏ ‏مِنْ عِنْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَرَضِهِ فَقَالُوا كَيْفَ أَصْبَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَبَا حَسَنٍ ‏ ‏فَقَالَ ‏ ‏أَصْبَحَ بِحَمْدِ اللَّهِ بَارِئًا فَقَالَ ‏ ‏الْعَبَّاسُ ‏ ‏أَلَا ‏ ‏تَرَى إِنِّي لَأَرَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَيُتَوَفَّى مِنْ وَجَعِهِ وَإِنِّي لَأَعْرِفُ فِي وُجُوهِ ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏الْمَوْتَ فَانْطَلِقْ بِنَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلْنُكَلِّمْهُ فَإِنْ كَانَ الْأَمْرُ فِينَا بَيَّنَهُ وَإِنْ كَانَ فِي غَيْرِنَا كَلَّمْنَاهُ وَأَوْصَى بِنَا فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏إِنْ قَالَ الْأَمْرُ فِي غَيْرِنَا فَلَمْ يُعْطِنَاهُ النَّاسُ أَبَدًا وَإِنِّي وَاللَّهِ لَا أُكَلِّمُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا أَبَدًا ‏","","",""],[2843,2843,"","আমি আমার বাবা তোমার ব্যাপারে কত কথা বলেছি, আমি ঈশ্বরের কাছে অনুরোধ করব আর সে আমাকে বলবে তুমি জিতলে, আমরা.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِمَاعِزٍ ‏ ‏حِينَ قَالَ زَنَيْتُ ‏ ‏لَعَلَّكَ غَمَزْتَ أَوْ قَبَّلْتَ أَوْ نَظَرْتَ إِلَيْهَا ‏ ‏قَالَ ‏ ‏كَأَنَّهُ يَخَافُ أَنْ لَا يَدْرِيَ مَا الزِّنَا ‏","","",""],[2844,2844,"","একজন যাজকের ছেলেকে দেখার জন্য তাকে হত্যা করার বিষয়ে আমরা কথা বলেছি। ঈশ্বর তাকে আদেশ দিয়েছেন এবং প্রতি বছর পাঠককে তার কাছে এই বিষয়ে পরামর্শ প্রদান করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْرِضُ الْقُرْآنَ عَلَى ‏ ‏جِبْرِيلَ ‏ ‏فِي كُلِّ سَنَةٍ مَرَّةً فَلَمَّا كَانَتْ السَّنَةُ الَّتِي قُبِضَ فِيهَا عَرَضَهُ عَلَيْهِ مَرَّتَيْنِ فَكَانَتْ قِرَاءَةُ ‏ ‏عَبْدِ اللَّهِ ‏ ‏آخِرَ الْقِرَاءَةِ ‏","","",""],[2845,2845,"","আমরা একটা ছেলেকে সাহায্য করার কথা বলেছি, সে চলে গেছে, আর তারা এতিমদের টাকা নিয়ে নেই, তাই আমি ভালো আছি, এটা আমার ইশ্বরের দোহাই, সে চুলা দিয়ে আগুন ছেড়ে দেবে আর তাদেরকে মেরে ফেলবে। তারা চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏وَلَا تَقْرَبُوا مَالَ الْيَتِيمِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ ‏} ‏عَزَلُوا أَمْوَالَ الْيَتَامَى حَتَّى جَعَلَ الطَّعَامُ يَفْسُدُ وَاللَّحْمُ يُنْتِنُ فَذُكِرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَزَلَتْ ‏ { ‏وَإِنْ تُخَالِطُوهُمْ فَإِخْوَانُكُمْ وَاللَّهُ يَعْلَمُ الْمُفْسِدَ مِنْ الْمُصْلِحِ ‏} ‏قَالَ فَخَالَطُوهُمْ ‏","","",""],[2846,2846,"","আমরা এমন একটা ছেলের কথা বলেছিলাম, যে তাকে মারতে চেয়েছিল । কথা দিলাম।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قِيلَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ فَرَغَ مِنْ ‏ ‏بَدْرٍ ‏ ‏عَلَيْكَ الْعِيرَ لَيْسَ دُونَهَا شَيْءٌ قَالَ فَنَادَاهُ ‏ ‏الْعَبَّاسُ ‏ ‏إِنَّهُ لَا يَصْلُحُ لَكَ إِنَّ اللَّهَ وَعَدَكَ إِحْدَى الطَّائِفَتَيْنِ وَقَدْ أَعْطَاكَ مَا وَعَدَكَ ‏","","",""],[2847,2847,"","ঈশ্বর সেই সাত জনের একটা দরজায় সমস্তকিছু সমর্পণ করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ كُلِّ ذِي ‏ ‏نَابٍ مِنْ السَّبُعِ ‏","","",""],[2848,2848,"","আমরা শেষ বার কথা বলেছি, আমরা পৃথিবীর সবচেয়ে খারাপ বিষয় নিয়ে কথা বলেছি। সে বলেছিল আমরা তার জন্য প্রার্থনা করবো আর সে ফ্রির জন্য ছেড়ে দেব। আমার ছেলে... ...যখন সূর্য জ্বলে না যায়, ততক্ষণ পাথর না ফেলে আমার অসুস্থ হয়ে পড়ে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ عُتَيْبَةَ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ النَّحْرِ وَعَلَيْنَا سَوَادٌ مِنْ اللَّيْلِ فَجَعَلَ يَضْرِبُ أَفْخَاذَنَا وَيَقُولُ ‏ ‏أَبَنِيَّ أَفِيضُوا وَلَا تَرْمُوا الْجَمْرَةَ حَتَّى تَطْلُعَ الشَّمْسُ ‏","","",""],[2849,2849,"","তিনি বলেছিলেন যে, ঈশ্বর তাঁর জন্য প্রার্থনা করেছিলেন এবং তিনি আমাকে ব্যর্থতা ও প্রার্থনা করতে বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ النَّهْشَلِيُّ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْجَزَّارِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِاللَّيْلِ ‏ ‏ثَمَانِيَ رَكَعَاتٍ وَيُوتِرُ بِثَلَاثٍ وَيُصَلِّ رَكْعَتَيْ الْفَجْرِ ‏","","",""],[2850,2850,"","আমরা ঈশ্বরের কাছে আমার ভালবাসার প্রতি করুণা দেখানোর চেয়ে ভালো কথা বলেছি। একজন যাজকের ছেলে বলেছিলেন, এটা গুয়াররে বেনটার্টের ছেলে। নাম, গুয়ারুর।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الَّرحْمَنِ ‏ ‏مَوْلَى ‏ ‏أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ اسْمُ ‏ ‏جُوَيْرِيَةَ بِنْتِ الْحَارِثِ ‏ ‏بَرَّةَ ‏ ‏فَحَوَّلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْمَهَا ‏ ‏فَسَمَّاهَا ‏ ‏جُوَيْرِيَةَ ‏","","",""],[2851,2851,"","আমরা ঈশ্বরের কথা বলেছিলাম, আমরা যা বলতে চাই তা নিয়ে বিচারকের সাথে কথা বলেছি। তার বুকে নীল রঙের.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدَّمَ ضَعَفَةَ أَهْلِهِ مِنْ ‏ ‏الْمُزْدَلِفَةِ ‏ ‏بِلَيْلٍ فَجَعَلَ ‏ ‏يُوصِيهِمْ أَنْ ‏ ‏لَا يَرْمُوا ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏ ‏حَتَّى تَطْلُعَ الشَّمْسُ ‏","","",""],[2852,2852,"","বাবা আমাকে একটা বধির ছেলে দিয়ে বড় হতে খুঁজছিলো, আমরা ডিনার করেছি, তারপর আমরা কিছু সময় খেতে চেষ্টা করেছি। আমি এটা নিয়ে কথা বললাম না। তাকে দোষ দিয়ে আমি বলছি না সে এটা করবে না। সে কোন যুদ্ধলক নয় অথবা একজন ওয়ার্ডেনকে তার মুখটা খেতে বলছে। কারণ আমি এগুলো খাই নি, কিন্তু এটা খারাপ ভাবে ভেঙ্গে ফেলা হয়। ওদের সাথে তারা বলে, \"আমার বিশ্বাস\" না হয়ও না।","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ يَعْنِي الشَّيْبَانِيَّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقُلْتُ تَزَوَّجَ فُلَانٌ فَقَرَّبَ إِلَيْنَا طَعَامًا فَأَكَلْنَا ثُمَّ قَرَّبَ إِلَيْنَا ‏ ‏ثَلَاثَةَ عَشَرَ ‏ ‏ضَبًّا فَبَيْنَ آكِلٍ وَتَارِكٍ فَقَالَ بَعْضُ مَنْ عِنْدَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏لَا آكُلُهُ وَلَا أُحَرِّمُهُ وَلَا آمُرُ بِهِ وَلَا أَنْهَى عَنْهُ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏بِئْسَ مَا تَقُولُونَ مَا بُعِثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا مُحِلًّا وَمُحَرِّمًا ‏ ‏قُرِّبَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَدَّ يَدَهُ لِيَأْكُلَ مِنْهُ فَقَالَتْ ‏ ‏مَيْمُونَةُ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّهُ لَحْمُ ضَبٍّ فَكَفَّ يَدَهُ وَقَالَ هَذَا لَحْمٌ لَمْ آكُلْهُ قَطُّ فَكُلُوا فَأَكَلَ ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏وَخَالِدُ بْنُ الْوَلِيدِ ‏ ‏وَامْرَأَةٌ كَانَتْ مَعَهُمْ ‏ ‏وَقَالَتْ ‏ ‏مَيْمُونَةُ ‏ ‏لَا آكُلُ مِمَّا لَمْ يَأْكُلْ مِنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2853,2853,"","আমরা এমন একটা ক্লাসের কথা বলেছি, যারা লাইটের মধ্যে বলা হয়েছে, ঈশ্বর আদেশ দিয়েছেন আর আমি কিভাবে এটা করতে পারি তার কাছে আত্মসমর্পণ করতে পারি। আমি বলছি আমরা কিভাবে বলি আমরা ঈশ্বরকে জিতব আর তা করতে যাচ্ছি। আমরা খেয়ে ফেলি।","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطٌ ‏ ‏حَدَّثَنَا ‏ ‏مُطَرِّفٌ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي قَوْلِهِ ‏ { ‏فَإِذَا نُقِرَ فِي النَّاقُورِ ‏} ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ أَنْعَمُ وَصَاحِبُ الْقَرْنِ قَدْ الْتَقَمَ الْقَرْنَ وَحَنَى جَبْهَتَهُ يَسَّمَّعُ مَتَى يُؤْمَرُ فَيَنْفُخُ فَقَالَ ‏ ‏أَصْحَابُ مُحَمَّدٍ ‏ ‏كَيْفَ نَقُولُ قَالَ قُولُوا حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ عَلَى اللَّهِ تَوَكَّلْنَا ‏","","",""],[2854,2854,"","আমরা হাতে কিছু হাত দিয়ে কথা বলেছি, সাথে সাথে আমরা একটা বিচার করেছি যে আমি একটা ভালো কুত্তার বাচ্চা নিয়ে খুশি হব। তাকে তার স্বপ্নের কথা স্মরণ করিয়ে দেওয়া হয়েছিল যতক্ষণ না আমরা উড়তে না বলি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏عَنْ صَوْمِ رَجَبٍ كَيْفَ ‏ ‏تَرَى فِيهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَصُومُ حَتَّى نَقُولَ لَا يُفْطِرُ وَيُفْطِرُ حَتَّى نَقُولَ لَا يَصُومُ ‏","","",""],[2855,2855,"","আমরা প্রভুর প্রেমের গোলামের সাথে কথা বলেছি, একজন যাজকের ছেলে বলল যে সে ঈশ্বরের কাছে প্রার্থনা করছে... ...যে সবসময় পবিত্র পিতার কাছে প্রার্থনা করবে ( যোহন ১৭: ৩) এমনকি তিনি প্রস্তাব দেওয়ার পর বিখ্যাত ব্যক্তিও । দুই.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْرِضُ الْقُرْآنَ فِي كُلِّ رَمَضَانَ عَلَى ‏ ‏جِبْرِيلَ ‏ ‏فَيُصْبِحُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ لَيْلَتِهِ الَّتِي يَعْرِضُ فِيهَا مَا يَعْرِضُ وَهُوَ أَجْوَدُ مِنْ الرِّيحِ الْمُرْسَلَةِ لَا يُسْأَلُ عَنْ شَيْءٍ إِلَّا أَعْطَاهُ حَتَّى كَانَ الشَّهْرُ الَّذِي هَلَكَ بَعْدَهُ عَرَضَ فِيهِ عَرْضَتَيْنِ ‏","","",""],[2856,2856,"","আমরা ঈশ্বরের ছেলের কথা বলেছি এবং আমরা যখন বাবার ছেলের কথা শুনি তখন আমরা তাদের কথা শুনছিলাম। এক ছেলের নামে শপথ করলাম যে, সে এমন এক ছেলে যার দ্বারা নিহত হয়েছে যে কখনো খারাপ মানুষ ছিল না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏وَمُؤَمَّلٌ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ الْمُسْلِمِينَ أَصَابُوا رَجُلًا مِنْ عُظَمَاءِ الْمُشْرِكِينَ فَقَتَلُوهُ فَسَأَلُوا أَنْ يَشْتَرُوا جِيفَتَهُ ‏","","",""],[2857,2857,"","আমরা ঈশ্বরের পুত্রদের কথা বলেছিলাম একটি দেবীর পুত্র সম্পর্কে কথা বলতে গিয়ে... ...আমাদের পরিপক্ব হওয়ার পর তার নিজের শান্তি আছে. অশিক্ষিত.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ لِلصَّلَاةِ فَقَالَ لَهُ بَعْضُ نِسَائِهِ اجْلِسْ ‏ ‏فَإِنَّ الْقِدْرَ قَدْ نَضِجَتْ فَنَاوَلَتْهُ كَتِفًا فَأَكَلَ ثُمَّ مَسَحَ يَدَهُ فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[2858,2858,"","আমরা বাবা, সুখী ছেলে, আমি এক বছর বয়সী ছিলাম এবং আমরা তার বাবার ছেলে সম্পর্কে কথা বলতে চাই, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তার উপহারের প্রতিজ্ঞা তাকে সমর্পণ করবেন। তারপর ফিরে আসবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَائِدُ فِي هِبَتِهِ كَالْكَلْبِ يَقِيءُ ثُمَّ يَعُودُ فِيهِ ‏","","",""],[2859,2859,"","আমরা একটা ছেলের কথা বলেছিলাম যে আমাকে একটা কুত্তার বাচ্চা হিসেবে ভালবাসতে চেয়েছিল, সে আমায় ছেড়ে দিলো, সে অনেক বড় কিছু করতে পারত। আমি তাকে বলেছিলাম যে তোমার মায়ের কোন ক্ষমতা নেই। ঈশ্বর.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ يَعْنِي ابْنَ فَرُّوخَ ‏ ‏حَدَّثَنَا ‏ ‏حَبِيبٌ يَعْنِي ابْنَ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَجُلًا دَخَلَ الْمَسْجِدَ فَقَامَ فَصَلَّى فَكَانَ إِذَا رَفَعَ رَأْسَهُ كَبَّرَ وَإِذَا وَضَعَ رَأْسَهُ كَبَّرَ وَإِذَا مَا نَهَضَ مِنْ الرَّكْعَتَيْنِ كَبَّرَ فَأَنْكَرْتُ ذَلِكَ فَأَتَيْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَأَخْبَرْتُهُ بِذَلِكَ فَقَالَ لَا أُمَّ لَكَ أَوَلَيْسَ تِلْكَ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2860,2860,"","আমরা ইশ্বরের সাথে কথা বলেছি, আমরা অনেক মানুষের জন্য অনেক বেশি কিছু করেছি যাদের ছেলে হয়েছে। তাকে আর আত্মসমর্পণ করতে হবে আর সে বলে যে তাকে করতে হবে, ঈশ্বর তার আত্মাকে দ্বিতীয় বার দেখে অথবা ঈশ্বরের কাছে তুলে নিয়ে যেতে হবে। আমি আগুন জ্বালাচ্ছি না, আমি সহজ এবং সুখী হব। ঈশ্বর কখনো তাঁকে পরিত্যাগ করেননি ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏نُوحُ بْنُ جَعْوَنَةَ السُّلَمِيُّ خُرَاسَانِيٌّ ‏ ‏عَنْ ‏ ‏مُقَاتِلِ بْنِ حَيَّانَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْمَسْجِدِ وَهُوَ يَقُولُ بِيَدِهِ هَكَذَا ‏ ‏فَأَوْمَأَ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏بِيَدِهِ إِلَى الْأَرْضِ ‏ ‏مَنْ أَنْظَرَ مُعْسِرًا أَوْ وَضَعَ لَهُ وَقَاهُ اللَّهُ مِنْ فَيْحِ جَهَنَّمَ أَلَا إِنَّ عَمَلَ الْجَنَّةِ حَزْنٌ بِرَبْوَةٍ ثَلَاثًا أَلَا إِنَّ عَمَلَ النَّارِ سَهْلٌ بِسَهْوَةٍ وَالسَّعِيدُ مَنْ وُقِيَ الْفِتَنَ وَمَا مِنْ جَرْعَةٍ أَحَبُّ إِلَيَّ مِنْ جَرْعَةِ غَيْظٍ يَكْظِمُهَا عَبْدٌ مَا كَظَمَهَا عَبْدٌ لِلَّهِ إِلَّا مَلَأَ اللَّهُ جَوْفَهُ إِيمَانًا ‏","","",""],[2861,2861,"","আমরা আপনাদের জন্য আমার এক অমর টাকার কথা বলেছি, ঈশ্বরের পুত্রের জন্য... ...একজন ভালবাসার সন্তান হিসেবে, ঈশ্বর তাকে আদেশ দিয়েছেন আর সে মৃত অবস্থায় আত্মসমর্পণ করেছে, যে ছিল সে মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِشَاةٍ مَيْتَةٍ فَقَالَ لِمَنْ كَانَتْ هَذِهِ الشَّاةُ فَقَالُوا ‏ ‏لِمَيْمُونَةَ ‏ ‏قَالَ أَفَلَا انْتَفَعْتُمْ بِإِهَابِهَا ‏","","",""],[2862,2862,"","বাবার চেয়ে ভালো উপায় খুঁজে পাওয়ার কথা বলেছিলাম, আমি ঈশ্বরের কাছে প্রার্থনা করব যেন তিনি এটা করতে পারেন আর তিনি কিছু দিনের মধ্যে মানুষের কাছে যাবেন.","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَرْتُ أَنَا ‏ ‏وَالْفَضْلُ ‏ ‏عَلَى ‏ ‏أَتَانٍ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِالنَّاسِ فِي فَضَاءٍ مِنْ الْأَرْضِ فَنَزَلْنَا وَدَخَلْنَا مَعَهُ فَمَا قَالَ لَنَا فِي ذَلِكَ شَيْئًا ‏","","",""],[2863,2863,"","বাবার সাথে কথা বলেছিলাম, তাকে ভালো ছেলে বানানোর পেছনে একটা কারণ আছে। আর আমি চলে যাব আর তাকে ভাড়া দিবো।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏زَمْعَةُ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏وَأَعْطَاهُ أَجْرَهُ ‏","","",""],[2864,2864,"","আমরা দুই দিনের কথা বলেছি একটা ছেলেকে খুঁজে বের করার জন্য যে কিনা তার নাম দেখে এসেছে। তাকে আত্মসমর্পণ করতে হবে এবং সূর্য থেকে নামার আগেই সে সব বাতির সাথে দাঁড়িয়ে থাকতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَفَ ‏ ‏بِجَمْعٍ ‏ ‏فَلَمَّا أَضَاءَ كُلُّ شَيْءٍ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ أَفَاضَ ‏","","",""],[2865,2865,"","আমরা একটা উলকি নিয়ে কথা বলেছিলাম আর একটা উলকির বিষয়ে বলেছিলাম যে আমরা হয়তো একটা ছেলেকে মেরে ফেলার চেষ্টা করব, যে তার ছেলেকে ব্যর্থ করবে? তাকে আত্মসমর্পণ করতে হবে যে সে তার কথা অনেক আগে দেখেছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَهَاشِمٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْبَخْتَرِيِّ ‏ ‏قَالَ ‏ ‏أَهْلَلْنَا هِلَالَ رَمَضَانَ وَنَحْنُ ‏ ‏بِذَاتِ عِرْقٍ ‏ ‏قَالَ فَأَرْسَلْنَا رَجُلًا إِلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏يَسْأَلُهُ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏فَسَأَلَهُ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ قَدْ مَدَّ رُؤْيَتَهُ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏لِرُؤْيَتِهِ ‏ ‏فَإِنْ أُغْمِيَ عَلَيْكُمْ فَأَكْمِلُوا الْعِدَّةَ ‏","","",""],[2866,2866,"","শেষ বার আমরা কথা বলেছিলাম আমার বাবার বাবার বাবার হাতে ঈশ্বরের হাত শোনার কারণ সে একজন বেশ্যার ছেলে, যে কিনা ছেলে ছিল, সে হরসি দিয়ে বলত, সে হরীটা দিয়ে আলোটা দেয়। যখন সে বাইরে গিয়েছিল এবং বললো যে এটা বাবার বলা হয়েছে কে বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏وَرْقَاءُ ‏ ‏سَمِعْتُ ‏ ‏عُبَيْدَ اللَّهِ بْنَ أَبِي يَزَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَلَاءَ فَوَضَعْتُ لَهُ وَضُوءًا فَلَمَّا خَرَجَ قَالَ مَنْ وَضَعَ ذَا قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ فَقِّهُّ فِي الدِّينِ ‏","","",""],[2867,2867,"","বাবা সম্বন্ধে আমরা তার সম্বন্ধে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ أَبِي وَحْشِيَّةَ أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ كُلِّ ذِي ‏ ‏نَابٍ مِنْ ‏ ‏السَّبُعِ ‏ ‏وَعَنْ كُلِّ ذِي مِخْلَبٍ مِنْ الطَّيْرِ ‏","","",""],[2868,2868,"","আমি যখন তাকে বলেছিলাম যে, আমি একজন যিহোবার সাক্ষি । সে তো কোন কুমারী নয়, সে আগুন থেকে এসেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى الثَّعْلَبِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اتَّقُوا الْحَدِيثَ عَنِّي إِلَّا مَا عَلِمْتُمْ قَالَ وَمَنْ كَذَبَ عَلَى الْقُرْآنِ بِغَيْرِ عِلْمٍ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[2869,2869,"","বাবা যখন মারা যান, তখন তিনি তার কাছে প্রার্থনা করেন এবং উত্তম কথা বলতে রাজি হন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلَ يَتَكَلَّمُ بِكَلَامٍ بَيِّنٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ الْبَيَانِ سِحْرًا وَإِنَّ مِنْ الشِّعْرِ حُكْمًا ‏","","",""],[2870,2870,"","আমরা এমন কয়েকটা জিনিস তৈরি করার কথা বলেছি, যা তার মনে ছিল। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং যখন তিনি আত্মসমর্পণ করেছেন তখন তিনি আত্মসমর্পণ করেছেন যখন তিনি বললেন যে ঈশ্বর ব্যর্থ হয়েছে এবং ব্যর্থ হয়েছে। যদি আপনি চান তাহলে আপনি চলে যাবেন। মরে যাও, তাকে ছেড়ে দাও, ওর হ্যান্ডলার এমনকি তার মৃত্যুর পরেও তাকে ছেড়ে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَاتَتْ شَاةٌ ‏ ‏لِسَوْدَةَ بِنْتِ زَمْعَةَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ مَاتَتْ فُلَانَةُ ‏ ‏يَعْنِي الشَّاةَ ‏ ‏فَقَالَ فَلَوْلَا أَخَذْتُمْ مَسْكَهَا فَقَالَتْ نَأْخُذُ مَسْكَ شَاةٍ قَدْ مَاتَتْ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏قُلْ لَا أَجِدُ فِيمَا أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَى طَاعِمٍ يَطْعَمُهُ إِلَّا أَنْ يَكُونَ مَيْتَةً أَوْ دَمًا مَسْفُوحًا أَوْ لَحْمَ خِنْزِيرٍ ‏} ‏فَإِنَّكُمْ لَا تَطْعَمُونَهُ إِنْ تَدْبُغُوهُ فَتَنْتَفِعُوا بِهِ فَأَرْسَلَتْ إِلَيْهَا فَسَلَخَتْ مَسْكَهَا فَدَبَغَتْهُ فَأَخَذَتْ مِنْهُ قِرْبَةً حَتَّى تَخَرَّقَتْ عِنْدَهَا ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏سَوْدَةَ بِنْتِ زَمْعَةَ ‏ ‏فَذَكَرَهُ ‏","","",""],[2871,2871,"","আমরা সাহায্যের জন্য একটি ভাল ছেলে থাকার কথা বলেছিলাম। তিনি বলেছিলেন, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং আপনার টাকা দিয়ে তিনি আপনার টাকা দেবেন। আমি আপনাকে কখনই বলিনি যে আপনার কাছে সৌভাগ্য আছে। আমি চেষ্টা করছি তাকে দেখতে চাই। বের হও।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِمَاعِزِ بْنِ مَالِكٍ ‏ ‏أَحَقٌّ مَا بَلَغَنِي عَنْكَ أَنَّكَ وَقَعْتَ عَلَى جَارِيَةِ بَنِي فُلَانٍ قَالَ فَشَهِدَ أَرْبَعَ شَهَادَاتٍ قَالَ فَرَجَمَهُ ‏","","",""],[2872,2872,"","আমরা আমাদের সময় রক্ষা করেছি এবং ঈশ্বরের কাছে যাচ্ছি, কিন্তু আমার ভালবাসার সাথে সুখী হওয়ার দুই মাস পর, ঈশ্বর তার জন্য প্রার্থনা করেন এবং আমার পাহাড়ি কামনায় আত্মসমর্পণ করেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏نَكَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَالَتِي ‏ ‏مَيْمُونَةَ الْهِلَالِيَّةَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[2873,2873,"","আমরা একজন বাবার সঙ্গে কথা বলেছিলাম, যিনি তার পর্দা বিক্রি করার চেষ্টা করেছিলেন । তাকে পানি আর মদ দিয়ে বেঁধে দুই ভাবে তাকে ভালো স্বাদ দেয়া হয় না, আর এমনকি তারা তাকে ভয় পায় না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُمْ خَرَجُوا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُحْرِمِينَ وَأَنَّ رَجُلًا مِنْهُمْ وَقَصَهُ بَعِيرُهُ فَمَاتَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اغْسِلُوهُ بِمَاءٍ ‏ ‏وَسِدْرٍ ‏ ‏وَكَفِّنُوهُ فِي ثَوْبَيْنِ وَلَا تُمِسُّوهُ طِيبًا وَلَا تُخَمِّرُوا رَأْسَهُ فَإِنَّهُ يُبْعَثُ يَوْمَ الْقِيَامَةِ مُلَبِّدًا ‏","","",""],[2874,2874,"","আমরা একটা কারণ তৈরি করার কথা বলেছিলাম, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন। সে বলবে না উড়ে যাওয়ার চেয়ে আর গুরুত্বপূর্ণ কিছু নেই। আমি প্রতিজ্ঞা করছি.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا طِيَرَةَ وَلَا عَدْوَى وَلَا هَامَةَ وَلَا صَفَرَ قَالَ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ إِنَّا لَنَأْخُذُ الشَّاةَ الْجَرْبَاءَ فَنَطْرَحُهَا فِي الْغَنَمِ فَتَجْرَبُ قَالَ فَمَنْ أَعْدَى الْأَوَّلَ ‏","","",""],[2875,2875,"","আমরা ঈশ্বরের সাথে আমাদের বাপ্তিস্মকে রক্ষা করার চেষ্টা করেছি, কিন্তু একজন মাত্র জন যোদ্ধা আছে, হয়তো সে তার জন্য প্রার্থনা করেছে আর যদি তাকে আমার হাতে আলো দিতে হয়, তাহলে তাকে পিটের মৃত্যুর মুখে ঠেলে দেয়া হবে। ঈশ্বর আপনাকে এটা দেন যে, ঋণের দায়ে তাদেরকে হত্যা করা এবং শিক্ষক হওয়াই হল ঈশ্বরের সবচেয়ে ভালো কাজ ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي بَيْتِ ‏ ‏مَيْمُونَةَ ‏ ‏فَوَضَعْتُ لَهُ وَضُوءًا مِنْ اللَّيْلِ قَالَ فَقَالَتْ ‏ ‏مَيْمُونَةُ ‏ ‏يَا رَسُولَ اللَّهِ وَضَعَ لَكَ هَذَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبَّاسٍ ‏ ‏فَقَالَ ‏ ‏اللَّهُمَّ فَقِّهُّ فِي الدِّينِ وَعَلِّمْهُ التَّأْوِيلَ ‏","","",""],[2876,2876,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তিনি যদি পুরোপুরি না হয়ে চলে যান, তাহলে তাকে রক্ষা করা হয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏فُلَانٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا مَشَى مَشَى مُجْتَمِعًا لَيْسَ فِيهِ كَسَلٌ ‏","","",""],[2877,2877,"","ঈশ্বর যে মন্দ নেতাদের বলেছিলেন, তাদের কাছে আমি ঈশ্বরকে জিজ্ঞেস করতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ أَوْلَادِ الْمُشْرِكِينَ قَالَ اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ إِذْ خَلَقَهُمْ ‏","","",""],[2878,2878,"","আমরা আমাদের সময় সম্পর্কে কথা বলেছি এবং এটা ছিল একটি খারাপ ছেলে হবার ব্যাপারে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আপনার পাপের দুর্দশার জন্য তাকে সমর্পণ করবেন। ভবিষ্যদ্বাণী.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَسُوا مِنْ ثِيَابِكُمْ الْبِيضَ فَإِنَّهَا مِنْ خَيْرِ ثِيَابِكُمْ وَكَفِّنُوا فِيهَا مَوْتَاكُمْ وَإِنَّ مِنْ خَيْرِ ‏ ‏أَكْحَالِكُمُ ‏ ‏الْإِثْمِدَ ‏ ‏إِنَّهُ ‏ ‏يَجْلُو الْبَصَرَ وَيُنْبِتُ الشَّعْرَ ‏","","",""],[2879,2879,"","ঈশ্বর তাঁর লোকেদের এই কথা বলার জন্য সমর্পণ করবেন এবং ঈশ্বর বিবাহবিচ্ছেদ করেছেন এবং ঈশ্বর বিনামূল্যে বলার স্বপ্ন দেখেছেন, আমি ফারকে ফেলে দেওয়ার আগে আমি মুক্ত ছিলাম এবং কখনো লজ্জিত হইনি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَهُ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏حَلَقْتُ وَلَمْ أَنْحَرْ قَالَ لَا حَرَجَ وَجَاءَهُ آخَرُ فَقَالَ يَا رَسُولَ اللَّهِ نَحَرْتُ قَبْلَ أَنْ أَرْمِيَ قَالَ فَارْمِ وَلَا حَرَجَ ‏","","",""],[2880,2880,"","আমরা আমাদের সময় নিয়ে কথা বলেছি আর এটা একটা ভালো ছেলে থাকার কথা ছিল। আমি তাকে বলতে চাই যে সে ঈশ্বরের কাছে প্রার্থনা করছে তাকে তার পিতা হতে হবে নাকি ঈশ্বর বলে দাবি করা হয়েছে। ''আর তোমাদের ও তোমাদের পরিবার-পরিজনকে একসঙ্গে জবাই কর,","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ سَمِعَهُ يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ادَّعَى إِلَى غَيْرِ أَبِيهِ أَوْ تَوَلَّى غَيْرَ مَوَالِيهِ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ ‏","","",""],[2881,2881,"","আমরা একটা ঘোড়ার কথা বলেছিলাম কিন্তু একটা ঘোড়া একটা ছেলে বিচার করার চেষ্টা করেছিল, সে ঈশ্বরের ইচ্ছার উপর ছুড়েছে, ঈশ্বরের কাছে আছে, আর জামমার তার স্পর্শ করার পর জমকে দেয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏رَمَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجِمَارَ بَعْدَ مَا زَالَتْ الشَّمْسُ ‏","","",""],[2882,2882,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং শান্তির বন্ধনের বশীভূত হওয়ার ক্ষেত্রে তিনি তা - ই থাকবেন । এটা ভুলে যাও।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُخَوَّلِ بْنِ رَاشِدٍ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي صَلَاةِ الْفَجْرِ يَوْمَ الْجُمُعَةِ ‏ ‏تَنْزِيلُ السَّجْدَةِ ‏ ‏وَهَلْ أَتَى عَلَى الْإِنْسَانِ ‏","","",""],[2883,2883,"","আমরা বাবার সাথে কথা বলেছিলাম একটা ছেলেকে সাহায্য করার কারন নিয়ে আমি নই, তুমি ঘোড়ার মেয়ের সাথে ডাইনি, যে ঈশ্বর আমাকে দিয়েছে আর আমাকে কিছু নাম আর কিছু কথা বলে ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তার সকল মঙ্গলভাবের কাছে আত্মসমর্পণ করেছেন এবং তাদেরকে ঈশ্বরের কাছে ছেড়ে দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏أُمَّ حُفَيْدٍ بِنْتَ الْحَارِثِ بْنِ حَزْنٍ ‏ ‏خَالَةَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَهْدَتْ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمْنًا وَأَقِطًا وَأَضُبًّا قَالَ فَدَعَا بِهِنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأُكِلْنَ عَلَى مَائِدَتِهِ وَتَرَكَهُنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَالْمُتَقَذِّرِ ‏ ‏فَلَوْ كُنَّ حَرَامًا مَا أُكِلْنَ عَلَى مَائِدَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا أَمَرَ بِأَكْلِهِنَّ ‏","","",""],[2884,2884,"","আমরা আমার কথোপকথন সম্পর্কে কথা বলছিলাম, কিন্তু আমি শুনেছি একটি ছেলে যে বলেছে সে পুত্র, ঈশ্বরের দয়া তাকে আদেশ দিয়েছে আর সে পৃথিবীর চেহারা দেখার জন্য পরিচিত হবে। ঈশ্বর আমার ভাতিজাকে হাতে তুলে দিতে বলেছেন যে, তিনি তার নিজের রাজা এবং তিনি তার কথা শুনবেন । তার ছেলে ক্ষমা পেয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنِي ‏ ‏سُكَيْنُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ فُلَانٌ رَدِيفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏قَالَ فَجَعَلَ الْفَتَى يُلَاحِظُ النِّسَاءَ وَيَنْظُرُ إِلَيْهِنَّ قَالَ وَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْرِفُ وَجْهَهُ بِيَدِهِ مِنْ خَلْفِهِ مِرَارًا قَالَ وَجَعَلَ الْفَتَى يُلَاحِظُ إِلَيْهِنَّ قَالَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنَ أَخِي ‏ ‏إِنَّ هَذَا يَوْمٌ مَنْ مَلَكَ فِيهِ سَمْعَهُ وَبَصَرَهُ وَلِسَانَهُ غُفِرَ لَهُ ‏","","",""],[2885,2885,"","আমরা বলেছিলাম তিনি ঈশ্বরের জন্য একটি কারণ নির্মাণ করা হয়েছে. তিনি আত্মসমর্পণ তিনি হবে তিনি একটি চুমু তিনি হবে তিনি হবে হবে যে তিনি হবে একটি চুম্বন হবে হবে হবে হবে যে আপনি কথা এবং প্রতিজ্ঞা. তোমার কিছু করার আছে, আমার মনে হয় সে তোমার লর্ডের জয় করবে আর সে জিতবে, আর তারা হবে মাস্টার","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَهُوَ فِي ‏ ‏قُبَّةٍ ‏ ‏يَوْمَ ‏ ‏بَدْرٍ ‏ ‏اللَّهُمَّ إِنِّي أَنْشُدُكَ عَهْدَكَ وَوَعْدَكَ اللَّهُمَّ إِنْ شِئْتَ لَمْ تُعْبَدْ بَعْدَ الْيَوْمِ فَأَخَذَ ‏ ‏أَبُو بَكْرٍ ‏ ‏بِيَدِهِ فَقَالَ حَسْبُكَ يَا رَسُولَ اللَّهِ فَقَدْ أَلْحَحْتَ عَلَى رَبِّكَ وَهُوَ يَثِبُ فِي الدِّرْعِ فَخَرَجَ وَهُوَ يَقُولُ ‏ { ‏سَيُهْزَمُ الْجَمْعُ وَيُوَلُّونَ ‏ ‏الدُّبُرَ ‏ }","","",""],[2886,2886,"","আমরা একটি ছেলে খুঁজে পেতে কিছু একটা করেছে সম্পর্কে কথা বলেছিলাম, যে হয়তো আপনার জন্য একটা ছেলে খুঁজে বের করতে পারে। করুণা থেকে মুক্ত নয় ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُرِيدَ عَلَى ‏ ‏بِنْتِ حَمْزَةَ ‏ ‏فَقَالَ ‏ ‏إِنَّهَا ابْنَةُ أَخِي مِنْ الرَّضَاعَةِ وَإِنَّهَا لَا تَحِلُّ لِي وَيَحْرُمُ مِنْ الرَّضَاعَةِ مَا يَحْرُمُ مِنْ الرَّحِمِ ‏","","",""],[2887,2887,"","আমরা বাবার সাথে যা ঘটেছে তার একটি খেলা তৈরি করতে বলেছিলাম। ঈশ্বর তাকে আদেশ দিয়েছেন এবং তিনি প্রার্থনা করবেন যে তিনি তাকে পরাজিত করবেন। আমি আমার বাবা-মা আমাকে অনেক কিছু বলে, অথবা আমি দেখতে পারি কে। আমি দেখলাম সে মিথ্যা বলেছে কিনা আর সে বলে যে, যদি সে তার হাতে হাত ধরে তাড়ত, তাহলে সে তার হাতে জিতে যেত ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏أَبُو جَهْلٍ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فَنَهَاهُ فَتَهَدَّدَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَتُهَدِّدُنِي أَمَا وَاللَّهِ إِنِّي لَأَكْثَرُ أَهْلِ ‏ ‏الْوَادِي ‏ ‏نَادِيًا فَأَنْزَلَ اللَّهُ ‏ { ‏أَرَأَيْتَ الَّذِي يَنْهَى عَبْدًا إِذَا صَلَّى أَرَأَيْتَ إِنْ كَانَ عَلَى الْهُدَى أَوْ أَمَرَ بِالتَّقْوَى أَرَأَيْتَ إِنْ كَذَّبَ وَتَوَلَّى ‏} ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ لَوْ دَعَا نَادِيَهُ لَأَخَذَتْهُ الزَّبَانِيَةُ ‏","","",""],[2888,2888,"","আমরা একটা শিক্ষা সম্পর্কে কথা বলেছিলাম, আমরা জানি সে কিভাবে একজন বাবাকে চিনত যে তাকে চেনে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَرَفَعَهُ قَالَ ‏ ‏مَا كَانَ مِنْ حِلْفٍ فِي الْجَاهِلِيَّةِ لَمْ يَزِدْهُ الْإِسْلَامُ إِلَّا حِدَّةً وَشِدَّةً ‏","","",""],[2889,2889,"","ঈশ্বর তাকে একটা মই দিতে বলেছেন যে পাথরটা হল আকাশের কালো কালো এবং আমি তুষারের এক সাদা ছেলেকে দেখতে পেতাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْحَجَرُ الْأَسْوَدُ مِنْ الْجَنَّةِ وَكَانَ أَشَدَّ بَيَاضًا مِنْ الثَّلْجِ حَتَّى سَوَّدَتْهُ خَطَايَا أَهْلِ الشِّرْكِ ‏","","",""],[2890,2890,"","ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তিনি হয়তো তার সঙ্গে দেখা করতে গিয়ে মারা যাবেন । তাকে খেতে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشَاةٍ مَيْتَةٍ قَدْ أَلْقَاهَا أَهْلُهَا فَقَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَلدُّنْيَا أَهْوَنُ عَلَى اللَّهِ مِنْ هَذِهِ عَلَى أَهْلِهَا ‏","","",""],[2891,2891,"","আমরা কথা বলেছি কঠিন হওয়া নিয়ে, আমরা একটা ছেলের জন্য মজা করার কথা বলেছিলাম, আমি আবার আবার ঈশ্বরের কাছে ফিরে যাব, ঈশ্বরের কাছে প্রার্থনা করব, তার কাছে প্রার্থনা করব এবং তাকে একটা উপহার দেব। একটু.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏سَعْدَ بْنَ عُبَادَةَ ‏ ‏اسْتَفْتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نَذْرٍ كَانَ عَلَى أُمِّهِ تُوُفِّيَتْ قَبْلَ أَنْ تَقْضِيَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْضِ عَنْهَا ‏","","",""],[2892,2892,"","আমি যখন তাকে জিজ্ঞেস করি যে, আমি যদি তার কাছে প্রার্থনা করি, তা হলে তিনি ঈশ্বরের সঙ্গে তার সম্পর্ককে আরও দৃঢ় করবেন । তার মালিককে তার সাথেও আমার ভাইকে জিজ্ঞেস করতে হবে, বাতাস তোমার বাবার ব্যাপারে একটা তর্ক করবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ امْرَأَةً مِنْ ‏ ‏خَثْعَمَ ‏ ‏سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ ‏ ‏وَالْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏رَدِيفُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ فَرِيضَةَ اللَّهِ فِي الْحَجِّ عَلَى عِبَادِهِ أَدْرَكَتْ أَبِي شَيْخًا كَبِيرًا لَا يَسْتَطِيعُ أَنْ يَسْتَمْسِكَ عَلَى الرَّاحِلَةِ أَفَأَحُجُّ عَنْهُ فَقَالَ ‏ ‏نَعَمْ حُجِّي عَنْ أَبِيكِ ‏","","",""],[2893,2893,"","আমাকে একজন কঠোর শ্রমিক বলা হয়েছে যে আমার বিয়ের কথা বলেছে... ...ঈশ্বরের ভালবাসার জন্য প্রার্থনা করেছে, আর আমাদের ছেলেকে মদ দিয়ে পানি খেতে বলেছে। রক্তপাত হয়েছিল।","‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَرِبَ لَبَنًا ثُمَّ دَعَا بِمَاءٍ فَمَضْمَضَ وَقَالَ إِنَّ لَهُ دَسَمًا ‏","","",""],[2894,2894,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি একজন মৃত মেয়েকে আত্মসমর্পণ করবেন, যিনি বলেছিলেন যে, তার সঙ্গে নেই বলে নয় । নিজের জীবনের সাথে সন্তুষ্ট, আমি এটা খাই।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشَاةٍ مَيْتَةٍ فَقَالَ ‏ ‏أَلَا ‏ ‏اسْتَمْتَعْتُمْ بِجِلْدِهَا قَالُوا يَا رَسُولَ اللَّهِ إِنَّهَا مَيْتَةٌ قَالَ إِنَّمَا حَرُمَ أَكْلُهَا ‏","","",""],[2895,2895,"","আমরা আমার বাবা প্রথম বারের মত ঈর্ষার কথা বলেছিলাম, আমার ছেলেকে একটা ভিক্ষু দিতে চেয়েছিলাম যে কোন যাজক না। ঈশ্বর তাকে জানেন এবং সে মেমিহকে বিয়ে করবে এবং সে একজন সে একজন মানুষ। যুদ্ধেরলক।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ أَبِي رَبَاحٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَزَوَّجَ ‏ ‏مَيْمُونَةَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[2896,2896,"","আমরা একটা ছেলে কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তাকে একটা শহরতলীতে তার জীবনে প্রবেশ করতে বাধ্য করেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْكَرِيمِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏ضُبَاعَةَ ‏ ‏أَنْ تَشْتَرِطَ فِي إِحْرَامِهَا ‏","","",""],[2897,2897,"","আমরা তার কিছু ভাইদের সম্বন্ধে কথা বলেছিলাম, যারা আমার সঙ্গে আমার প্রেমের সঙ্গে বাপ্তাইজিত হয়েছে । আমি তাকে বিশ্বাস করি, লর্ডের কাছে প্রার্থনা করা বন্ধ করে দেওয়া হবে, কারণ সে বলেছে আমার ছেলে নেই। আমাদের পরিবর্তন করার পর আমি তাকে আরো ভাল করার জন্য নিয়ে এসেছি। আমি যা বলেছি, মাস্টারের হাতে... ...এই অনুষ্ঠানের সবচেয়ে পবিত্র হাত।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏بَعْضِ إِخْوَانِهِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عُبَيْدٍ الْمَكِّيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏إِنَّ رَجُلًا قَدِمَ عَلَيْنَا يُكَذِّبُ بِالْقَدَرِ فَقَالَ دُلُّونِي عَلَيْهِ وَهُوَ يَوْمَئِذٍ قَدْ عَمِيَ قَالُوا وَمَا تَصْنَعُ بِهِ يَا ‏ ‏أَبَا عَبَّاسٍ ‏ ‏قَالَ وَالَّذِي نَفْسِي بِيَدِهِ لَئِنْ اسْتَمْكَنْتُ مِنْهُ لَأَعَضَّنَّ أَنْفَهُ حَتَّى أَقْطَعَهُ وَلَئِنْ وَقَعَتْ رَقَبَتُهُ فِي يَدَيَّ لَأَدُقَّنَّهَا فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كَأَنِّي بِنِسَاءِ ‏ ‏بَنِي فِهْرٍ ‏ ‏يَطُفْنَ بِالْخَزْرَجِ تَصْطَكُّ أَلْيَاتُهُنَّ مُشْرِكَاتٍ هَذَا أَوَّلُ شِرْكِ هَذِهِ الْأُمَّةِ وَالَّذِي نَفْسِي بِيَدِهِ لَيَنْتَهِيَنَّ بِهِمْ سُوءُ رَأْيِهِمْ حَتَّى يُخْرِجُوا اللَّهَ مِنْ أَنْ يَكُونَ قَدَّرَ خَيْرًا كَمَا أَخْرَجُوهُ مِنْ أَنْ يَكُونَ قَدَّرَ شَرًّا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِيَ ‏ ‏الْعَلَاءُ بْنُ الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عُبَيْدٍ الْمَكِّيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏بِهَذَا الْحَدِيثِ ‏ ‏قُلْتُ ‏ ‏أَدْرَكَ ‏ ‏مُحَمَّدٌ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ نَعَمْ ‏","","",""],[2898,2898,"","আমরা যে ঈর্ষাপরায়ণ বাবার কথা বলেছিলাম সে আমার বাবাকে ভালো নাম দেবে। একজন মানুষকে বলে যে আমি তার পতাকা আর তার মই। ( ১ রাজা.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ ‏ ‏بَلَغَنِي ‏ ‏أَنَّ ‏ ‏عَطَاءَ بْنَ أَبِي رَبَاحٍ ‏ ‏قَالَ إِنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يُخْبِرُ ‏ ‏أَنَّ رَجُلًا أَصَابَهُ جُرْحٌ فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ ‏ ‏أَصَابَهُ احْتِلَامٌ فَأُمِرَ ‏ ‏بِالِاغْتِسَالِ فَمَاتَ فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏قَتَلُوهُ قَتَلَهُمْ اللَّهُ أَلَمْ يَكُنْ شِفَاءَ ‏ ‏الْعِيِّ ‏ ‏السُّؤَالُ ‏","","",""],[2899,2899,"","আমি বাবার সঙ্গে আরও ভাল কিছু পাওয়ার চেষ্টা করার বিষয়ে কথা বলেছিলাম । আর একবার, তারপর তোমাকে আটকে রাখা হবে, তার দরজা দিয়ে হবে কিভাবে আমি এটা করতে পারি...","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْدَفَهُ عَلَى دَابَّتِهِ فَلَمَّا اسْتَوَى عَلَيْهَا ‏ ‏كَبَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثًا وَحَمِدَ اللَّهَ ثَلَاثًا وَسَبَّحَ اللَّهَ ثَلَاثًا وَهَلَّلَ اللَّهَ وَاحِدَةً ثُمَّ اسْتَلْقَى عَلَيْهِ فَضَحِكَ ثُمَّ أَقْبَلَ ‏ ‏عَلَيَّ ‏ ‏فَقَالَ مَا مِنْ امْرِئٍ يَرْكَبُ دَابَّتَهُ فَيَصْنَعُ كَمَا صَنَعْتُ إِلَّا أَقْبَلَ اللَّهُ تَبَارَكَ وَتَعَالَى فَضَحِكَ إِلَيْهِ كَمَا ضَحِكْتُ إِلَيْكَ ‏","","",""],[2900,2900,"","আমি বলেছিলাম যে, লোকেদের কাছে প্রার্থনা করা হচ্ছে এবং আমি বলেছিলাম যে, লোকেরা যাতে লোকেদের গড়ে তুলতে পারে । যে ভাবে ছেলেটি সৃষ্টিকর্তা এটা রক্ষা করেছে এবং বলা হয়েছে যে জনতা মাথা বন্ধ করে দিচ্ছে এবং আপনি একজন ভাল মানুষ হবেন না এবং তারা হত্যা করত ছেলে না খারাপ লোক।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبٌ ‏ ‏قَالَ سُئِلَ ‏ ‏الزُّهْرِيُّ ‏ ‏هَلْ فِي الْجُمُعَةِ غُسْلٌ وَاجِبٌ ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ جَاءَ مِنْكُمْ الْجُمُعَةَ فَلْيَغْتَسِلْ ‏ ‏و قَالَ ‏ ‏طَاوُسٌ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏ذَكَرُوا أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اغْتَسِلُوا يَوْمَ الْجُمُعَةِ وَاغْسِلُوا رُءُوسَكُمْ وَإِنْ لَمْ تَكُونُوا جُنُبًا وَأَصِيبُوا مِنْ الطِّيبِ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَمَّا الْغُسْلُ فَنَعَمْ وَأَمَّا الطِّيبُ فَلَا أَدْرِي ‏","","",""],[2901,2901,"","ঈশ্বর আমার বাবার হাতে এই প্ল্যান করেছেন আমাদের সাথে এমনটি ঘটেছে যেন সে আমাদের যেতে না দেয়। পৃথিবীতে জন্ম দেয়া হোক, নারী এবং পুরুষের প্রতি নারীর সন্দেহ","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ هَذَا الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ الْوَاصِلَةَ وَالْمَوْصُولَةَ وَالْمُتَشَبِّهِينَ مِنْ الرِّجَالِ بِالنِّسَاءِ وَالْمُتَشَبِّهَاتِ مِنْ النِّسَاءِ بِالرِّجَالِ ‏","","",""],[2902,2902,"","আমরা ঈশ্বরের আশীর্বাদের কথা বলেছিলাম আমার বাবা বা বাবা, যাকে আমরা জন্ম দিয়েছিলাম। একজন যাজকের ছেলে বলেছিলেন, আমি ঈশ্বরের কাছে প্রার্থনা করি এবং আত্মসমর্পণ করি। গত রাতে আমি তোমাকে এটা থেকে বাঁচাতে তার জুতা গ্রহণ করেছি, ঈশ্বরের অনুগ্রহে তিনি তার প্রার্থনা পৌঁছে দিয়েছেন এবং তার প্রার্থনা পৌঁছে দিয়েছেন। পাপ চলে যায় আর আল্লাহ্‌ বা ঈশ্বরকে বলে আমি কখনো ভুলবো না। ঈশ্বর তোমাকে আমার ঈশ্বর বলেছেন আমি তাকে ভালবাসি, তারপর তাকে একটা পতাকা ফিরিয়ে দিতে দাও। আমি তাকে ঘুম থেকে উঠার আগ পর্যন্ত ঘুম পাড়িয়ে দিয়েছি। প্রার্থনা ছাড়া তাকে মেরে ফেলো.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏حَاتِمُ بْنُ أَبِي صَغِيرَةَ أَبُو يُونُسَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏أَنَّ ‏ ‏كُرَيْبًا ‏ ‏أخْبَرَهُ أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ آخِرِ اللَّيْلِ فَصَلَّيْتُ خَلْفَهُ فَأَخَذَ بِيَدِي فَجَرَّنِي فَجَعَلَنِي حِذَاءَهُ فَلَمَّا أَقْبَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى صَلَاتِهِ ‏ ‏خَنَسْتُ ‏ ‏فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا انْصَرَفَ قَالَ لِي مَا شَأْنِي أَجْعَلُكَ حِذَائِي ‏ ‏فَتَخْنِسُ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَوَيَنْبَغِي لِأَحَدٍ أَنْ يُصَلِّيَ حِذَاءَكَ وَأَنْتَ رَسُولُ اللَّهِ الَّذِي أَعْطَاكَ اللَّهُ قَالَ فَأَعْجَبْتُهُ ‏ ‏فَدَعَا اللَّهَ لِي أَنْ يَزِيدَنِي عِلْمًا وَفَهْمًا قَالَ ثُمَّ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَامَ حَتَّى سَمِعْتُهُ يَنْفُخُ ثُمَّ أَتَاهُ ‏ ‏بِلَالٌ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ الصَّلَاةَ فَقَامَ فَصَلَّى مَا أَعَادَ وُضُوءًا ‏","","",""],[2903,2903,"","বাবা যখন এ বিষয়ে কথা বলত, তখন আমরা ঈশ্বরের সাথে কথা বলেছিলাম, যখন বাবা এ বিষয়ে কথা বলেছিলাম, সে বলত আমি একজন যাজকের ছেলে হব যদি আমি তাকে সাহায্য করতে পারি, বাবা বলেন তোমার সাথে জুয়া খেলার সময় সে শুরু হওয়ার আগেই ভুল ছিল। তারা বললো যে সে হঠাৎ করে তার কাপড় থেকে পালিয়ে যায় আর বলে যে ১০ জন পড়ে যায় আমি এমন একজনকে বিক্রি করবো যে কখনো তার জন্য লজ্জা পাবে না। তাকে ওর জীবনের অর্ধেক ছায়ার মাঝে অবাক করে দিয়ে সে তার হৃদয়ের কথা শোনে। সে আমার কাছে যায় না আর আমি আমার চাচাতো ভাইয়ের কাছে বলছি যে তুমি ঋণের মধ্যে আছো আর তার কাছে। সে বলেছে, আমি ঋণের মধ্যে আছি, আর অন্য জন বলেছে তুমি ঋণ পেয়েছ। সে আমাকে দেনা ধারের ঋণ দাও আর অন্য জন বলেছে যে আমরা ঋণের মধ্যে আছি। প্রথমে মানুষ উদ্ধার করা হলো... ...যখন তিনি নেতৃত্ব নেন এবং প্রভুর ইচ্ছা নিয়ে নেন. সে তার আত্মা ষাঁড়ের উপর পড়ে থাকতে দেখেছে, ঈশ্বর সেটা জানেন এবং তারপর সে তার নিজের জায়গায় ঘুমাবে, আর ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তার সেরাটা করার সাথে সাথে সাথে তিনি তার সেরাটা দিয়েছেন। আমার বাবা তার গাউনে জন্মগ্রহণ করেছিলেন । আপনি বলেছিলেন মানুষ বিয়েতে গিয়েছিল আপনি বলেছিলেন তিনি বলতে হবে তিনি বলেন তিনি আমাকে বলতে হবে যে আপনি আমার থেকে এসেছেন আমার মধ্যে একজন যে মোটেল থেকে এসেছে যার কোন ছেলে নেই। যদি আপনি আমার উত্তরদাতা হন, তিনি বলেন তিনি আছেন প্রভু, আপনি আমার অভিভাবক, তারা বলে যে আপনি আমার অভিভাবক, তিনি একটি কাপুরুষ খুঁজে পেতে যাচ্ছে এবং তিনি তার একটি উপায় আছে না বলার, কোরআন কোরআন এ, তিনি হয়তো সন্তুষ্ট হতে পারে. ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তিনি যদি আপনাকে বলেন যে তিনি আপনার অবস্থানের জন্য তাকে ক্ষমা করে দিয়েছেন, তা হলে তিনি তাঁর পদকে অগ্রাহ্য করবেন । সে-ই হবে যে , এ ব ্ যক ্ তিজে থাকবে এবং সে ব ্ যর ্ থ হবে যে , সে ব ্ যক ্ তি হবে , এমন একজন যে হবে সেই হবে সেই হবে সেই রাজা হবে। আমাকে বলা হয়েছে, যা ঘটেছে তার অনেক কিছুই হত্যা করতে। আমরা যখন এত কিছু বলার চেষ্টা করতাম, তখন আমরা দাসের সন্তান লাভ করার জন্য আমাদের ভালোবাসি ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَلْجٍ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ مَيْمُونٍ ‏ ‏قَالَ ‏ ‏إِنِّي لَجَالِسٌ إِلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏إِذْ أَتَاهُ تِسْعَةُ رَهْطٍ فَقَالُوا يَا ‏ ‏أَبَا عَبَّاسٍ ‏ ‏إِمَّا أَنْ تَقُومَ مَعَنَا وَإِمَّا أَنْ ‏ ‏يُخْلُونَا هَؤُلَاءِ قَالَ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏بَلْ أَقُومُ مَعَكُمْ قَالَ وَهُوَ يَوْمَئِذٍ صَحِيحٌ قَبْلَ أَنْ ‏ ‏يَعْمَى قَالَ فَابْتَدَءُوا فَتَحَدَّثُوا فَلَا نَدْرِي مَا قَالُوا قَالَ فَجَاءَ يَنْفُضُ ثَوْبَهُ وَيَقُولُ أُفْ وَتُفْ وَقَعُوا فِي رَجُلٍ لَهُ عَشْرٌ وَقَعُوا فِي رَجُلٍ قَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَبْعَثَنَّ رَجُلًا لَا ‏ ‏يُخْزِيهِ اللَّهُ أَبَدًا يُحِبُّ اللَّهَ وَرَسُولَهُ قَالَ فَاسْتَشْرَفَ لَهَا مَنْ اسْتَشْرَفَ قَالَ أَيْنَ ‏ ‏عَلِيٌّ ‏ ‏قَالُوا هُوَ فِي ‏ ‏الرَّحْلِ ‏ ‏يَطْحَنُ قَالَ وَمَا كَانَ أَحَدُكُمْ لِيَطْحَنَ قَالَ فَجَاءَ وَهُوَ أَرْمَدُ لَا يَكَادُ يُبْصِرُ قَالَ فَنَفَثَ فِي عَيْنَيْهِ ثُمَّ هَزَّ الرَّايَةَ ثَلَاثًا فَأَعْطَاهَا إِيَّاهُ فَجَاءَ ‏ ‏بِصَفِيَّةَ بِنْتِ حُيَيٍّ ‏ ‏قَالَ ثُمَّ بَعَثَ فُلَانًا بِسُورَةِ ‏ ‏التَّوْبَةِ ‏ ‏فَبَعَثَ ‏ ‏عَلِيًّا ‏ ‏خَلْفَهُ فَأَخَذَهَا مِنْهُ قَالَ لَا يَذْهَبُ بِهَا إِلَّا رَجُلٌ مِنِّي وَأَنَا مِنْهُ قَالَ وَقَالَ لِبَنِي عَمِّهِ أَيُّكُمْ ‏ ‏يُوَالِينِي فِي الدُّنْيَا وَالْآخِرَةِ قَالَ ‏ ‏وَعَلِيٌّ ‏ ‏مَعَهُ جَالِسٌ فَأَبَوْا فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏أَنَا ‏ ‏أُوَالِيكَ فِي الدُّنْيَا وَالْآخِرَةِ قَالَ أَنْتَ وَلِيِّي فِي الدُّنْيَا وَالْآخِرَةِ قَالَ فَتَرَكَهُ ثُمَّ أَقْبَلَ عَلَى رَجُلٍ مِنْهُمْ فَقَالَ أَيُّكُمْ ‏ ‏يُوَالِينِي فِي الدُّنْيَا وَالْآخِرَةِ فَأَبَوْا قَالَ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏أَنَا ‏ ‏أُوَالِيكَ فِي الدُّنْيَا وَالْآخِرَةِ فَقَالَ أَنْتَ وَلِيِّي فِي الدُّنْيَا وَالْآخِرَةِ قَالَ وَكَانَ أَوَّلَ مَنْ أَسْلَمَ مِنْ النَّاسِ بَعْدَ ‏ ‏خَدِيجَةَ ‏ ‏قَالَ وَأَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَوْبَهُ فَوَضَعَهُ عَلَى ‏ ‏عَلِيٍّ ‏ ‏وَفَاطِمَةَ ‏ ‏وَحَسَنٍ ‏ ‏وَحُسَيْنٍ ‏ ‏فَقَالَ ‏ { ‏إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمْ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا ‏} ‏قَالَ وَشَرَى ‏ ‏عَلِيٌّ ‏ ‏نَفْسَهُ لَبِسَ ثَوْبَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ نَامَ مَكَانَهُ قَالَ وَكَانَ الْمُشْرِكُونَ يَرْمُونَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعَلِيٌّ ‏ ‏نَائِمٌ قَالَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏يَحْسَبُ أَنَّهُ نَبِيُّ اللَّهِ قَالَ فَقَالَ يَا نَبِيَّ اللَّهِ قَالَ فَقَالَ لَهُ ‏ ‏عَلِيٌّ ‏ ‏إِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ انْطَلَقَ نَحْوَ ‏ ‏بِئْرِ مَيْمُونٍ ‏ ‏فَأَدْرِكْهُ قَالَ فَانْطَلَقَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَدَخَلَ مَعَهُ الْغَارَ قَالَ وَجَعَلَ ‏ ‏عَلِيٌّ ‏ ‏يُرْمَى بِالْحِجَارَةِ كَمَا كَانَ ‏ ‏يُرْمَى نَبِيُّ اللَّهِ وَهُوَ يَتَضَوَّرُ قَدْ لَفَّ رَأْسَهُ فِي الثَّوْبِ لَا يُخْرِجُهُ حَتَّى أَصْبَحَ ثُمَّ كَشَفَ عَنْ رَأْسِهِ فَقَالُوا إِنَّكَ لَلَئِيمٌ كَانَ صَاحِبُكَ ‏ ‏نَرْمِيهِ فَلَا يَتَضَوَّرُ وَأَنْتَ تَتَضَوَّرُ وَقَدْ اسْتَنْكَرْنَا ذَلِكَ قَالَ وَخَرَجَ بِالنَّاسِ فِي ‏ ‏غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏قَالَ فَقَالَ لَهُ ‏ ‏عَلِيٌّ ‏ ‏أَخْرُجُ مَعَكَ قَالَ فَقَالَ لَهُ نَبِيُّ اللَّهِ لَا فَبَكَى ‏ ‏عَلِيٌّ ‏ ‏فَقَالَ لَهُ أَمَا ‏ ‏تَرْضَى أَنْ تَكُونَ مِنِّي بِمَنْزِلَةِ ‏ ‏هَارُونَ ‏ ‏مِنْ ‏ ‏مُوسَى ‏ ‏إِلَّا أَنَّكَ لَسْتَ بِنَبِيٍّ إِنَّهُ لَا ‏ ‏يَنْبَغِي أَنْ أَذْهَبَ إِلَّا وَأَنْتَ خَلِيفَتِي قَالَ وَقَالَ لَهُ رَسُولُ اللَّهِ أَنْتَ وَلِيِّي فِي كُلِّ مُؤْمِنٍ بَعْدِي وَقَالَ سُدُّوا أَبْوَابَ الْمَسْجِدِ غَيْرَ بَابِ ‏ ‏عَلِيٍّ ‏ ‏فَقَالَ فَيَدْخُلُ الْمَسْجِدَ جُنُبًا وَهُوَ طَرِيقُهُ لَيْسَ لَهُ طَرِيقٌ غَيْرُهُ قَالَ وَقَالَ مَنْ كُنْتُ مَوْلَاهُ فَإِنَّ مَوْلَاهُ ‏ ‏عَلِيٌّ ‏ ‏قَالَ وَأَخْبَرَنَا اللَّهُ عَزَّ وَجَلَّ فِي الْقُرْآنِ أَنَّهُ قَدْ رَضِيَ عَنْهُمْ عَنْ ‏ ‏أَصْحَابِ الشَّجَرَةِ ‏ ‏فَعَلِمَ مَا فِي قُلُوبِهِمْ هَلْ حَدَّثَنَا أَنَّهُ سَخِطَ عَلَيْهِمْ بَعْدُ قَالَ وَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِعُمَرَ ‏ ‏حِينَ قَالَ ائْذَنْ لِي فَلْأَضْرِبْ عُنُقَهُ قَالَ أَوَكُنْتَ فَاعِلًا وَمَا يُدْرِيكَ لَعَلَّ اللَّهَ قَدْ اطَّلَعَ إِلَى أَهْلِ ‏ ‏بَدْرٍ ‏ ‏فَقَالَ اعْمَلُوا مَا شِئْتُمْ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَالِكٍ كَثِيرُ بْنُ يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَلْجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏نَحْوَهُ ‏","","",""],[2904,2904,"","আমরা আমাদের প্রিয় ছেলের কথা বলেছিলাম, আমরা একটা বাচ্চাকে বলেছিলাম । তারপর সে তার দেশে পৌঁছে যাবে যখন সে তার কাছে এসেছে আর সে আমাকে আমার সব চোখ দিয়ে দেবে, আমি তাদেরকে চুমু দিবো যতক্ষণ না মহিলারা আসে আর সে বলে যে এটা একটা ভালো সংবাদ। এটা এমনকি তার আনন্দের একটা আলো, আর তারপর তিনি বলেছেন যখন তাকে ছেড়ে দেওয়া হয়, তিনি বলেছিলেন যে তিনি শপথ নিতে যাচ্ছেন। আমরা করি, ঈশ্বর ভাল আছেন কে? আমার মা আমাকে বলেছিলেন যে, আমি তার সঙ্গে বাইবেল অধ্যয়ন করতে চাই ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏حَسَنُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏شَهِدْتُ الصَّلَاةَ يَوْمَ الْفِطْرِ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏فَكُلُّهُمْ كَانَ يُصَلِّيهَا قَبْلَ الْخُطْبَةِ ثُمَّ يَخْطُبُ بَعْدُ قَالَ فَنَزَلَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَأَنِّي أَنْظُرُ إِلَيْهِ حِينَ يُجْلِسُ الرِّجَالَ بِيَدِهِ ثُمَّ أَقْبَلَ يَشُقُّهُمْ حَتَّى جَاءَ النِّسَاءَ وَمَعَهُ ‏ ‏بِلَالٌ ‏ ‏فَقَالَ ‏ { ‏يَا أَيُّهَا النَّبِيُّ إِذَا جَاءَكَ الْمُؤْمِنَاتُ يُبَايِعْنَكَ عَلَى أَنْ لَا يُشْرِكْنَ بِاللَّهِ شَيْئًا ‏} ‏فَتَلَا هَذِهِ الْآيَةَ حَتَّى فَرَغَ مِنْهَا ثُمَّ قَالَ حِينَ فَرَغَ مِنْهَا أَنْتُنَّ عَلَى ذَلِكَ فَقَالَتْ امْرَأَةٌ وَاحِدَةٌ لَمْ يُجِبْهُ غَيْرُهَا مِنْهُنَّ نَعَمْ يَا نَبِيَّ اللَّهِ ‏ ‏لَا يَدْرِي ‏ ‏حَسَنٌ ‏ ‏مَنْ هِيَ ‏ ‏قَالَ فَتَصَدَّقْنَ قَالَ فَبَسَطَ ‏ ‏بِلَالٌ ‏ ‏ثَوْبَهُ ثُمَّ قَالَ هَلُمَّ لَكُنَّ فِدَاكُنَّ أَبِي وَأُمِّي فَجَعَلْنَ يُلْقِينَ الْفَتَخَ وَالْخَوَاتِمَ فِي ثَوْبِ ‏ ‏بِلَالٍ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏الْخَوَاتِيمَ ‏","","",""],[2905,2905,"","আমরা একজন যাজকের ছেলের কথা বলেছিলাম যে ছেলেটির সাথে কি ঘটেছে, সে একটা সালাদ পাবে, তারপর সে চলে যাবে, তুমি আংটিটা ছুঁড়ে ফেলবে এবং তারপর পাবে তারপর আমি আবার ভেতরে যাই তারপর আমি এটা খরচ করার পর তার সাথে দেখা করি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏شَهِدْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى يَوْمَ الْعِيدِ ثُمَّ خَطَبَ فَظَنَّ أَنَّهُ لَمْ يُسْمِعْ النِّسَاءَ فَأَتَاهُنَّ فَوَعَظَهُنَّ وَقَالَ ‏ ‏تَصَدَّقْنَ فَجَعَلَتْ الْمَرْأَةُ ‏ ‏تُلْقِي الْخَاتَمَ ‏ ‏وَالْخُرْصَ وَالشَّيْءَ ثُمَّ أَمَرَ ‏ ‏بِلَالًا ‏ ‏فَجَمَعَهُ فِي ثَوْبٍ حَتَّى أَمْضَاهُ ‏","","",""],[2906,2906,"","আমরা তার বাবার কথা একবার আমাদের বলেছিলাম যে তার মন হারিয়ে গেছে. আর একবার সে তার বাড়ি ছিল তার অন্ধকার থেকে আসা অন্ধকার থেকে। আমি সেরা থেকে সেরা থেকে এসেছি ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏مَرَّةً ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَقُلْتُ لَمْ يَكُنْ يُجَاوِزُ بِهِ ‏ ‏طَاوُسًا ‏ ‏فَقَالَ بَلَى هُوَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏ثُمَّ سَمِعَهُ يَذْكُرُهُ بَعْدُ وَلَا يَذْكُرُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُهِلُّ أَهْلُ ‏ ‏الْمَدِينَةِ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏وَيُهِلُّ أَهْلُ ‏ ‏الشَّامِ ‏ ‏مِنْ ‏ ‏الْجُحْفَةِ ‏ ‏وَيُهِلُّ أَهْلُ ‏ ‏الْيَمَنِ ‏ ‏مِنْ ‏ ‏يَلَمْلَمَ ‏ ‏وَيُهِلُّ أَهْلُ ‏ ‏نَجْدٍ ‏ ‏مِنْ ‏ ‏قَرْنٍ ‏ ‏وَهُنَّ لَهُنَّ وَلِمَنْ أَتَى عَلَيْهِنَّ مِمَّنْ سِوَاهُمْ مِمَّنْ أَرَادَ الْحَجَّ وَالْعُمْرَةَ وَمَنْ كَانَ بَيْتُهُ مِنْ دُونِ الْمِيقَاتِ فَإِنَّهُ يُهِلُّ مِنْ بَيْتِهِ حَتَّى يَأْتِيَ عَلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏قَدْ أَحْرَمْتُ مِنْ ‏ ‏يَلَمْلَمَ ‏ ‏حِينَ جِئْتُ مِنْ عِنْدِ ‏ ‏عَبْدِ الرَّزَّاقِ ‏","","",""],[2907,2907,"","ঈশ্বর কীভাবে একটা সন্তানকে আমাদের সম্বন্ধে বলেছিলেন, সেই বিষয়ে আমরা আলোচনা করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ قَتْلِ أَرْبَعٍ مِنْ الدَّوَابِّ النَّمْلَةِ وَالنَّحْلَةِ وَالْهُدْهُدِ ‏ ‏وَالصُّرَدِ ‏","","",""],[2908,2908,"","আমরা বাবার সবচেয়ে ভালোটার কথা বলেছি, একটা ছেলে আমাদের বলেছেন আমি তার জন্য প্রার্থনা করছি আর তাকে দু'টি দুঃখ দিতে হবে। তার বল তাকে গেরিলা হিসেবে দেখতে হবে, আমি আমার শক্তি নিয়ে অসুস্থ, সে সকল ঘোড়ায় চড়ে তাকে খুজছে, সে তার জন্য প্রার্থনা করছে এবং সে তাকে খুঁজছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلِ بْنِ حُنَيْفٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِضَبَّيْنِ مَشْوِيَّيْنِ وَعِنْدَهُ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏فَأَهْوَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ لِيَأْكُلَ ‏ ‏فَقِيلَ لَهُ إِنَّهُ ضَبٌّ فَأَمْسَكَ يَدَهُ فَقَالَ لَهُ ‏ ‏خَالِدٌ ‏ ‏أَحَرَامٌ هُوَ يَا رَسُولَ اللَّهِ قَالَ لَا وَلَكِنَّهُ لَا يَكُونُ بِأَرْضِ قَوْمِي فَأَجِدُنِي أَعَافُهُ فَأَكَلَ ‏ ‏خَالِدٌ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْظُرُ إِلَيْهِ ‏","","",""],[2909,2909,"","আমরা একটা ছেলের কথা বলেছিলাম যে আমাদের ঈশ্বর সম্পর্কে বলেছে, তার মৃত্যুর জন্য তিনি আমাকে প্রশংসা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَجَعَلَ يُثْنِي عَلَيْهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ الْبَيَانِ سِحْرًا وَإِنَّ مِنْ الشِّعْرِ حُكْمًا ‏","","",""],[2910,2910,"","আমরা দলের মধ্যে থেকে ভালো কথা বলেছি একজন মানুষের ছেলে যে কিনা ঈশ্বর প্রদত্ত কথা বলেছে সে শনিবার আমার সমস্ত মুখ খুলে দেবে এবং আমার হৃদয় উড়ে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَكْلِ كُلِّ ذِي ‏ ‏نَابٍ مِنْ السِّبَاعِ وَعَنْ أَكْلِ كُلِّ ذِي مِخْلَبٍ مِنْ الطَّيْرِ ‏","","",""],[2911,2911,"","আমি পৃথিবীর সেরাদের ব্যাপারে কথা বলেছি, আমার একটা ছেলে আছে, আমি যা বলেছি, সেভাবেই এই বিষয়ে ভীত। ভগবানের কাছ থেকে সরিয়ে নেয়া হয়েছে। তারা বলে যে আমরা যা বলছি তা নিয়ে আমাদের নিতে হবে। আমরা বলেছি, তারা ঈশ্বরের কাছে প্রার্থনা করবে যেন তারা আমাদের কথা শোনে এবং আমরা তা শুনি। আমি তার ঈশ্বর থেকে দূরে থাকবো আর তার বিশ্বাস তাকে আর কোন ক্ষতি করবে না, সে কোন ঈশ্বরের কাছে যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَقُلْتُ يَا ‏ ‏أَبَا عَبَّاسٍ ‏ ‏كُنْتُ عِنْدَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقَرَأَ هَذِهِ الْآيَةَ فَبَكَى قَالَ أَيَّةُ آيَةٍ قُلْتُ ‏ { ‏إِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ ‏} ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏إِنَّ هَذِهِ الْآيَةَ حِينَ أُنْزِلَتْ غَمَّتْ ‏ ‏أَصْحَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَمًّا شَدِيدًا وَغَاظَتْهُمْ غَيْظًا شَدِيدًا ‏ ‏يَعْنِي وَقَالُوا يَا رَسُولَ اللَّهِ هَلَكْنَا إِنْ كُنَّا نُؤَاخَذُ بِمَا تَكَلَّمْنَا وَبِمَا نَعْمَلُ فَأَمَّا قُلُوبُنَا فَلَيْسَتْ بِأَيْدِينَا فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُولُوا سَمِعْنَا وَأَطَعْنَا قَالَ فَنَسَخَتْهَا هَذِهِ الْآيَةُ ‏ { ‏آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ ‏ ‏إِلَى ‏ ‏لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ‏} ‏فَتُجُوِّزَ لَهُمْ عَنْ حَدِيثِ النَّفْسِ وَأُخِذُوا بِالْأَعْمَالِ ‏","","",""],[2912,2912,"","আমরা আমাদের মধ্যে ভাল কথা বলেছি কত মানুষ এটা করেছে। সে বলেছে আমি তাকে কাছে নিয়ে যাবো, দুই বছর আগে তারা তোমাকে ধরে ফেলবে, অথবা তুমি যতটা ছিলে তার চেয়ে দ্বিগুণ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏وَالْأَسْوَدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏قُرَيْشًا ‏ ‏أَتَوْا ‏ ‏كَاهِنَةً ‏ ‏فَقَالُوا لَهَا أَخْبِرِينَا بِأَقْرَبِنَا شَبَهًا بِصَاحِبِ هَذَا الْمَقَامِ فَقَالَتْ إِنْ أَنْتُمْ جَرَرْتُمْ كِسَاءً عَلَى هَذِهِ السَّهْلَةِ ثُمَّ مَشَيْتُمْ عَلَيْهَا أَنْبَأْتُكُمْ فَجَرُّوا ثُمَّ مَشَى النَّاسُ عَلَيْهَا فَأَبْصَرَتْ أَثَرَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏هَذَا أَقْرَبُكُمْ شَبَهًا بِهِ فَمَكَثُوا بَعْدَ ذَلِكَ عِشْرِينَ سَنَةً ‏ ‏أَوْ قَرِيبًا مِنْ عِشْرِينَ سَنَةً ‏ ‏أَوْ مَا شَاءَ اللَّهُ ثُمَّ بُعِثَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2913,2913,"","আমরা একটা ছেলেকে জীবন দেওয়ার জন্য আমাদের সর্বোত্তমটা নিয়ে কথা বলতাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ مَرَّةً مَرَّةً ‏","","",""],[2914,2914,"","আমরা আমার বাবায়ের ছেলে হবার ব্যাপারে আমাদের সব থেকে ভালো কথা বলেছি। আর সে তার ছেলের কাছ থেকে শেখার জন্য শক্তি পেয়েছিলো। এটা ঈশ্বরের পুত্র নয়, এটা পাথর আর ঐ পাথর নয়। এটা ছিল আমার বাবার কথা। আমি জানি, আমি জানি যে, আমি আমার বাবা, আমি আমার বাবা, আমি যদি আমার ছেলের সাথে নেই। আমি আমার বাবা, আমি আমার বাবা, আমি আমার বাবা, আমি আর আমি জানি, আমি জানি, আমি জানি না যে, আমি আমার ছেলে, আমি তোমার সাথে নেই। আমি যদি আমার ছেলেও না করি, আমি আমার ছেলে। আমি আমার বাবা, আমি আমার বাবা, আমি আমার বাবা, আমি আমার বাবা। আমি আমার বাবা, আমি জানি যে, আমি আমার বাবা, আমি আমার বাবা, আমি আমার বাবা। আমি আমার বাবা। আমি আমার বাবা, আমি আমার বাবা। বন্য ছাড়া আমাকে মারতে চাইলেই হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَالثَّوْرِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَمُعَاوِيَةَ ‏ ‏فَكَانَ ‏ ‏مُعَاوِيَةُ ‏ ‏لَا يَمُرُّ بِرُكْنٍ إِلَّا اسْتَلَمَهُ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَكُنْ لِيَسْتَلِمَ إِلَّا الْحَجَرَ ‏ ‏وَالْيَمَانِيَ فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏لَيْسَ شَيْءٌ مِنْ الْبَيْتِ مَهْجُورًا ‏","","",""],[2915,2915,"","আমরা এই সময়ের সেরাটা নিয়ে কথা বলেছি, কয়েক মাস আগে আমরা বিদ্রোহীদের বলেছিলাম আর আমরা অন্ধ হয়ে যাব এই বাস্তবতা যে তারা পৃথিবীতে নেই. সে উঠে তার স্বপ্নের উপর দিয়ে গেল এবং সে অনেক খুশি হয়েছিল।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ خُثَيْمٍ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تَزَوَّجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏ ‏وَاحْتَجَمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[2916,2916,"","আমরা কথা বলেছিলাম যে, আমরা কত খুশি যে ছেলে ছিল যে ছেলে ছিল, আর সে ছিল একটা যুদ্ধলক আর আমি তাকে কেটে ফেলবো, না হয় ভগবানকে তার জ্যোতির জন্য প্রার্থনা করবো। তারা তাকে বন্ধ করে দিল। ড্রেস আর তারা ভাবতে পারেনি সে কে আর তারা এটা ভালো করে করে না। সে আমাকে বলেছে বিয়ের বড়ি হওয়ার পর, আমরা কাপুরুষের ছেলের ছেলে হয়ে ফিরে যাবো। ঈশ্বরের একজন রক্ষক ছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلًا خَرَّ عَنْ بَعِيرِهِ وَهُوَ مُحْرِمٌ فَوَقَصَهُ ‏ ‏أَوْ أَقْصَعَهُ شَكَّ ‏ ‏أَيُّوبُ ‏ ‏فَسَأَلُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏اغْسِلُوهُ بِمَاءٍ ‏ ‏وَسِدْرٍ ‏ ‏وَكَفِّنُوهُ فِي ثَوْبِهِ وَلَا تُخَمِّرُوا رَأْسَهُ وَلَا تُقَرِّبُوهُ طِيبًا فَإِنَّ اللَّهَ يَبْعَثُهُ يَوْمَ الْقِيَامَةِ مُحْرِمًا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ ‏ ‏مَعْمَرٌ ‏ ‏وَأَخْبَرَنِي ‏ ‏عَبْدُ الْكَرِيمِ الْجَزَرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلًا خَرَّ عَنْ بَعِيرٍ نَادٍّ وَهُوَ مُحْرِمٌ فَوُقِصَ وَقْصًا ثُمَّ ذَكَرَ مِثْلَ حَدِيثِ ‏ ‏أَيُّوبَ ‏","","",""],[2917,2917,"","আমরা ঈশ্বরের সেরাটার ব্যাপারে কথা বলেছি, একজন যাজকের ছেলে সম্পর্কে আমাদের বলেছিলাম। আমি ঈশ্বরের কাছে প্রার্থনা করতে চাই এবং তাঁকে তার নিজের মাংসের রক্ত ও রক্তের কাজে সাহায্য করতে চাই। আমি যা করেছি তার অর্ধেকই... ...সে বলেছে, সে একটা স্টান্ট।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏احْتَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْأَخْدَعَيْنِ وَبَيْنَ الْكَتِفَيْنِ حَجَمَهُ عَبْدٌ ‏ ‏لِبَنِي بَيَاضَةَ ‏ ‏وَكَانَ أَجْرُهُ مُدًّا وَنِصْفًا فَكَلَّمَ أَهْلَهُ حَتَّى وَضَعُوا عَنْهُ نِصْفَ مُدٍّ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَأَعْطَاهُ أَجْرَهُ وَلَوْ كَانَ حَرَامًا مَا أَعْطَاهُ ‏","","",""],[2918,2918,"","আমরা ভিড়ের কথা বলেছিলাম একজন যাজকের অন্ধকার ছেলেকে দেখে ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমার বাবার পাপের হাত থেকে বের হয়ে আসবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنِ ‏ ‏الْمُنْذِرِ بْنِ النُّعْمَانِ الْأَفْطَسِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏وَهْبًا ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ مِنْ ‏ ‏عَدَنِ أَبْيَنَ ‏ ‏اثْنَا عَشَرَ أَلْفًا يَنْصُرُونَ اللَّهَ وَرَسُولَهُ هُمْ خَيْرُ مَنْ بَيْنِي وَبَيْنَهُمْ ‏ ‏قَالَ ‏ ‏لِي ‏ ‏مَعْمَرٌ ‏ ‏اذْهَبْ فَاسْأَلْهُ عَنْ هَذَا الْحَدِيثِ ‏","","",""],[2919,2919,"","আমরা পৃথিবীর সেরাদের ব্যাপারে কথা বলেছি আমরা বলেছিলাম যে একটা ছোট ছেলে যে তোমাকে বলেছিল তোমার বাবা। হয়তো সে বলে যে আমরা এমন একটা ছেলে যে তার বোকাদের কাছে ফিরে যেতে চাই। গেম, সে বলেছিল, \"ঈশ্বর, আমার মা মারা যাচ্ছে এবং আমরা চলে যাচ্ছি\" আমি নিশ্চিত তুমি ডিজিনায়ার দেয়াল, তার বন্ধু এবং একটা কুত্তার বাচ্চা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَعْلَى ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عِكْرِمَةَ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏يَقُولُ أَنْبَأَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏سَعْدَ بْنَ عُبَادَةَ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏أَخَا ‏ ‏بَنِي سَاعِدَةَ ‏ ‏تُوُفِّيَتْ أُمُّهُ وَهُوَ غَائِبٌ عَنْهَا فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ ‏ ‏أُمِّي ‏ ‏تُوُفِّيَتْ وَأَنَا غَائِبٌ عَنْهَا فَهَلْ يَنْفَعُهَا إِنْ تَصَدَّقْتُ بِشَيْءٍ عَنْهَا قَالَ نَعَمْ قَالَ فَإِنِّي أُشْهِدُكَ أَنَّ حَائِطَ الْمَخْرَفِ ‏ ‏صَدَقَةٌ ‏ ‏عَلَيْهَا ‏ ‏وَقَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏الْمِخْرَافِ ‏","","",""],[2920,2920,"","আমি সমুদ্রের সেরাটার ব্যাপারে কথা বলেছি, আমার একটা ছেলে আছে যে ঈশ্বরকে বলে তা করতে বলা উচিত আর আমাকে আমার ভালবাসার স্বাধীনতা দিতে হবে। \"এই সূর্যটা ছিল মাছের টব, তারপর আমি প্রার্থনা করলাম।\" যখন সবকিছু আমার বংশধরের মতো ছিল এবং তারপর দিনের মাঝখানে আমাকে ধরা হল। দিনের বেলায় মসজিদের যুবকেরা আঘাত পায়, মনে হয় যেন যেন আমি সবকিছু পছন্দ করি, তারপর আমি এটার মাঝখানে আটকে পড়ি, আর তারপর এটা আমাকে কোন এক জায়গায় আটকে রাখে। প্রথম রাতটা হলো, আঘাত করতে বলা হলো, তারপর সে আমাকে ক্ষমা করে দিল, \"যাই হোক না কেন,\" এই বার আমার বাবা আমার সাথে কথা বলে, যখন আমরা কথা বলি, আমরা যুদ্ধ জিততে পারবো না। তিন রাত ধরে তিনি আমার কাছে প্রার্থনা করেছিলেন । আগে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏حَدَّثَنِي ‏ ‏حَكِيمُ بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّنِي ‏ ‏جِبْرِيلُ ‏ ‏عِنْدَ الْبَيْتِ فَصَلَّى بِي الظُّهْرَ حِينَ زَالَتْ الشَّمْسُ فَكَانَتْ بِقَدْرِ الشِّرَاكِ ثُمَّ صَلَّى بِي الْعَصْرَ حِينَ كَانَ ظِلُّ كُلِّ شَيْءٍ مِثْلَيْهِ ثُمَّ صَلَّى بِي الْمَغْرِبَ حِينَ أَفْطَرَ الصَّائِمُ ثُمَّ صَلَّى بِي الْعِشَاءَ حِينَ غَابَ ‏ ‏الشَّفَقُ ‏ ‏ثُمَّ صَلَّى بِي الْفَجْرَ حِينَ حَرُمَ الطَّعَامُ وَالشَّرَابُ عَلَى الصَّائِمِ ثُمَّ صَلَّى الْغَدَ الظُّهْرَ حِينَ كَانَ ظِلُّ كُلِّ شَيْءٍ مِثْلَهُ ثُمَّ صَلَّى بِي الْعَصْرَ حِينَ صَارَ ظِلُّ كُلِّ شَيْءٍ مِثْلَيْهِ ثُمَّ صَلَّى بِي الْمَغْرِبَ حِينَ أَفْطَرَ الصَّائِمُ ثُمَّ صَلَّى بِي الْعِشَاءَ إِلَى ثُلُثِ اللَّيْلِ الْأَوَّلِ ثُمَّ صَلَّى بِي الْفَجْرَ فَأَسْفَرَ ثُمَّ الْتَفَتَ إِلَيَّ فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏هَذَا وَقْتُ الْأَنْبِيَاءِ مِنْ قَبْلِكَ الْوَقْتُ فِيمَا بَيْنَ هَذَيْنِ الْوَقْتَيْنِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ عَيَّاشِ بْنِ أَبِي رَبِيعَةَ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حَكِيمِ بْنِ عَبَّادِ بْنِ حُنَيْفٍ ‏ ‏فَذَكَرَهُ بِإِسْنَادِهِ وَمَعْنَاهُ ‏ ‏إِلَّا أَنَّهُ قَالَ فِي الْفَجْرِ فِي الْيَوْمِ الثَّانِي لَا أَدْرِي أَيَّ شَيْءٍ قَالَ وَقَالَ فِي الْعِشَاءِ صَلَّى بِي حِينَ ذَهَبَ ثُلُثُ اللَّيْلِ الْأَوَّلِ ‏","","",""],[2921,2921,"","আমরা আমার বিশ্বাসের সবচেয়ে ভালো দিক নিয়ে কথা বলেছি, আর আমি খুশি হব একটা ছেলে সম্পর্কে, যে হয়তো ঈশ্বরের সর্বোচ্চ মঙ্গল কামনা করে আর আত্মসমর্পণ করে তার প্রতি দয়া দেখাতে হয়। বেনের জন্ম আমার বাবা বেন মানোস সম্বন্ধে যা বলেছিলেন, তা হল শুধু এটাই যে, বেনোসকে ঈর্ষা করেন । হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ عُمَرَ الصَّنْعَانِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏وَهْبُ بْنُ مَانُوسَ الْعَدَنِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ ثُمَّ يَقُولُ اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَاوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِبْرَاهِيمَ بْنِ عُمَرَ بْنِ كَيْسَانَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ مَانُوسَ ‏ ‏غَيْرَ هَذَا الْحَدِيثِ ‏","","",""],[2922,2922,"","আমরা সবার মধ্যে থেকে ভালো কথা বলেছি, এমন এক ছেলের কথা, যাকে চিকিৎসার জন্য ব্যবহার করা প্রয়োজন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏احْتَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَعْطَى ‏ ‏الْحَجَّامَ ‏ ‏أَجْرَهُ وَلَوْ كَانَ سُحْتًا لَمْ يُعْطِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2923,2923,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তিনি ডাক্তার ও ধনীদের কাছে আত্মসমর্পণ করেছিলেন । পৃথিবী এবং দুঃখ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي جَمْرَةَ الضُّبَعِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالْحَنْتَمِ ‏","","",""],[2924,2924,"","আমরা কিভাবে কথা বলেছিলাম যে আমরা সুন্দর সুন্দর কিছু করব, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তিনি বিদ্রোহীদের সাথে আমার প্রতারণা না করার জন্য আত্মসমর্পণ করেছেন না বা রাজকুমার নিরব।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ لِلْوَلِيِّ مَعَ الثَّيِّبِ أَمْرٌ وَالْيَتِيمَةُ تُسْتَأْمَرُ فَصَمْتُهَا إِقْرَارُهَا ‏","","",""],[2925,2925,"","আমরা বাবার জীবন নিয়ে কথা বলেছি, তার নিজের ভালবাসার জন্য অনেক বেশি। সূর্যের বাবা তাকে বলেন যে সে তালাক পেয়েছে তার ছেলে। প্রার্থনা করি যেন সে স্বপ্নের অর্থ উদ্ধার করে। সে স্বপ্ন দেখে, বা কে না, সেই একমাত্র ব্যক্তি যিনি আগে কখনো ছিলেন না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ مُعَتِّبٍ ‏ ‏عَنْ ‏ ‏مَوْلَى ‏ ‏بَنِي نَوْفَلٍ ‏ ‏يَعْنِي ‏ ‏أَبَا الْحَسَنِ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدٍ طَلَّقَ امْرَأَتَهُ بِطَلْقَتَيْنِ ثُمَّ عَتَقَا أَيَتَزَوَّجُهَا قَالَ نَعَمْ قِيلَ عَمَّنْ قَالَ أَفْتَى بِذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِيلَ ‏ ‏لِمَعْمَرٍ ‏ ‏يَا ‏ ‏أَبَا عُرْوَةَ ‏ ‏مَنْ ‏ ‏أَبُو حَسَنٍ ‏ ‏هَذَا لَقَدْ تَحَمَّلَ صَخْرَةً عَظِيمَةً ‏","","",""],[2926,2926,"","আমরা জনতার কথা বলছিলাম যে আমার বিয়ে বই দিয়ে ঈশ্বরের হাতে তুলে দেবে, হয়তো নবী তার কাছে প্রার্থনা করেছেন এবং গত দুই বছর তিনি আহত হয়েছেন। তার দুই বছর পর তার মোটা চুল নিয়ে হারিয়ে গেছে, সে আর দুঃখিত হবে না, সে একটা বাচ্চা হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏فَأَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ فِي رَمَضَانَ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏مَعَهُ عَشْرَةُ آلَافٍ مِنْ الْمُسْلِمِينَ وَذَلِكَ عَلَى رَأْسِ ثَمَانِ سِنِينَ وَنِصْفٍ مِنْ مَقْدَمِهِ ‏ ‏الْمَدِينَةَ ‏ ‏فَسَارَ بِمَنْ مَعَهُ مِنْ الْمُسْلِمِينَ إِلَى ‏ ‏مَكَّةَ ‏ ‏يَصُومُ وَيَصُومُونَ حَتَّى إِذَا بَلَغَ ‏ ‏الْكَدِيدَ ‏ ‏وَهُوَ مَا بَيْنَ ‏ ‏عُسْفَانَ ‏ ‏وَقُدَيْدٍ ‏ ‏أَفْطَرَ وَأَفْطَرَ الْمُسْلِمُونَ مَعَهُ فَلَمْ يَصُمْ ‏","","",""],[2927,2927,"","বাবা যা বলেছিল সব থেকে ভালো কথা হলো, একটা শিক্ষা হলো বাবা হচ্ছে সবচেয়ে বড় বন্ধু যে... ঈশ্বর তাকে আদেশ দিয়েছেন এবং আমি তাঁকে আদেশ দিয়েছি ও আদেশ দিয়েছি । ওকে মেনে নিতে আর বলতে চাই যে ওর লর্ডের কথা শোনা যাবে না। আমাদের পরবর্তী ছেলেকে খুন করার পর সে মারা যাবে। আমার ভাই তার চাচার জন্য চলে যাবে, কিন্তু আমি তাকে উদ্ধার করবো। একটা বিড়াল ছানা বলছে আমার বাবার ভেতরে থাকাটা আমার জীবনের সবচেয়ে বড় বন্ধু।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ الصِّدِّيقَ ‏ ‏دَخَلَ الْمَسْجِدَ ‏ ‏وَعُمَرُ ‏ ‏يُحَدِّثُ النَّاسَ فَمَضَى حَتَّى أَتَى الْبَيْتَ الَّذِي تُوُفِّيَ فِيهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي بَيْتِ ‏ ‏عَائِشَةَ ‏ ‏فَكَشَفَ عَنْ وَجْهِهِ بُرْدَ ‏ ‏حِبَرَةٍ ‏ ‏كَانَ مُسَجًّى بِهِ فَنَظَرَ إِلَى وَجْهِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ أَكَبَّ عَلَيْهِ يُقَبِّلُهُ ثُمَّ قَالَ وَاللَّهِ ‏ ‏لَا يَجْمَعُ اللَّهُ عَلَيْهِ مَوْتَتَيْنِ لَقَدْ مِتَّ الْمَوْتَةَ الَّتِي لَا تَمُوتُ بَعْدَهَا ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏دَخَلَ ‏ ‏أَبُو بَكْرٍ الصِّدِّيقُ ‏ ‏الْمَسْجِدَ ‏ ‏وَعُمَرُ ‏ ‏يُكَلِّمُ النَّاسَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[2928,2928,"","আমি আমার বাবা কথা বলেছিলাম. অ্যাসাঞ্জ বলেছিল তিনি ঈশ্বরের কাছে প্রার্থনা করবেন তিনি এটা ঠিক করার আদেশ দিয়েছেন যে কি করা উচিত. কিভাবে ঈশ্বরের দয়া ভালো এবং কি. তোমার ঈশ্বর ভুলে গেছে","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ ‏ ‏لَمْ يَكُنْ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ قَالَ ‏ ‏قَرَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا أُمِرَ أَنْ يَقْرَأَ فِيهِ وَسَكَتَ فِيمَا أُمِرَ أَنْ يَسْكُتَ فِيهِ ‏ { ‏قَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏} { ‏وَمَا كَانَ رَبُّكَ نَسِيًّا ‏}","","",""],[2929,2929,"","আমরা আমার বাবার সাথে কথা বলেছি যে একটা ছেলে কি জানে যে সে টাকা পেতে চায় না। সে হাল ছেড়ে দেবে কেন সে একটা সিদ্ধান্ত নিয়েছে। ঘরের ভিতরে গিয়ে তার দেবতাদের ফাঁস করে দেয়, আর হঠাৎ করে চলে যায়, আর তাদের হাতে স্বপ্ন দেখার জন্য আমি এখনো বলছি আল্লাহ এটা করেছেন. তারা জানত তাকে বলা হয়েছে. তারপর বাড়িতে গিয়ে দরজার দিকে গিয়ে বাইরে চলে গেলেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا قَدِمَ ‏ ‏مَكَّةَ ‏ ‏أَبَى أَنْ يَدْخُلَ ‏ ‏الْبَيْتَ ‏ ‏وَفِيهِ الْآلِهَةُ فَأَمَرَ بِهَا فَأُخْرِجَتْ فَأَخْرَجَ صُورَةَ ‏ ‏إِبْرَاهِيمَ ‏ ‏وَإِسْمَاعِيلَ ‏ ‏عَلَيْهِمَا السَّلَام ‏ ‏فِي أَيْدِيهِمَا ‏ ‏الْأَزْلَامُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاتَلَهُمْ اللَّهُ أَمَا وَاللَّهِ لَقَدْ عَلِمُوا مَا اقْتَسَمَا بِهَا قَطُّ قَالَ ثُمَّ دَخَلَ ‏ ‏الْبَيْتَ ‏ ‏فَكَبَّرَ فِي نَوَاحِي ‏ ‏الْبَيْتِ ‏ ‏وَخَرَجَ وَلَمْ يُصَلِّ فِي ‏ ‏الْبَيْتِ ‏","","",""],[2930,2930,"","আমরা একটা ছেলের কথা বলেছিলাম, তাকে একটা কারণের কথা, সে রাতের বেলা হলে তার পা দিয়ে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَهُ فِي الثَّقَلِ مِنْ ‏ ‏جَمْعٍ ‏ ‏بِلَيْلٍ ‏","","",""],[2931,2931,"","আমরা কথা বলেছি তিনি কত বার পালাতে চেষ্টা করছেন। তিনি বলেছেন, তাকে উদ্ধার করতে হবে এবং এই লজ্জার জন্য তাকে পুনরায় ক্ষমা করতে হবে। ভুল।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ كَرِهَ نَبِيذَ ‏ ‏الْبُسْرِ ‏ ‏وَحْدَهُ وَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَبْدَ الْقَيْسِ ‏ ‏عَنْ الْمُزَّاءِ فَأَكْرَهُ أَنْ يَكُونَ ‏ ‏الْبُسْرُ ‏ ‏وَحْدَهُ ‏","","",""],[2932,2932,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং আমি সূর্যের আনন্দের মধ্যে পড়ে যেতাম । তোমার রক্ত পড়ছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَزْرَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي صَلَاةِ الصُّبْحِ يَوْمَ الْجُمُعَةِ ‏ ‏تَنْزِيلُ السَّجْدَةَ ‏ ‏وَهَلْ أَتَى عَلَى الْإِنْسَانِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏بِ ‏ ‏الم تَنْزِيلُ ‏","","",""],[2933,2933,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং আগামীকাল মসজিদের আশীর্বাদগুলোর জন্য প্রার্থনা করেছেন । অপসারণ করা হয়েছে এবং অপসারণ করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏بُكَيْرُ بْنُ أَبِي السَّمِيطِ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرَأَ فِي صَلَاةِ الْغَدَاةِ يَوْمَ الْجُمُعَةِ ‏ ‏تَنْزِيلُ السَّجْدَةَ ‏ ‏وَهَلْ أَتَى عَلَى الْإِنْسَانِ ‏","","",""],[2934,2934,"","আমরা ঐ চাবি নিয়ে কথা বলেছি, হয়তো জাহাজের আগুন দিয়ে যেতে পারে। সে বলল, আমি ঈশ্বরের কাছে প্রার্থনা করেছি, আর সে বলবে আমার মায়ের ভিতর থেকে দুইটা বিছানা আছে। আমার বাবা মারা গেছে বলতে বাধ্য হয়ে বলেছে, কে ভাঙ্গা হৃদয় ভেঙ্গে গেছে, আমার মা আমাকে ধরতে পারেনি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ رَبِّهِ بْنُ بَارِقٍ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكٌ أَبُو زُمَيْلٍ الْحَنَفِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَ لَهُ ‏ ‏فَرَطَانِ ‏ ‏مِنْ أُمَّتِي دَخَلَ الْجَنَّةَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏بِأَبِي فَمَنْ ‏ ‏كَانَ لَهُ ‏ ‏فَرَطٌ ‏ ‏فَقَالَ وَمَنْ كَانَ لَهُ ‏ ‏فَرَطٌ ‏ ‏يَا مُوَفَّقَةُ قَالَتْ فَمَنْ لَمْ يَكُنْ لَهُ ‏ ‏فَرَطٌ ‏ ‏مِنْ أُمَّتِكَ قَالَ فَأَنَا ‏ ‏فَرَطُ ‏ ‏أُمَّتِي لَمْ يُصَابُوا بِمِثْلِي ‏","","",""],[2935,2935,"","আমরা যে বধিরদের কথা বলেছি, তাদের কথা আমরা তার নিরবতার কথা বলেছি। তিনি শুনেছেন আল্লাহ ঈশ্বরের সাথে শান্তি চুক্তি করতে ইচ্ছুক। কিন্তু আমরা একটি ছেলে সম্পর্কে কথা বলেছি যে বাবার ছেলের চেয়ে বেশি প্রলুব্ধ হয়েছে, যে ভবিষ্যৎবাণীতে ঈশ্বরের কাছে প্রার্থনা করেছে, সে এটা করেছে এবং তার আদর্শকে রক্ষা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَ ‏ ‏أَبُو سَلَّامٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ مِينَاءَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏وَعَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏أَنَّهُمَا ‏ ‏سَمِعَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى أَعْوَادِ مِنْبَرِهِ ‏ ‏لَيَنْتَهِيَنَّ أَقْوَامٌ عَنْ وَدْعِهِمْ الْجُمُعَاتِ أَوْ لَيَخْتِمَنَّ اللَّهُ عَلَى قُلُوبِهِمْ ثُمَّ لَيُكْتَبُنَّ مِنْ الْغَافِلِينَ ‏ ‏حَدَّثَنَا ‏ ‏هُدْبَةُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ الْعَطَّارُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَّامٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ مِينَاءَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏","","",""],[2936,2936,"","সে প্রভুর কাছে যে উত্তম প্রার্থনা করে এবং চলে যায়, সেই বিষয়ে প্রার্থনা করে । ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ فَرُّوخَ ‏ ‏حَدَّثَنِي ‏ ‏حَبِيبٌ يَعْنِي ابْنَ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَجُلًا ‏ ‏يُصَلِّي فِي ‏ ‏مَسْجِدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ ‏ ‏يُكَبِّرُ إِذَا سَجَدَ وَإِذَا رَفَعَ وَإِذَا خَفَضَ فَأَنْكَرْتُ ذَلِكَ فَذَكَرْتُهُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏فَقَالَ لَا أُمَّ لَكَ تِلْكَ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2937,2937,"","আমরা সেই বধিরদের কথা বলেছিলাম, আমরা যেখানে খুশি মনে ঈশ্বরের বিষ নিয়ে কথা বলেছি। সে তার জন্য প্রার্থনা করছিল এবং সে তার মৃত্যুর শপথে আত্মসমর্পণ করতো। কিন্তু এটা হতে পারে। আমরা যখন ছিলাম, আমরা ভেবেছিলাম, আমরা যখন ছিলাম তখন আমরা আমাদের মৃত্যকর্মের জন্য। আমরা যখন ছিলাম, তখন আমরা আমাদের জীবন------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- ঈশ্বরের শিক্ষা, তিনি তাদের বলেছিলেন, তিনি ঋণের মধ্যে হারিয়ে ফেলেন এবং শিক্ষা লাভ করতে শেখালেন কিভাবে করতে হয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِ ‏ ‏مَيْمُونَةَ ‏ ‏فَوَضَعْتُ لَهُ وَضُوءًا مِنْ اللَّيْلِ فَقَالَتْ لَهُ ‏ ‏مَيْمُونَةُ ‏ ‏وَضَعَ لَكَ هَذَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبَّاسٍ ‏ ‏فَقَالَ ‏ ‏اللَّهُمَّ فَقِّهُّ فِي الدِّينِ وَعَلِّمْهُ التَّأْوِيلَ ‏","","",""],[2938,2938,"","আমরা বধির ও আরও উত্তম ছেলে মোশির সঙ্গে কথা বলেছিলাম, যে আমার বাবার সঙ্গে একটা হাত ছিল । একজন যাজককে মৃত্যুর জন্য বলা হয়েছে, আমি তাকে এখানে বলতে চাই, একটা ভীতুর ডিমের ছেলে যে তাকে ঈশ্বরের কাছে প্রার্থনা করতে দেখেছে, তার দয়া অবিশ্বাস্য। আমি ঈশ্বরের কাছে কি করছি আর আমি জানি না কি করবো। তাই আমি ঈশ্বরের কাছে প্রার্থনা করতে চাই যাতে তিনি তা উদ্ধার করতে পারেন এবং যখন আপনি বলেছিলেন যে এটা থেকে এসেছে। ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং জগতের মৃত্যুর পর সফল হওয়ার জন্য আমাদের সর্বোত্তমটা গ্রহণ করেছেন । ঈশ্বর তাকে আদেশ দিয়েছেন যে, ঈশ্বর তাকে আদেশ দিয়েছেন এবং ঈশ্বর ঈশ্বর ও পবিত্র ঈশ্বরের মধ্যে যেকোনো নরকই হল আসল বিষয় । ফাদার, তিনি ঈশ্বরের কাছে প্রতিজ্ঞা করেছেন যে তিনি তা করবেন এবং তিনি পৃথিবীর কাছে আত্মসমর্পণ করবেন, তিনি তার জন্য করুণা বোধ করবেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلَيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا مَاتَ ‏ ‏عُثْمَانُ بْنُ مَظْعُونٍ ‏ ‏قَالَتْ امْرَأَتُهُ هَنِيئًا لَكَ يَا ‏ ‏ابْنَ مَظْعُونٍ ‏ ‏بِالْجَنَّةِ قَالَ فَنَظَرَ إِلَيْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَظْرَةَ غَضَبٍ فَقَالَ لَهَا مَا يُدْرِيكِ فَوَاللَّهِ إِنِّي لَرَسُولُ اللَّهِ وَمَا أَدْرِي مَا يُفْعَلُ بِي ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَلَا بِهِ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ فَارِسُكَ وَصَاحِبُكَ فَاشْتَدَّ ذَلِكَ عَلَى ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ قَالَ ذَلِكَ ‏ ‏لِعُثْمَانَ ‏ ‏وَكَانَ مِنْ خِيَارِهِمْ حَتَّى مَاتَتْ ‏ ‏رُقَيَّةُ ابْنَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ الْحَقِي بِسَلَفِنَا الْخَيْرِ ‏ ‏عُثْمَانَ بْنِ مَظْعُونٍ ‏ ‏قَالَ وَبَكَتْ النِّسَاءُ فَجَعَلَ ‏ ‏عُمَرُ ‏ ‏يَضْرِبُهُنَّ بِسَوْطِهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِعُمَرَ ‏ ‏دَعْهُنَّ يَبْكِينَ وَإِيَّاكُنَّ ‏ ‏وَنَعِيقَ ‏ ‏الشَّيْطَانِ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَهْمَا يَكُنْ مِنْ الْقَلْبِ وَالْعَيْنِ فَمِنْ اللَّهِ وَالرَّحْمَةِ وَمَهْمَا كَانَ مِنْ الْيَدِ وَاللِّسَانِ فَمِنْ الشَّيْطَانِ وَقَعَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى شَفِيرِ الْقَبْرِ ‏ ‏وَفَاطِمَةُ ‏ ‏إِلَى جَنْبِهِ تَبْكِي فَجَعَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَيْنَ ‏ ‏فَاطِمَةَ ‏ ‏بِثَوْبِهِ رَحْمَةً لَهَا ‏","","",""],[2939,2939,"","আমি মেঘের সাথে কাজ করছি, তাই আমি আমার যথাসাধ্য চেষ্টা করছি, ঈশ্বর তাকে জিজ্ঞেস করেছেন এবং আমি তা করবো না। সে লুকিয়ে থাকার জন্য এতই ভুল করেছে আর আমাকে পড়তে বলেছে, সে তার বই নিয়ে যুদ্ধ করেছে, তার হাতে টাকা দেয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عِيسَى أَبُو بِشْرٍ الرَّاسِبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي حَمْزَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏كُنْتُ غُلَامًا أَسْعَى مَعَ الْغِلْمَانِ فَالْتَفَتُّ فَإِذَا أَنَا بِنَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَلْفِي مُقْبِلًا فَقُلْتُ مَا جَاءَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا إِلَيَّ قَالَ فَسَعَيْتُ حَتَّى أَخْتَبِئَ وَرَاءَ بَابِ دَارٍ قَالَ فَلَمْ أَشْعُرْ حَتَّى تَنَاوَلَنِي فَأَخَذَ بِقَفَايَ فَحَطَأَنِي حَطْأَةً فَقَالَ ‏ ‏اذْهَبْ فَادْعُ لِي ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ وَكَانَ كَاتِبَهُ فَسَعَيْتُ فَأَتَيْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏فَقُلْتُ أَجِبْ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنَّهُ عَلَى حَاجَةٍ ‏","","",""],[2940,2940,"","আমরা সেই বধিরদের কথা বলেছিলাম, যাদের কথা আমরা আমার বাবার ছেলে মেন্টরের ছেলে আর আমি একদিনের জন্য ভালো আছি। তিনি প্রার্থনা করার পর এমন এক শক্তি হাতে নিয়ে এসেছিলেন, যা নারীদের লাইনে রাখার জন্য প্রয়োজন ছিল এবং এরপর তিনি যে - বিষয়গুলো নিয়ে এসেছিলেন সেগুলোর মধ্য দিয়ে গিয়েছিলেন । তারা বিশ্বাস করতে আসে","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ يَعْنِي ابْنَ أَبِي الْفُرَاتِ ‏ ‏وَأَبُو عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالنَّاسِ يَوْمَ فِطْرٍ رَكْعَتَيْنِ بِغَيْرِ أَذَانٍ ثُمَّ خَطَبَ بَعْدَ الصَّلَاةِ ثُمَّ أَخَذَ بِيَدِ ‏ ‏بِلَالٍ ‏ ‏فَانْطَلَقَ إِلَى النِّسَاءِ فَخَطَبَهُنَّ ثُمَّ أَمَرَ ‏ ‏بِلَالًا ‏ ‏بَعْدَ مَا قَفَّا مِنْ عِنْدِهِنَّ أَنْ يَأْتِيَهُنَّ فَيَأْمُرَهُنَّ أَنْ يَتَصَدَّقْنَ ‏","","",""],[2941,2941,"","আমরা রাজার কথা বলেছিলাম আমার বাবার ভালোর জন্য, সে একটা ছেলে যে বলেছে যে সে ঈশ্বরকে তার জন্য একটা অনুগ্রহ চায় আর তিনি আপনাকে একটা উপকার দেবেন। ঈশ্বরের কাছে আমি তার আগে কখনো হয়নি, যখন আমরা তোমার যাওয়ার পর ভিতরে প্রবেশ করার ভাল উপায় জানা। সে সাসবার এবং হুইসেলের সাথে বিবাহিত ছিল... আমি তোমাকে ভালো মানুষ বলতে পেরে খুশি হয়েছি, আমি যদি মানুষ হতাম কিন্তু আমি তাকে বলতে পারতাম যে তোমার কোন মেয়ে নেই, তার কথা এবং তাকে বলেছিলেন যে, যাদেরকে লোকেদের হত্যা করতে হয়েছে তাদেরকে তাকে ব্যবহার করতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏الْمُغِيرَةُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَاعَنَ ‏ ‏بَيْنَ ‏ ‏الْعَجْلَانِيِّ ‏ ‏وَامْرَأَتِهِ قَالَ وَكَانَتْ حُبْلَى فَقَالَ وَاللَّهِ مَا قَرَبْتُهَا مُنْذُ عَفَرْنَا ‏ ‏وَالْعَفْرُ أَنْ يُسْقَى النَّخْلُ بَعْدَ أَنْ يُتْرَكَ مِنْ ‏ ‏السَّقْيِ بَعْدَ ‏ ‏الْإِبَارِ ‏ ‏بِشَهْرَيْنِ ‏ ‏قَالَ وَكَانَ زَوْجُهَا ‏ ‏حَمْشَ ‏ ‏السَّاقَيْنِ وَالذِّرَاعَيْنِ ‏ ‏أَصْهَبَ ‏ ‏الشَّعَرَةِ وَكَانَ الَّذِي رُمِيَتْ بِهِ ‏ ‏ابْنَ السَّحْمَاءِ ‏ ‏قَالَ فَوَلَدَتْ غُلَامًا أَسْوَدَ أَجْلَى جَعْدًا ‏ ‏عَبْلَ ‏ ‏الذِّرَاعَيْنِ قَالَ فَقَالَ ‏ ‏ابْنُ شَدَّادِ بْنِ الْهَادِ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏أَهِيَ الْمَرْأَةُ الَّتِي قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كُنْتُ رَاجِمًا بِغَيْرِ بَيِّنَةٍ لَرَجَمْتُهَا قَالَ لَا تِلْكَ امْرَأَةٌ قَدْ أَعْلَنَتْ فِي الْإِسْلَامِ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏فَذَكَرَ مَعْنَاهُ وَقَالَ فِيهِ ‏ ‏عَبْلَ ‏ ‏الذِّرَاعَيْنِ ‏ ‏خَدْلَ ‏ ‏السَّاقَيْنِ ‏ ‏وَقَالَ ‏ ‏الْهَاشِمِيُّ ‏ ‏خَدْلٌ ‏ ‏وَقَالَ ‏ ‏بَعْدَ الْإِبَارِ ‏","","",""],[2942,2942,"","আমরা একটা ছেলের কথা বলেছিলাম, যে আমাদের সাথে কথা বলেছিল, কিন্তু আমি ফুল নিয়ে কথা বলেছি। আমি ভাববাদীকে তার কাছে প্রার্থনা করতে দেখলাম আর আমি একে অপরকে প্রার্থনা করতে দেখলাম আর তারপর প্রার্থনা করতেও পারিনি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَرٍو ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ عُضْوًا ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[2943,2943,"","আমরা একটি উদ্যোগী মনের সঙ্গে কথা করেছি যে আমরা সুখী হব এবং একটি পরমদেশ প্রতিশ্রুতি এবং একটি নির্দিষ্ট প্রকৃতির প্রতিশ্রুতি. ( আদিপুস্তক ১: ২৭) সমুদ্রের মৃত্যু ও সমুদ্রের মরণ দ্বারা উদ্ধার করা ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَيَعْلَى بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَزَوَّجَ ‏ ‏مَيْمُونَةَ بِنْتَ الْحَارِثِ ‏ ‏وَهُوَ مُحْرِمٌ ‏ ‏قَالَ ‏ ‏وَفِي حَدِيثِ ‏ ‏يَعْلَى بْنِ حَكِيمٍ ‏ ‏بَنَى بِهَا بِمَاءٍ يُقَالُ لَهُ ‏ ‏سَرِفُ ‏ ‏فَلَمَّا قَضَى نُسُكَهُ أَعْرَسَ بِهَا بِذَلِكَ الْمَاءِ ‏","","",""],[2944,2944,"","আমরা বাবার সবচেয়ে ছোট ভালোবাসার কথা বলেছি, তার ছেলের জন্য ভালো কাপুরুষ সাহায্যের জন্য। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং সবার মন ও মন ভুলের জন্য নিজেকে সমর্পণ করেছেন। আর পৃথিবীর ক্ষতি সম্পর্কে উদাসীন হতে পেরে সে লিখেছে যে একটা ইঁদুর ইউনিফর্ম পড়ানোর অনুমতি দেবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطٌ ‏ ‏حَدَّثَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْبُسْرِ ‏ ‏وَالتَّمْرِ أَنْ يُخْلَطَا جَمِيعًا وَعَنْ الزَّبِيبِ وَالتَّمْرِ أَنْ يُخْلَطَا جَمِيعًا قَالَ وَكَتَبَ إِلَى أَهْلِ ‏ ‏جُرَشٍ ‏ ‏أَنْ لَا يَخْلِطُوا الزَّبِيبَ وَالتَّمْرَ ‏","","",""],[2945,2945,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তার নিজের ঈশ্বরের সিংহাসনের সঙ্গে যিনি বেদীতে আছেন তার জন্য তিনি দায়ী হয়েছেন । আমি আপনাকে তার পরে কখনো হারাব না। আমার কাছে আছে ঈশ্বরের মৃত্যু। তিনি বলেন, প্রভুর প্রার্থনা তিনি রক্ষা করেছেন এবং তারা বলতে চাই যে ঈশ্বরের হাত একজন যাজকের সন্তান যিনি বলেন, ঈশ্বরের অনুগ্রহের উপর, ( ১ রাজা.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا حُضِرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفِي الْبَيْتِ رِجَالٌ وَفِيهِمْ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلُمَّ أَكْتُبْ لَكُمْ كِتَابًا لَنْ تَضِلُّوا بَعْدَهُ أَبَدًا فَقَالَ ‏ ‏عُمَرُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ غَلَبَ عَلَيْهِ الْوَجَعُ وَعِنْدَنَا الْقُرْآنُ حَسْبُنَا كِتَابُ اللَّهِ فَاخْتَلَفَ أَهْلُ الْبَيْتِ فَاخْتَصَمُوا فَمِنْهُمْ مَنْ يَقُولُ قَرِّبُوا يَكْتُبُ لَكُمْ كِتَابًا لَا تَضِلُّوا بَعْدَهُ وَفِيهِمْ مَنْ يَقُولُ مَا قَالَ ‏ ‏عُمَرُ ‏ ‏فَلَمَّا أَكْثَرُوا اللَّغْوَ ‏ ‏وَالِاخْتِلَافَ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُومُوا ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏وَكَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏الرَّزِيَّةَ ‏ ‏كُلَّ ‏ ‏الرَّزِيَّةِ ‏ ‏مَا حَالَ بَيْنَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ أَنْ يَكْتُبَ لَهُمْ ذَلِكَ الْكِتَابَ مِنْ اخْتِلَافِهِمْ ‏ ‏وَلَغَطِهِمْ ‏","","",""],[2946,2946,"","বেঁচে থাকার জন্য ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং আমি তাঁর জন্মের সময় পর্যন্ত কত সুখীই না হয়েছিলাম! ওর কল্পনার জন্য ঈশ্বরকে ধন্যবাদ, আমি দুঃখিত, আমি তার ডিজাইনের ব্যাপারে ঠিক আছি আর আমি তার ডিজাইনের অর্ডার দিচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏فَوَجَدَ ‏ ‏يَهُودَ ‏ ‏يَصُومُونَ ‏ ‏يَوْمَ عَاشُورَاءَ ‏ ‏فَقَالَ مَا هَذَا فَقَالُوا هَذَا يَوْمٌ عَظِيمٌ يَوْمَ نَجَّى اللَّهُ ‏ ‏مُوسَى ‏ ‏وَأَغْرَقَ آلَ ‏ ‏فِرْعَوْنَ ‏ ‏فَصَامَهُ ‏ ‏مُوسَى ‏ ‏شُكْرًا قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنِّي أَوْلَى ‏ ‏بِمُوسَى ‏ ‏وَأَحَقُّ بِصِيَامِهِ فَصَامَهُ وَأَمَر بِصِيَامِهِ ‏","","",""],[2947,2947,"","তিনি তার প্রতিটা রুমের প্রতিটা অংশ ডুবিয়েছিলেন এবং পরে তিনি বলেছিলেন যে, ভাববাদীর কাছে ছিল । সে তার জন্য এসেছিল আর সে এটা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ ‏ ‏تَوَضَّأَ فَغَسَلَ كُلَّ عُضْوٍ مِنْهُ غَسْلَةً وَاحِدَةً ثُمَّ ذَكَرَ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَهُ ‏","","",""],[2948,2948,"","আমি একটা কাপুরুষের ছেলেকে বলতে চাই যে আমার সাথে কথা হয়েছে। ছেলে, আর তিনিই সেই ব্যক্তি যিনি এই ব্যক্তি যিনি এই কে? যে ই না সেই লোক যে কিনা... ...যে কথা বলেছিল... ...সে হল... ...যে... ...আর ঐ ছেলে... সে মারা যেতে পারে, ভুলে যাবে আমরা তোমাকে রক্ষা করবো... ...যে আমাকে হত্যা করবে... ...সে বলবে মানুষ তাকে উদ্ধার করবে, আমি তার নাম বাদ দিয়ে তাকে ব্যাট থেকে তুলে নিচ্ছি আর আমি একটা ছেলে হয়ে যাবো আমি তাকে বলতে চাই, নবী আমাকে নেতৃত্ব দিয়েছেন। তাঁরা তার মাথা দেখতে অতি দ্রুত এবং বলে সে এখানে ঈশ্বরের সন্তান হতে পারে। আমি তাকে বলতে চাই, সে আমাদের এই কাজ করতে চায়। আমি চাই, আমি চাই, আমি যেন আমি তাকে বলি, আমি যেন আমার নেতা। আমি আমার সিদ্ধান্তের জন্য এই সিদ্ধান্ত নিয়েছি। এবং আমি আমার নিজের মাথাকে আমার জীবনের জন্য প্রস্তুত করি। আমি আমার নিজের সিদ্ধান্তের জন্য, আমি আমার কাছে এটা একটা বিষয় নিয়ে। এবং আমি যখন ফিরে যাই, তখন আমি আমার কাছে এটা একটা প্রশ্ন করি। আমি যখন আমি আমার মনে করি, তখন আমি মনে করি, আমি আমার মনে করি, আমি জানি যে, আমি আমার ছেলে আমাকে জিজ্ঞেস করি, আমি আমার ছেলে নেই। আমি কি তাকে জিজ্ঞেস করি, আমি আমার ছেলে-মেয়ে। আমি জানি যে, আমি আমার বাবা আমার ছেলে-মা'র কাছ থেকে দূরে সরে যেতে হবে। বাবা, আমাদের সাহায্য করো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حُسَيْنُ بْنُ عَبْدِ اللَّهِ بْنِ عُبَيْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏وَدَاوُدُ بْنُ عَلِيٍّ ‏ ‏أَنَّ رَجُلًا نَادَى ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏وَالنَّاسُ حَوْلَهُ فَقَالَ سُنَّةً تَبْتَغُونَ بِهَذَا ‏ ‏النَّبِيذِ ‏ ‏أَوْ هُوَ أَهْوَنُ عَلَيْكُمْ مِنْ الْعَسَلِ وَاللَّبَنِ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏جَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَبَّاسًا ‏ ‏فَقَالَ ‏ ‏اسْقُونَا فَقَالَ إِنَّ هَذَا ‏ ‏النَّبِيذَ ‏ ‏شَرَابٌ قَدْ ‏ ‏مُغِثَ ‏ ‏وَمُرِثَ ‏ ‏أَفَلَا ‏ ‏نَسْقِيكَ لَبَنًا وَعَسَلًا فَقَالَ اسْقُونِي مِمَّا تَسْقُونَ مِنْهُ النَّاسَ قَالَ فَأُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَهُ أَصْحَابُهُ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَالْأَنْصَارِ ‏ ‏بِعِسَاسٍ ‏ ‏فِيهَا النَّبِيذُ فَلَمَّا شَرِبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَجِلَ قَبْلَ أَنْ يَرْوَى فَرَفَعَ رَأْسَهُ فَقَالَ أَحْسَنْتُمْ هَكَذَا فَاصْنَعُوا قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَرِضَا رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَلِكَ أَعْجَبُ إِلَيَّ مِنْ أَنْ تَسِيلَ شِعَابُهَا عَلَيْنَا لَبَنًا وَعَسَلًا ‏","","",""],[2949,2949,"","আমরা একটা মহান মনের সাথে কথা বলেছি... ...যে কিনা আগে কখনো খুন হয়েছে তাকে বলে যে শয়তান আমাকে বলেছিল যে সে আমার সাথে কথা বলেছে একজন যাজকের ছেলে... তিনি তা - ই করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّ ‏ ‏أَبَا الشَّعْثَاءِ ‏ ‏أخْبَرَهُ قَالَ حَدَّثَنِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَخْطُبُ يَقُولُ ‏ ‏مَنْ لَمْ يَجِدْ إِزَارًا وَوَجَدَ سَرَاوِيلَ فَلْيَلْبَسْهَا وَمَنْ لَمْ يَجِدْ نَعْلَيْنِ وَوَجَدَ خُفَّيْنِ فَلْيَلْبَسْهُمَا ‏","","",""],[2950,2950,"","আমরা আমার ছেলের আশীর্বাদ নিয়ে কথা বলেছি, কাপুরুষের বাচ্চা একটা কাপুরুষের বাচ্চা, যে কিনা কাপুরুষের বাচ্চা। গুজব তাকে বলে যে একজন যাজকের ছেলে তাকে বলেছিল যে, ভাববাদীর অধিকার আছে উদ্ধার ছিল একজন স্বপ্নবী।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَحَجَّاجٌ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّ ‏ ‏أَبَا الشَّعْثَاءِ ‏ ‏أخْبَرَهُ أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَكَحَ ‏ ‏مَيْمُونَةَ ‏ ‏وَهُوَ حَرَامٌ ‏","","",""],[2951,2951,"","আমরা কথা বলেছি কত মানুষ আমাদের বলেছে যে আমাদের কল করা হয়েছে বা না বলা হয়েছে। একটা শিক্ষা হচ্ছে, সে বলেছে মাখনের চামড়া দিয়ে মাখনের চামড়া দিয়ে আঘাত করেছে। আমি বলব, সে নাকি তার ছেলেকে মেরে ফেলবে। বল আমি একজন স্মার্ট মহিলা আর আমি আমার ভেতর দিয়ে যেতে চাই, সে বলল আমি পালিয়ে যাবো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏طَاوُسًا ‏ ‏وَعِكْرِمَةَ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏يُخْبِرَانِ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏جَاءَتْ ‏ ‏ضُبَاعَةُ بِنْتُ الزُّبَيْرِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏إِنِّي امْرَأَةٌ ثَقِيلَةٌ وَإِنِّي أُرِيدُ الْحَجَّ فَكَيْفَ تَأْمُرُنِي كَيْفَ أُهِلُّ قَالَ أَهِلِّي وَاشْتَرِطِي أَنَّ مَحِلِّي حَيْثُ حَبَسْتَنِي قَالَ فَأَدْرَكَتْ ‏","","",""],[2952,2952,"","আমরা আবেগ নিয়ে কথা বলেছি এবং একটা ছেলের সাথে আমাদের একটা উপদেবতার কথা বলেছি। তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন তার জন্য এবং গরু ও দেয়াল উদ্ধার করেছেন। আমি ঘৃণা করি যে আমি দেখতে চাই। তার হুমকির কারণ","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُحَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَائِرَاتِ الْقُبُورِ وَالْمُتَّخِذِينَ عَلَيْهَا الْمَسَاجِدَ ‏ ‏وَالسُّرُجَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أُرَهُ ‏ ‏يَعْنِي ‏ ‏الْيَهُودَ ‏","","",""],[2953,2953,"","আমরা আমাদের আবেগ সৃষ্টি করেছি একটি প্রথা তৈরি করেছি যা আমাকে কুসুমতার রীতিতে পরিচালিত করেছে। আমি জিজ্ঞেস করবো, যদি আমি না আসি তাহলে আমি কিভাবে প্রার্থনা করব। মাস্টারদের সঙ্গে ও তিনি আত্মসমর্পণ করেছেন","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ سَلَمَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏كَيْفَ أُصَلِّي إِذَا كُنْتُ ‏ ‏بِمَكَّةَ ‏ ‏إِذَا لَمْ أُصَلِّ مَعَ الْإِمَامِ فَقَالَ ‏ ‏رَكْعَتَيْنِ سُنَّةَ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2954,2954,"","আমরা একটা ছেলের কথা বলেছিলাম যে তোমাকে ভালোবাসার কথা বলেছিলাম সে তার নিজের কসমটা দিয়ে দেবে, প্রভু, আমি তাকে বলেছি, ঈশ্বর শান্তি প্রতিষ্ঠা করেছেন। অথবা তিনি বলেছিলেন, ঈশ্বর তাকে বললেন, ঈশ্বর শান্তি স্থাপন করেছেন। পানি বেঁচে যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَجْنَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَيْمُونَةُ ‏ ‏فَاغْتَسَلَتْ ‏ ‏مَيْمُونَةُ ‏ ‏فِي جَفْنَةٍ وَفَضَلَتْ فَضْلَةٌ فَأَرَادَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَغْتَسِلَ مِنْهَا فَقَالَتْ يَا رَسُولَ اللَّهِ إِنِّي قَدْ اغْتَسَلْتُ مِنْهُ فَقَالَ ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمَاءَ لَيْسَتْ عَلَيْهِ جَنَابَةٌ ‏ ‏أَوْ قَالَ إِنَّ الْمَاءَ لَا يَنْجُسُ ‏","","",""],[2955,2955,"","আমরা তর্ক করেছি কিভাবে একটি ছেলের মৃত্যুর সময় বেঁচে থাকতে হয়, ঈশ্বর তাকে বলেছেন মাখনের সৌভাগ্য হচ্ছে গরুের পুত্র যাজক বলবে সে তার বাবার কসম শেষ করে তার ছেলেকে অন্ধ করে দেবে। আমি বলবো, নবী ঈশ্বরের কাছে প্রার্থনা করেছেন এবং বলবেন আমার বাবার দিন ও এর শেষ বয়স।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏الْفُضَيْلِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏أُرَاهُ عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تَمَتَّعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏نَهَى ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏عَنْ الْمُتْعَةِ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏مَا يَقُولُ ‏ ‏عُرَيَّةُ ‏ ‏قَالَ يَقُولُ نَهَى ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏عَنْ الْمُتْعَةِ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أُرَاهُمْ سَيَهْلِكُونَ أَقُولُ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيَقُولُ نَهَى ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏","","",""],[2956,2956,"","আমি আমার বাবার বিরুদ্ধে তর্ক করেছি যে একজন যাজককে ঈশ্বরের অনুগ্রহের উপর তদন্ত করতে হবে. ওর সাথে অথবা আমাকে নিয়ে যাও।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنِ ‏ ‏التَّمِيمِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ ‏ ‏أُمِرْتُ بِالسِّوَاكِ حَتَّى ظَنَنْتُ أَنَّهُ سَيَنْزِلُ بِهِ عَلَيَّ قُرْآنٌ أَوْ وَحْيٌ ‏","","",""],[2957,2957,"","আমরা তর্কের কথা বলেছি আমরা ঈশ্বরের ভালোবাসার একটি মেয়েকে খুঁজে বের করার চেষ্টা করেছি। হয়তো সে বলেছিল, সে ঈশ্বরের অনুগ্রহ কামনা করবে, তাকে তার কাছে হস্তান্তর করা হবে এবং তারপর সে পানি এবং তারপর তাকে ডাকা হবে সে বলতে চেয়েছিল, \"সে মারা গেছে.\"","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنَا ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏شَرِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَنًا ثُمَّ دَعَا بِمَاءٍ فَمَضْمَضَ ثُمَّ قَالَ إِنَّ لَهُ دَسَمًا ‏","","",""],[2958,2958,"","আমরা একটা মুরগির কথা বলেছি যে আমাকে বলেছিল সে একটা ছেলেকে সাহায্য করবে, সে একটা ছেলেকে খুজে বের করে দিল, যেটা হল সেইগুলো ছিল ঈশ্বর আর প্রভু, আমি আমার পালনকর আমার পালনকরের উপর নির্ভর করি না। ঈশ্বরের কাছে তার শান্তি এবং গোপনে আত্মসমর্পন করা.","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَعْلَى بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏نَزَلَتْ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ ‏ ‏وَأُولِي ‏ ‏الْأَمْرِ مِنْكُمْ ‏} ‏فِي ‏ ‏عَبْدِ اللَّهِ بْنِ حُذَافَةَ بْنِ قَيْسِ بْنِ عَدِيٍّ السَّهْمِيِّ ‏ ‏إِذْ بَعَثَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏السَّرِيَّةِ ‏","","",""],[2959,2959,"","আমরা এক ভয়ের কথা বলেছি যে আমাদের বাবা একজন যাজকের জন্য খুশি... ...একজন ভালো ছেলের জন্য, যে তোমার অনুগ্রহে একত্রিত হয়েছে, তার কাছে প্রার্থনা করেছে, আর আমরা তাকে চুমু দিব ভাববাদী তার কাছে এসেছিলেন এবং আমরা তার কাজের শাস্ত্রপদটি উদ্ধার করব ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جَمَعْتُ ‏ ‏الْمُحْكَمَ ‏ ‏فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقُبِضَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ابْنُ عَشْرِ حِجَجٍ قَالَ فَقُلْتُ لَهُ وَمَا ‏ ‏الْمُحْكَمُ ‏ ‏قَالَ ‏ ‏الْمُفَصَّلُ ‏","","",""],[2960,2960,"","একজন যাজকের ছেলে একটা জুয়াখেলার জন্য খরচ করেছে, যে ঈশ্বরের জন্য নিজের জীবন দিয়েছে এবং তার সঙ্গে রয়েছে । তার জীবনও দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏أَنَّ جَنَازَةً مَرَّتْ ‏ ‏بِالْحَسَنِ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏فَقَامَ ‏ ‏الْحَسَنُ ‏ ‏وَلَمْ يَقُمْ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَقَالَ ‏ ‏الْحَسَنُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏أَقَامَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ قَامَ وَقَعَدَ ‏","","",""],[2961,2961,"","আমরা বাবার সাথে কথা বলেছিলাম, একটা খেলা বানানোর কথা যা ভুল হচ্ছে। আমাকে বলতে হবে তাদের মধ্যে কেউ কেউ আমাদের সাথে থাকবে আর আমাদের সাথে থাকবে আমি যাদের সাথে ছিলাম, তারা বলেছিল তারা যমজ ছিল এবং আমাকে এই গল্পের জন্য অনুমতি দিয়েছিল। ঈশ্বর তাকে ক্ষমা করে দিলে তিনি মারা যাবেন। এটা এমন নয় যে, তার ভবিষ্যদ্বাণী আর তার নিজের কামনার সাথে সালাদ দিয়ে মানুষ তোমাদের প্রভু হিসেবে ঈশ্বরের ঋণে প্রবেশ করতে দেখেছে। সে বলল, আমাকে দোষ দিতে হবে। তুমি দেখতে পাচ্ছ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏يَأْذَنُ لِأَهْلِ ‏ ‏بَدْرٍ ‏ ‏وَيَأْذَنُ لِي مَعَهُمْ فَقَالَ بَعْضُهُمْ يَأْذَنُ لِهَذَا الْفَتَى مَعَنَا وَمِنْ أَبْنَائِنَا مَنْ هُوَ مِثْلُهُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏إِنَّهُ ‏ ‏مَنْ ‏ ‏قَدْ عَلِمْتُمْ قَالَ فَأَذِنَ لَهُمْ ذَاتَ يَوْمٍ وَأَذِنَ لِي مَعَهُمْ فَسَأَلَهُمْ عَنْ هَذِهِ السُّورَةِ ‏ ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ‏ ‏فَقَالُوا أَمَرَ نَبِيَّهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا فُتِحَ عَلَيْهِ أَنْ يَسْتَغْفِرَهُ وَيَتُوبَ إِلَيْهِ فَقَالَ لِي مَا تَقُولُ يَا ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ قُلْتُ لَيْسَتْ كَذَلِكَ وَلَكِنَّهُ أَخْبَرَ نَبِيَّهُ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏بِحُضُورِ أَجَلِهِ فَقَالَ ‏ { ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ‏} ‏فَتْحُ ‏ ‏مَكَّةَ ‏ { ‏وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا ‏} ‏فَذَلِكَ عَلَامَةُ مَوْتِكَ ‏ { ‏فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا ‏} ‏فَقَالَ لَهُمْ كَيْفَ تَلُومُونِي عَلَى مَا تَرَوْنَ ‏","","",""],[2962,2962,"","আমরা একটা সাধারণ উদ্বেগের কথা বলেছি যে আমাদের বাবার চেয়ে বেশি হওয়া উচিত একজন যাজকের ছেলে একজন সাক্ষী যিনি বলেছেন যে তিনি একটা ছেলে। সে গ্রীষ্মের বাজি আর দুনিয়ার ছেলে নিয়ে এসেছে তার স্বপ্নের ছোট অংশ। আমি আদেশ দিয়েছি যে কেউ যেন প্রথম লাইনে যেতে না পারে আর তা করতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَهَلَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحَجِّ فَلَمَّا قَدِمَ طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَلَمْ يُقَصِّرْ وَلَمْ يَحِلَّ مِنْ أَجْلِ ‏ ‏الْهَدْيِ ‏ ‏وَأَمَرَ مَنْ لَمْ يَكُنْ سَاقَ ‏ ‏الْهَدْيَ ‏ ‏أَنْ يَطُوفَ وَأَنْ ‏ ‏يَسْعَى وَأَنْ يُقَصِّرَ أَوْ يَحْلِقَ ثُمَّ يَحِلَّ ‏","","",""],[2963,2963,"","ঈশ্বর তাদের জিজ্ঞেস করবেন যে, আমি কোন লোকেদের জিজ্ঞেস করব যে, প্রান্তরে ভূত্বক্‌ত্বক্‌ কোন দল রয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏إِسْمَاعِيلُ بْنُ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ ‏ ‏أَيُّ الشَّرَابِ أَطْيَبُ قَالَ الْحُلْوُ الْبَارِدُ ‏","","",""],[2964,2964,"","আমরা আবেগ দিয়ে বাপ্তাইজিত হয়েছি এবং আমাদের বলতে চাই যে আমার ভাইয়ের জীবন কিভাবে লুকিয়ে রাখা যায়। সে বলছে, ঈশ্বরের কাছে প্রার্থনা করছে এবং সে প্রার্থনা করবে। তিনশ সন্তানের জন্য,","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي جَمْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً ‏","","",""],[2965,2965,"","আমরা একটি ছেলে কথা বলেছি যে \"আমার পিতা\" বলতে গিয়ে যে ... ...ঈশ্বর তাকে উদ্ধার করেছেন এবং আমরা পাপের পাপ নিয়ে খেলা করছি আলমারীর নাম দিলে আমি তার কাছে ফিরে যাই, আমি বলি এটা খেতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي جَمْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏مَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أَلْعَبُ مَعَ الْغِلْمَانِ فَاخْتَبَأْتُ مِنْهُ خَلْفَ بَابٍ فَدَعَانِي ‏ ‏فَحَطَأَنِي ‏ ‏حَطْأَةً ‏ ‏ثُمَّ ‏ ‏بَعَثَنِي إِلَى ‏ ‏مُعَاوِيَةَ ‏ ‏فَرَجَعْتُ إِلَيْهِ فَقُلْتُ هُوَ يَأْكُلُ ‏","","",""],[2966,2966,"","আমরা আবেগ আর আবেগ নিয়ে কথা বলেছি যেটা আমরা কখনো দেখিনি, আমি একটা কাপুরুষের ছেলের কথা শুনে খুশি হয়েছি যে যে বলে আমি হুমকি দিচ্ছি ঈশ্বর সমুদ্রের এক সমতল সমতল সমতল সমতল ওপর নিয়ে এসেছিলেন এবং একজন যুদ্ধবীর যিনি বলেছিলেন যে এটা পাথর বা পাথর ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏أَهْدَى ‏ ‏الصَّعْبُ ‏ ‏وَقَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏ابْنُ جَثَّامَةَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شِقَّةَ حِمَارٍ وَهُوَ مُحْرِمٌ فَرَدَّهُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏عَجُزَ حِمَارٍ ‏ ‏أَوْ قَالَ رِجْلَ حِمَارٍ ‏","","",""],[2967,2967,"","আমরা আবেগ-অনুভূতি করার চেষ্টা করেছি কিছু শোনার মাধ্যমে সাহায্য করার চেষ্টা করেছি। একজন যাজকের ছেলে যিনি তার নিজের রক্ত নিয়ে মজা করেছেন। কে বলেছে তারা ভেঙ্গে পড়েছে। ( পড়ুন, গীতসংহিতা ৩৪: ৮.)","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْمِنْهَالِ بْنِ عَمْرٍو ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏مَرَرْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏فِي طَرِيقٍ مِنْ طُرُقِ ‏ ‏الْمَدِينَةِ ‏ ‏فَإِذَا فِتْيَةٌ قَدْ نَصَبُوا دَجَاجَةً يَرْمُونَهَا لَهُمْ كُلُّ خَاطِئَةٍ قَالَ فَغَضِبَ وَقَالَ مَنْ فَعَلَ هَذَا قَالَ فَتَفَرَّقُوا فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏يُمَثِّلُ ‏ ‏بِالْحَيَوَانِ ‏","","",""],[2968,2968,"","আমরা এক ধরনের আবেগ কথা বলেছি যা আমরা শুনেছি শয়তান এর কথা শুনেছি, সে ঈশ্বরের অনুগ্রহের মাধ্যমে চলে গেছে, সে এটা করেছে এবং তাদের প্রতিজ্ঞার উপর ছেড়ে দিয়েছে ( ১ রাজাবলি ১১: ১ - ৩) মা ও তার উত্তরাধিকারী সম্বন্ধে বর্ণনা করেছিল ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ الشَّيْبَانِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏قَالَ ‏ ‏أَخْبَرَنِي مَنْ ‏ ‏مَرَّ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى قَبْرٍ ‏ ‏مَنْبُوذٍ ‏ ‏فَأَمَّهُمْ وَصَفُّوا خَلْفَهُ فَقُلْتُ يَا ‏ ‏أَبَا عَمْرٍو ‏ ‏مَنْ حَدَّثَكَ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏","","",""],[2969,2969,"","আমরা কামনার প্রতি আসক্তি নিয়ে কথা বলেছি... ...যে তোমার চাকরের রীতি তৈরি করেছে... ...যে কিনা কখনো বাচ্চা নিয়ে যুদ্ধ করতে পারে নি, ঈশ্বরের উত্তর হল সে তার হাতে সমর্পণ করেছে যে তার ভাইয়ের জন্য ভাল কিছু দিতে হবে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَتْ لَهُ أَرْضٌ أَنْ يَمْنَحَهَا أَخَاهُ خَيْرٌ لَهُ ‏","","",""],[2970,2970,"","আমরা আবেগ নিয়ে কথা বলেছি যে আমরা একটা ছেলের জন্য লড়াই করেছি যেটা রক্ষা পেয়েছিল। আল্লাহ তার যাওয়ার জন্য প্রার্থনা করেছেন। যদি আমি কষ্ট পাই তাহলে তার সত্যিকারের স্বাদ মারা যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ كَانَ عِنْدَ الْحَجَرِ وَعِنْدَهُ مِحْجَنٌ يَضْرِبُ بِهِ الْحَجَرَ وَيُقَبِّلُهُ فَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ ‏} ‏لَوْ أَنَّ قَطْرَةً قُطِرَتْ مِنْ ‏ ‏الزَّقُّومِ ‏ ‏فِي الْأَرْضِ لَأَمَرَّتْ عَلَى أَهْلِ الدُّنْيَا مَعِيشَتَهُمْ فَكَيْفَ بِمَنْ هُوَ طَعَامُهُ وَلَيْسَ لَهُ طَعَامٌ غَيْرُهُ ‏","","",""],[2971,2971,"","আমরা আমাদের সুস্থ করার চেষ্টা করেছি, আমরা ভালো সংবাদ নিয়ে এসেছি। এক ছেলে বলে যে এক মাস আটকে থাকার ভয় পেয়েছে, ভয় পেয়ে সে মারা গেছে। আমি বলতে চাচ্ছি যে, আমার বাবার জীবন নিয়ে বেঁচে থাকা একজন সাক্ষির জন্য যে - ব্যক্তির কাছে আমি গিয়েছিলাম, তিনি বলেছিলেন যে, আমাকে যদি বাইরে যেতে হয়, তা হলে আমাকে অবশ্যই যেতে হবে নীল","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏رَكِبَتْ امْرَأَةٌ الْبَحْرَ فَنَذَرَتْ أَنْ تَصُومَ شَهْرًا فَمَاتَتْ قَبْلَ أَنْ تَصُومَ فَأَتَتْ أُخْتُهَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَتْ ذَلِكَ لَهُ ‏ ‏فَأَمَرَهَا أَنْ تَصُومَ عَنْهَا ‏ ‏حَدَّثَنَا ‏ ‏الْقَوَارِيرِىُّ ‏ ‏حَدَّثَنَا ‏ ‏فُضَيْلُ بْنُ عِيَاضٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ يَعْنِي الْأَعْمَشَ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَوْ أَنَّ قَطْرَةً مِنْ ‏ ‏الزَّقُّومِ ‏ ‏فَذَكَرَهُ ‏","","",""],[2972,2972,"","আমরা আমাদের ভালোবাসা যুদ্ধের জন্য অনুপ্রেরনা দিয়ে বাপ্তাইজিত হয়েছি। লর্ড তার জন্য প্রার্থনা করেছেন এবং আশ্বস্ত করেছেন যে তিনি এই দিনে তার জন্য যা করেছেন, তার জন্য তিনি আমার কাছে সবচেয়ে সেরা কাজ করেছেন। প্রভুর পথে চেষ্টা করে বলা হয়েছে যে দলটি ঈশ্বরের পথে যাবে না, যদি না সে তার আত্মা নিয়ে পালিয়ে যেতে পারে... ...আর সে কখনই তা করতে পারত না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا عَمَلٌ أَفْضَلَ مِنْهُ فِي هَذِهِ الْأَيَّامِ ‏ ‏يَعْنِي أَيَّامَ الْعَشْرِ قَالَ فَقِيلَ وَلَا الْجِهَادُ فِي سَبِيلِ اللَّهِ قَالَ وَلَا الْجِهَادُ ‏ ‏فِي سَبِيلِ اللَّهِ إِلَّا مَنْ خَرَجَ بِنَفْسِهِ وَمَالِهِ ثُمَّ لَمْ يَرْجِعْ بِشَيْءٍ مِنْ ذَلِكَ ‏","","",""],[2973,2973,"","আমরা আবেগ নিয়ে কথা বলেছি যা আমাদেরকে ফ্রেঞ্চদের ইতিহাস নিয়ে এসেছে। আমি বিকেলের পর দু'বার অসুস্থ হয়ে পড়েছি, আর এটা অনেক বড় হয়ে গেছে। তোমার একটা বছর চলে গেছে। ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏صَلَّيْتُ خَلْفَ شَيْخٍ أَحْمَقَ صَلَاةَ الظُّهْرِ فَكَبَّرَ فِيهَا ثِنْتَيْنِ وَعِشْرِينَ تَكْبِيرَةً يُكَبِّرُ إِذَا سَجَدَ وَإِذَا رَفَعَ رَأْسَهُ مِنْ السُّجُودِ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏لَا أُمَّ لَكَ تِلْكَ سُنَّةُ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2974,2974,"","আমরা একটি আবেগ দ্বারা বাপ্তাইজিত হয়েছি, যা আমার বাবাকে অভিশাপ দিয়ে আমাদের কাছে হয়েছে। দাস, পাখিটা ছিল আমার সব দরজার নাম ছিল সপ্তমের দরজা থেকে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْحَكَمِ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ مِهْرَانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏عَنْ كُلِّ ذِي مِخْلَبٍ مِنْ الطَّيْرِ وَعَنْ كُلِّ ذِي ‏ ‏نَابٍ مِنْ السِّبَاعِ ‏","","",""],[2975,2975,"","আমরা আবেগ এবং বধির পিতাদের কথা বলেছি, তারা এক বিজ্ঞ মানুষের সুখী প্রতিশ্রুতির কথা বলেছে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং গণ ও পর্দার উদ্দেশ্যর কাছে আত্মসমর্পণ করেছেন। আর জেলে পাওয়া যাবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَأَبُو عَبْدِ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُجَثَّمَةِ ‏ ‏وَالْجَلَّالَةِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْدِ الصَّمَدِ ‏ ‏نَهَى عَنْ لَبَنِ ‏ ‏الْجَلَّالَةِ ‏ ‏وَأَنْ يَشْرَبَ مِنْ ‏ ‏فِي ‏ ‏السِّقَاءِ ‏","","",""],[2976,2976,"","আমরা একটা কুকুরের ছেলের কথা বলেছিলাম, যে হয়ত এটা করেছে, সে মানুষের ছেলেদের শেষ করে দেবে আর সূর্যের অভিশাপ বহন করবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ لَبَنِ ‏ ‏الْجَلَّالَةِ ‏ ‏وَعَنْ ‏ ‏الْمُجَثَّمَةِ ‏ ‏وَعَنْ الشُّرْبِ مِنْ ‏ ‏فِي ‏ ‏السِّقَاءِ ‏","","",""],[2977,2977,"","আমরা আবেগ-অনুভূতি এবং মহান মনের ছেলের কথা বলেছি যা আমরা একজন যুবকের অভিজ্ঞতার প্রতিশ্রুতি দিয়েছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমি তার ইচ্ছা পালন করব। তার সাথে বিয়ে করার জন্য শ্রেষ্ঠ মেয়ের কন্যা, কারণ থেকে তাকে পর্ণো থেকে নিষিদ্ধ করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُرِيدَ عَلَى ‏ ‏ابْنَةِ حَمْزَةَ ‏ ‏أَنْ يَتَزَوَّجَهَا فَقَالَ ‏ ‏إِنَّهَا ابْنَةُ أَخِي مِنْ الرَّضَاعَةِ فَإِنَّهُ يَحْرُمُ مِنْ الرَّضَاعِ مَا يَحْرُمُ مِنْ النَّسَبِ ‏","","",""],[2978,2978,"","আমরা আবেগ নিয়ে কথা বলেছি যে একটা ছেলের সাথে প্রতারণা করা নিয়ে আমরা খুশি হয়েছি। আর সে গর্ভবতী, আমি তোমার লর্ডশিপের জন্য প্রার্থনা করবো, তার কাছে প্রার্থনা করো আর তার কাছে প্রার্থনা করো তাকে আত্মসমর্পণ করা যে সে দুই ডজন ডলার খেয়ে ফেলবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏غَشِيَ ‏ ‏امْرَأَتَهُ وَهِيَ حَائِضٌ فَسَأَلَ عَنْ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُ أَنْ يَتَصَدَّقَ بِدِينَارٍ أَوْ نِصْفِ دِينَارٍ ‏","","",""],[2979,2979,"","আমরা আবেগ নিয়ে কথা বলেছি যে আমরা একটা জাতি সন্তান দিয়ে ঘুমাতে সাহায্য করতে পেরে আনন্দিত। ঈশ্বর তাঁর জন্য প্রার্থনা করেন এবং তিনি তার উপহার হিসেবে তাকে নেতৃত্ব প্রদান করবেন তার বমির মধ্যে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَائِدُ فِي هِبَتِهِ كَالْعَائِدِ فِي قَيْئِهِ ‏","","",""],[2980,2980,"","আমরা একটি নির্দিষ্ট আবেগ নিয়ে কথা বলেছি, আমরা একটি নির্দিষ্ট ভূমিকার জন্য ভাল করেছি যা হারমোনিয়ান যুদ্ধের উপর নির্মিত। আমরা ঈশ্বর তার প্রার্থনা করার জন্য এবং তাকে রক্ষা করতে বলা হয়েছে। প্রভু, ঈশ্বর কোন মহান দেবতা নেই।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَيَزِيدَ بْنِ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْعَالِيَةِ الرِّيَاحِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقُولُ عِنْدَ الْكَرْبِ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَوَاتِ وَالْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏رَبُّ السَّمَوَاتِ السَّبْعِ وَرَبُّ الْعَرْشِ الْكَرِيمِ ‏","","",""],[2981,2981,"","ঈশ্বর তাকে শিক্ষা দিয়েছেন এবং মরূদ্যাসকে পাওয়া গেলে তার প্রতি বশ্যতা দেখাতে হবে । আমি কেঁদেছি ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَقَّتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏وَلِأَهْلِ ‏ ‏الشَّامِ ‏ ‏الْجُحْفَةَ ‏ ‏وَلِأَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَرْنَ ‏ ‏وَلِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏يَلَمْلَمَ ‏ ‏قَالَ هُنَّ لَهُمْ وَلِمَنْ أَتَى عَلَيْهِنَّ مِمَّنْ سِوَاهُمْ مِمَّنْ أَرَادَ الْحَجَّ وَالْعُمْرَةَ ثُمَّ مِنْ حَيْثُ بَدَأَ حَتَّى بَلَغَ ذَلِكَ أَهْلُ ‏ ‏مَكَّةَ ‏","","",""],[2982,2982,"","আমি কথা বলার নিয়ম নিয়ে কথা বলেছি, বাবা ভালো করেই একজন যাজকের ছেলে হয়ে আছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর আমি যখন পারি তখন আমি তা রোধ করতে পারবো এক বছর পার হয়ে গেছে, রক্ত তাকে এটা করতে দিয়েছে, তারপর তাকে যেতে দাও, তাকে নিয়ে যেতে দাও, সে সুখী হবে না।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حَسَّانَ الْأَعْرَجَ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏فَأُتِيَ بِبَدَنَةٍ فَأَشْعَرَ صَفْحَةَ ‏ ‏سَنَامِهَا ‏ ‏الْأَيْمَنِ ثُمَّ سَلَتَ الدَّمَ عَنْهَا وَقَلَّدَهَا نَعْلَيْنِ ثُمَّ دَعَا بِرَاحِلَتِهِ فَرَكِبَهَا فَلَمَّا اسْتَوَتْ بِهِ عَلَى ‏ ‏الْبَيْدَاءِ ‏ ‏أَهَلَّ بِالْحَجِّ ‏","","",""],[2983,2983,"","আমরা একটি প্রথা তৈরি করা একটি প্রথা এবং একটি প্রয়োজন যে একটি স্বর্গের জন্য আমাকে একটি স্বর্গ তৈরি করা প্রয়োজন যে আপনার জীবন সৃষ্টি করা হয়েছে, হয়তো তিনি তার জন্য ঈশ্বরের প্রার্থনা এবং তিনি তিনি তিনি বলতে হবে এটা আর সে প্রতারণা করবে আর বিক্রি করবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هَذِهِ وَهَذِهِ سَوَاءٌ ‏ ‏يَعْنِي الْخِنْصَرَ وَالْإِبْهَامَ ‏","","",""],[2984,2984,"","আমরা আবেগ- আকাঙ্ক্ষার কথা বলেছি এবং আমাকে নিষ্ঠুরতার একটি খেলা দেখাতে সাহায্য করেছে। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং ঈশ্বরের এই ভয়ানক ঘটনার প্রতিবাদ করেছেন। পুরুষ আর পুরুষের অমানুষের কামনা...","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْمُتَشَبِّهِينَ مِنْ الرِّجَالِ بِالنِّسَاءِ وَالْمُتَشَبِّهَاتِ مِنْ النِّسَاءِ بِالرِّجَالِ ‏","","",""],[2985,2985,"","আমরা একটা প্রথা নিয়ে কথা বলেছি... ...যে কিনা একটা পাহাড়ের কথা শুনেছে, আমি তাকে জিজ্ঞেস করবো যে সে একটা ছেলে যে তাকে মারতে চায় প্রার্থনার সময়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ قَوْلِ الرَّجُلِ بِإِصْبَعِهِ ‏ ‏يَعْنِي هَكَذَا فِي الصَّلَاةِ قَالَ ذَاكَ الْإِخْلَاصُ ‏","","",""],[2986,2986,"","( মথি ২৪: ১৪) তিনি বলেছিলেন যে, একজন যাজকের ছেলে হয়তো ঈশ্বরকে উদ্ধার করার আদেশ দেওয়া হয়েছিল এবং তার কাছে সমর্পণ করা হয়েছিল যদিও তিনি সেখানে থাকতেন ।","‏ ‏وَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏لَقَدْ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالسِّوَاكِ حَتَّى ظَنَنَّا أَنَّهُ سَيُنْزَلُ عَلَيْهِ فِيهِ ‏","","",""],[2987,2987,"","সে আমাকে ভগবানের কাছে প্রার্থনা করতে দেখেছে... ...আর সে আমার লাইনও খুঁজে পাবে.","‏ ‏وَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْجُدُ حَتَّى يُرَى بَيَاضُ إِبْطَيْهِ ‏","","",""],[2988,2988,"","আমরা আবেগ আর আবেগ নিয়ে কথা বলেছি... ...যে কিনা আমাকে বলেছিল সে একটা সাপ, সে আমাকে বিয়ারের কথা বলে খুশি করেছে যে কিনা ঈশ্বরের দোহাই দিয়ে ঈশ্বরকে পাঠালো, সে বলেছিল সে ফিরে যাবে আর সে যাওয়ার আগে ফোন করবে না। আমি তাদের সাথে বন্ধুত্ব করেছি। মহিলা বাহিরে গিয়ে তাকে মেরে ফেলে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏أَخْبَرَنِي ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ يَوْمَ أَضْحَى ‏ ‏أَوْ يَوْمَ فِطْرٍ قَالَ وَأَكْبَرُ ظَنِّي أَنَّهُ قَالَ يَوْمَ فِطْرٍ ‏ ‏فَصَلَّى رَكْعَتَيْنِ لَمْ يُصَلِّ قَبْلَهُمَا وَلَا بَعْدَهُمَا ثُمَّ أَتَى النِّسَاءَ وَمَعَهُ ‏ ‏بِلَالٌ ‏ ‏فَأَمَرَهُنَّ بِالصَّدَقَةِ فَجَعَلَتْ الْمَرْأَةُ ‏ ‏تُلْقِي ‏ ‏خُرْصَهَا ‏ ‏وَسِخَابَهَا ‏ ‏وَلَمْ يَشُكَّ ‏ ‏بَهْزٌ ‏ ‏قَالَ ‏ ‏يَوْمَ فِطْرٍ ‏ ‏وَقَالَ ‏ ‏صِخَابَهَا ‏","","",""],[2989,2989,"","আমরা চেষ্টা করেছি আমাকে সাহায্য করার চেষ্টা করার জন্য। একজন যাজক বলেছিলেন, তিনি তাকে বড় করেছেন। তাদের একজন ছিল ভাববাদী, যিনি তার শান্তি ছিল এবং তাকে তার অসঙ্গতি উদ্ধার করতে হয়েছিল। চিতাবাঘকে ঈশ্বরের কাছে না বলতে ভয় পেয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏وَعَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏رَفَعَهُ أَحَدُهُمَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏كَانَ يَدُسُّ فِي ‏ ‏فِي ‏ ‏فِرْعَوْنَ ‏ ‏الطِّينَ مَخَافَةَ أَنْ يَقُولَ لَا إِلَهَ إِلَّا اللَّهُ ‏","","",""],[2990,2990,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমার বাবার সাথে থাকা হৃদয়ের জন্য এনেছে। লর্ড তার জন্য প্রার্থনা করেছেন এবং আশ্বস্ত করেছেন যে তিনি তাকে কিছু না নিতে বলেছেন যা ডুবে গেছে। সে কথা বলার আগে, তুমি ভবিষ্যদ্বাণীর কথা বলেছিলে... ...আর সে ঈশ্বরের দোহাই চেয়ে আত্মসমর্পণ করতে চায়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا تَتَّخِذُوا شَيْئًا فِيهِ الرُّوحُ غَرَضًا ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏مِثْلَهُ قَالَ أَيْ ‏ ‏شُعْبَةُ ‏ ‏قُلْتَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2991,2991,"","আমরা সেই সময়ের প্রবলতা দেখে বাপ্তাইজিত হয়েছি... ...আমরা স্বপ্নের কথা শুনেছি... ...যে কথাগুলো আমি শুনেছি সূর্যর বাণী হচ্ছে, পিপপিপের ওয়াইন আর রং দিয়ে বানানো একটা ছেলে খুন করে যাতে মুক্ত হতে পারে মুক্ত হওয়ার জন্য মুক্ত হওয়ার জন্য মুক্ত হওয়ার জন্য মুক্ত মুক্ত হতে মুক্ত হিসাবে মুক্ত মুক্ত মুক্ত হতে মুক্ত হিসাবে ব্যবহৃত বিনামূল্যে মুক্ত করতে হবে। মুক্তির জন্য, ওয়াইনের জন্য।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْحَكَمِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏وَعَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏مَنْ سَرَّهُ أَنْ يُحَرِّمَ مَا حَرَّمَ اللَّهُ وَرَسُولُهُ فَلْيُحَرِّمْ النَّبِيذَ ‏","","",""],[2992,2992,"","আমরা আমাদের কামনা দ্বারা বাপ্তাইজিত হয়েছি... ...আমরা তোমাদের কথা শুনেছি... ...তার কথা শুনেছি, ঈশ্বরের কাছে প্রার্থনা করতে তিনি বলেছিলেন, তিনি তাকে চেনেন আর তিনি যে মাসগুলো বেঁচে থাকতে যাচ্ছেন.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْحَكَمِ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَمَّ الشَّهْرُ تِسْعٌ وَعِشْرُونَ ‏","","",""],[2993,2993,"","আমরা একটা বাসা তৈরি করেছি... ...যেটা আমি আমার ছেলেকে শোক পালন করতে দেব. আমি ঈশ্বরের কাছে প্রার্থনা করব, যে ছেলেকে নরকের আগুনে পরিণত করা হয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُشَاشٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَطَاءَ بْنَ أَبِي رَبَاحٍ ‏ ‏فَحَدَّثَ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ صِبْيَانَ ‏ ‏بَنِي هَاشِمٍ ‏ ‏وَضَعَفَتَهُمْ أَنْ يَتَحَمَّلُوا مِنْ ‏ ‏جَمْعٍ ‏ ‏بِلَيْلٍ ‏","","",""],[2994,2994,"","আমরা এক আবেগ দ্বারা বাপ্তাইজিত হয়েছি, যা আমাদের হৃদয়ের এক অনুভূতি এনে দিয়েছে, যা এক বিস্ময়কর পণ্ডিতের কাছ থেকে শোনা যাচ্ছে। সম্প্রদায়ের রস এবং কপটদের রস নিয়ে গঠিত দলের কথা ভুলে যান সকালের সূর্য।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُخَوَّلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُسْلِمًا الْبَطِينَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَقْرَأُ فِي صَلَاةِ الصُّبْحِ ‏ ‏الم تَنْزِيلُ السَّجْدَةَ ‏ ‏وَهَلْ أَتَى عَلَى الْإِنْسَانِ ‏ ‏وَفِي الْجُمُعَةِ بِسُورَةِ ‏ ‏الْجُمُعَةِ ‏ ‏وَالْمُنَافِقِينَ ‏","","",""],[2995,2995,"","আমরা আবেগ নিয়ে কথা বলেছি এবং আমাদের প্রয়োজনের কথা যে আমরা কি ঘটেছে তা নিয়ে কথা বলেছি। তাঁরা বলেছিলেন, প্রভু, আমরা একা তাদের হত্যা করতে বলছি। রাজনীতিবিদদের কাছে এটা পাস করে দাও।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏وَمَنْصُورٍ ‏ ‏عَنْ ‏ ‏ذَرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُمْ قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏إِنَّا نُحَدِّثُ أَنْفُسَنَا بِالشَّيْءِ لَأَنْ يَكُونَ أَحَدُنَا ‏ ‏حُمَمَةً ‏ ‏أَحَبُّ إِلَيْهِ مِنْ أَنْ يَتَكَلَّمَ بِهِ قَالَ فَقَالَ أَحَدُهُمَا الْحَمْدُ لِلَّهِ الَّذِي لَمْ يَقْدِرْ مِنْكُمْ إِلَّا عَلَى الْوَسْوَسَةِ ‏ ‏وَقَالَ ‏ ‏الْآخَرُ الْحَمْدُ لِلَّهِ الَّذِي رَدَّ أَمْرَهُ إِلَى الْوَسْوَسَةِ ‏","","",""],[2996,2996,"","আমরা আবেগ আর প্রয়োজনের কথা বলেছি... ...আমাদের একজন যাজকের উদ্দেশ্যে একটা রীতি তৈরি করা হয়েছে... ...আর আল্লাহকে বন্যা বইয়ে শহর থেকে উদ্ধার করতে হবে... ( ১ রাজাবলি ১১: ১ - ৩) কিন্তু, সেই পুত্র যদি তার সঙ্গে খারাপ ব্যবহার করতেন, তাহলে তিনি তার সঙ্গে খারাপ ব্যবহার করতেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏فِي رَمَضَانَ حِينَ فَتَحَ ‏ ‏مَكَّةَ ‏ ‏فَصَامَ حَتَّى أَتَى ‏ ‏عُسْفَانَ ‏ ‏ثُمَّ دَعَا ‏ ‏بِعُسٍّ ‏ ‏مِنْ شَرَابٍ ‏ ‏أَوْ إِنَاءٍ ‏ ‏فَشَرِبَ ‏ ‏فَكَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏مَنْ شَاءَ صَامَ وَمَنْ شَاءَ أَفْطَرَ ‏","","",""],[2997,2997,"","আমরা আবেগে বাপ্তাইজিত হয়েছি... ...আমার বাবার খারাপ আচরণের একটা রীতি নিয়ে... ...সে আমার খালার মাকে হুমকি দিয়েছে, ঈশ্বরের ইচ্ছার প্রধান, তাকে উদ্ধার করতে হবে। আমাদের বিষ আর আমি ভুল, আমি ঈশ্বরের কাছে নিজের অনুগ্রহের কথা বলছি... ...আর যদি আমার সাথে কিছু না থাকে তাহলে ঈশ্বর তাকে দিয়েছেন.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏أَهْدَتْ خَالَتِي ‏ ‏أُمُّ حُفَيْدٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمْنًا وَأَقِطًا وَأَضُبًّا ‏ ‏فَأَكَلَ مِنْ السَّمْنِ وَالْأَقِطِ وَتَرَكَ الْأَضُبَّ تَقَذُّرًا وَأُكِلَ عَلَى مَائِدَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَوْ كَانَ حَرَامًا مَا أُكِلَ عَلَى مَائِدَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2998,2998,"","আমরা এক নিষ্ঠুর ছেলেকে নিয়ে যে আবেগ নিয়ে এসেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং যদি তারা চুপ থাকে তাহলে শহর আত্মসমর্পণ করবে। তারা তাকে ভিডিও করে ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏فَإِذَا ‏ ‏الْيَهُودُ ‏ ‏قَدْ صَامُوا ‏ ‏يَوْمَ عَاشُورَاءَ ‏ ‏فَسَأَلَهُمْ عَنْ ذَلِكَ فَقَالُوا هَذَا الْيَوْمُ الَّذِي ظَهَرَ فِيهِ ‏ ‏مُوسَى ‏ ‏عَلَى ‏ ‏فِرْعَوْنَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَصْحَابِهِ ‏ ‏أَنْتُمْ أَوْلَى ‏ ‏بِمُوسَى ‏ ‏مِنْهُمْ فَصُومُوهُ ‏","","",""],[2999,2999,"","আমরা আবেগ নিয়ে কথা বলেছি, আমরা আমার বাবার খারাপ কাজ নিয়ে এসেছি একটা কুত্তার বাচ্চাকে সাহায্য করার জন্য। ঈশ্বর তোমার সন্তানদের অনুরোধ করেছেন যেন তারা বলে যে ঈশ্বর তাদের কাজ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏سُئِلَ عَنْ أَوْلَادِ الْمُشْرِكِينَ فَقَالَ اللَّهُ إِذْ خَلَقَهُمْ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ ‏","","",""],[3000,3000,"","আমরা আবেগ আর প্রয়োজনের কথা বলেছি একটা ছেলের জন্য ভালবাসা নিয়ে। সে বলল সে ঈশ্বরের কাছে প্রার্থনা করতো আর ডাক্তার আর বেচারাদের ছেড়ে দিত।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏يَحْيَى أَبِي عُمَرَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالنَّقِيرِ ‏","","",""]];
